function updateJournalModeButtons() {
  const modeToggle = $('.journal-mode-toggle');
  if (modeToggle) modeToggle.hidden = Boolean(teamCalendarController?.isTeamMode) || calendarView !== 'day';
  const filters = $('.booking-filters');
  if (filters) filters.hidden = Boolean(teamCalendarController?.isTeamMode) || calendarView !== 'day' || journalMode === 'timeline';
  $$('[data-journal-mode]').forEach(button => {
    const active = button.dataset.journalMode === journalMode;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
}

function parseLocalIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ''))) return null;
  const date = new Date(`${value}T12:00:00`);
  return Number.isNaN(date.getTime()) || localIsoDate(date) !== value ? null : date;
}

function restoreSelectedDate() {
  const requested = new URLSearchParams(window.location.search).get('date');
  if (parseLocalIsoDate(requested)) return requested;
  try {
    if (localStorage.getItem(SCHEDULE_FOLLOW_TODAY_KEY) === 'true') return businessTodayIso();
    const stored = localStorage.getItem(SCHEDULE_DATE_KEY);
    if (parseLocalIsoDate(stored)) return stored;
  } catch {}
  return businessTodayIso();
}

function restoreScheduleFilter() {
  const requested = new URLSearchParams(window.location.search).get('records');
  if (['day', 'upcoming', 'all'].includes(requested)) return requested;
  try {
    const stored = localStorage.getItem(SCHEDULE_FILTER_KEY);
    if (['day', 'upcoming', 'all'].includes(stored)) return stored;
  } catch {}
  return 'day';
}

function restoreCalendarView() {
  const requested = new URLSearchParams(window.location.search).get('range');
  if (['day', 'week', 'month'].includes(requested)) return requested;
  try {
    const stored = localStorage.getItem(CALENDAR_VIEW_KEY);
    if (['day', 'week', 'month'].includes(stored)) return stored;
  } catch {}
  return 'day';
}

function restoreJournalMode() {
  const requested = new URLSearchParams(window.location.search).get('journal');
  if (['timeline', 'list'].includes(requested)) return requested;
  try {
    const stored = localStorage.getItem(JOURNAL_MODE_KEY);
    if (['timeline', 'list'].includes(stored)) return stored;
  } catch {}
  return 'timeline';
}

function rememberSelectedDate(followToday = selectedDate === businessTodayIso()) {
  try {
    localStorage.setItem(SCHEDULE_DATE_KEY, selectedDate);
    localStorage.setItem(SCHEDULE_FOLLOW_TODAY_KEY, String(followToday));
  } catch {}
}

function weekStartFor(date) {
  const start = new Date(date);
  const daysFromMonday = (start.getDay() + 6) % 7;
  start.setDate(start.getDate() - daysFromMonday);
  return start;
}

function calendarRange(view = calendarView, value = selectedDate) {
  const selected = parseLocalIsoDate(value) || parseLocalIsoDate(businessTodayIso());
  if (view === 'week') {
    const start = weekStartFor(selected);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return { start:localIsoDate(start), end:localIsoDate(end) };
  }
  if (view === 'month') {
    const start = new Date(selected.getFullYear(), selected.getMonth(), 1, 12);
    const end = new Date(selected.getFullYear(), selected.getMonth() + 1, 0, 12);
    return { start:localIsoDate(start), end:localIsoDate(end) };
  }
  const iso = localIsoDate(selected);
  return { start:iso, end:iso };
}

function updateCalendarViewControls() {
  $$('[data-calendar-view]').forEach(button => {
    const active = button.dataset.calendarView === calendarView;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  const strip = $('#dateStrip');
  if (strip) strip.hidden = calendarView !== 'day' || currentFilter !== 'day';
  const filters = $('.booking-filters');
  if (filters) filters.hidden = Boolean(teamCalendarController?.isTeamMode) || calendarView !== 'day' || journalMode === 'timeline';
  const labels = calendarView === 'day'
    ? ['Показать предыдущий день', 'Показать следующий день']
    : calendarView === 'week'
      ? ['Показать предыдущую неделю', 'Показать следующую неделю']
      : ['Показать предыдущий месяц', 'Показать следующий месяц'];
  const mobileDayCarousel = calendarView === 'day' && matchMedia('(max-width:760px)').matches;
  $$('[data-date-shift]').forEach(button => {
    const direction = Number(button.dataset.dateShift) < 0 ? 0 : 1;
    const carouselWeek = mobileDayCarousel && Boolean(button.closest('.date-strip-frame'));
    button.setAttribute('aria-label', carouselWeek
      ? (direction ? 'Показать следующую неделю' : 'Показать предыдущую неделю')
      : labels[direction]);
  });
  updateJournalModeButtons();
  updateBookingQueryTools();
}

function setCalendarView(view) {
  const next = ['day', 'week', 'month'].includes(view) ? view : 'day';
  if (next === calendarView && currentFilter === 'day') return;
  calendarView = next;
  currentFilter = 'day';
  try {
    localStorage.setItem(CALENDAR_VIEW_KEY, calendarView);
    localStorage.setItem(SCHEDULE_FILTER_KEY, currentFilter);
  } catch {}
  $$('[data-filter]').forEach(button => {
    const active = button.dataset.filter === currentFilter;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  updateCalendarViewControls();
  syncScheduleContextHistory();
  renderDateStrip();
  renderBookings();
}

function selectScheduleDate(value) {
  const date = parseLocalIsoDate(value);
  if (!date) return;
  const nextDate = localIsoDate(date);
  selectedDate = nextDate;
  rememberSelectedDate();
  renderDateStrip({ instantCenter:true });
  setFilter('day', { render:false });
  renderSelectedDateTitle(calendarView);
  requestAnimationFrame(() => {
    if (selectedDate === nextDate) renderBookings();
  });
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  if (userId) void loadAutomaticBookingBreaks(nextDate, userId, generation).then(result => {
    if (result.ok && selectedDate === nextDate && sessionIsCurrent(userId, generation)) renderBookings();
  });
}

function shiftScheduleDate(direction, { weekStep = false } = {}) {
  const date = parseLocalIsoDate(selectedDate) || parseLocalIsoDate(businessTodayIso());
  if (calendarView === 'month') {
    const selectedDay = date.getDate();
    date.setDate(1);
    date.setMonth(date.getMonth() + direction);
    const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0, 12).getDate();
    date.setDate(Math.min(selectedDay, lastDay));
  } else {
    const dayStep = calendarView === 'week' || (calendarView === 'day' && weekStep) ? 7 : 1;
    date.setDate(date.getDate() + direction * dayStep);
  }
  selectScheduleDate(localIsoDate(date));
}

function refreshBusinessDay() {
  const today = businessTodayIso();
  if (today === renderedBusinessToday) return;
  renderedBusinessToday = today;
  try {
    if (localStorage.getItem(SCHEDULE_FOLLOW_TODAY_KEY) === 'true') {
      selectedDate = today;
      rememberSelectedDate(true);
    }
  } catch {}
  renderDateStrip();
  renderBookingData();
}

function updateDateStripEmphasis(dateStrip) {
  if (!dateStrip) return;
  const buttons = [...dateStrip.querySelectorAll('[data-booking-date]')];
  const activeIndex = buttons.findIndex(button => button.classList.contains('active'));
  buttons.forEach((button, index) => {
    const distance = activeIndex < 0 ? 3 : Math.min(3, Math.abs(index - activeIndex));
    button.dataset.dateDistance = String(distance);
  });
}

function centerDateStripSelection(dateStrip, options = {}) {
  if (!dateStrip || dateStrip.scrollWidth <= dateStrip.clientWidth) return;
  const active = dateStrip.querySelector('[data-booking-date].active');
  if (!active) return;
  const stripRect = dateStrip.getBoundingClientRect();
  const activeRect = active.getBoundingClientRect();
  const activeContentLeft = activeRect.left - stripRect.left + dateStrip.scrollLeft;
  const target = activeContentLeft - (dateStrip.clientWidth - activeRect.width) / 2;
  const nextLeft = Math.max(0, Math.min(dateStrip.scrollWidth - dateStrip.clientWidth, target));
  const instant = options.instant === true;
  const smooth = !instant && options.smooth === true && !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  dateStrip.dataset.programmaticCenterUntil = String(Date.now() + (instant ? 520 : smooth ? 460 : 100));
  if (smooth && typeof dateStrip.scrollTo === 'function') dateStrip.scrollTo({ left:nextLeft, behavior:'smooth' });
  else {
    const inlineScrollBehavior = dateStrip.style.scrollBehavior;
    dateStrip.style.scrollBehavior = 'auto';
    dateStrip.scrollLeft = nextLeft;
    dateStrip.style.scrollBehavior = inlineScrollBehavior;
  }
}

function bindDateStripResizeCentering(dateStrip) {
  if (!dateStrip || dateStrip.dataset.resizeObserverBound) return;
  let previousWidth = dateStrip.clientWidth;
  const recenterForWidth = widthValue => {
    const width = Math.round(widthValue || dateStrip.clientWidth);
    if (!width || Math.abs(width - previousWidth) < 1) return;
    previousWidth = width;
    requestAnimationFrame(() => centerDateStripSelection(dateStrip));
    window.setTimeout(() => centerDateStripSelection(dateStrip), 220);
  };
  if ('ResizeObserver' in window) new ResizeObserver(entries => recenterForWidth(entries[0]?.contentRect?.width)).observe(dateStrip);
  window.addEventListener('resize', () => recenterForWidth(dateStrip.clientWidth), { passive:true });
  dateStrip.dataset.resizeObserverBound = 'true';
}

function renderDateStrip({ forceCenter = false, instantCenter = false } = {}) {
  const dateStrip = $('#dateStrip');
  if (!dateStrip) return;
  const todayIso = businessTodayIso();
  const today = parseLocalIsoDate(todayIso);
  const selected = parseLocalIsoDate(selectedDate) || today;
  const mobileCenteredRange = window.matchMedia('(max-width: 760px)').matches;
  const weekStart = weekStartFor(selected);
  const todayWeekStart = weekStartFor(today);
  const rangeStart = mobileCenteredRange
    ? new Date(selected)
    : new Date(todayWeekStart < weekStart ? todayWeekStart : weekStart);
  const rangeEnd = mobileCenteredRange
    ? new Date(selected)
    : new Date(todayWeekStart > weekStart ? todayWeekStart : weekStart);
  rangeStart.setDate(rangeStart.getDate() - (mobileCenteredRange ? 120 : 28));
  rangeEnd.setDate(rangeEnd.getDate() + (mobileCenteredRange ? 120 : 62));
  const rangeStartIso = localIsoDate(rangeStart);
  const rangeEndIso = localIsoDate(rangeEnd);
  const rangeDays = Math.round((Date.UTC(rangeEnd.getFullYear(), rangeEnd.getMonth(), rangeEnd.getDate()) - Date.UTC(rangeStart.getFullYear(), rangeStart.getMonth(), rangeStart.getDate())) / 86400000) + 1;
  const rangeMode = mobileCenteredRange ? 'inertial' : 'extended';
  const currentRangeContainsSelection = dateStrip.dataset.rangeStart <= selectedDate && selectedDate <= dateStrip.dataset.rangeEnd;
  const currentRangeContainsToday = dateStrip.dataset.rangeStart <= todayIso && todayIso <= dateStrip.dataset.rangeEnd;
  const rebuildStrip = dateStrip.dataset.rangeMode !== rangeMode
    || (mobileCenteredRange ? !currentRangeContainsSelection : !currentRangeContainsSelection || !currentRangeContainsToday)
    || dateStrip.dataset.today !== todayIso;
  const previousSelectedDate = dateStrip.dataset.selectedDate || '';
  const selectionChanged = previousSelectedDate !== selectedDate;
  if (rebuildStrip) {
    const weekday = new Intl.DateTimeFormat('ru-RU', { weekday: 'short' });
    dateStrip.innerHTML = Array.from({ length: rangeDays }, (_, index) => {
      const date = new Date(rangeStart);
      date.setDate(rangeStart.getDate() + index);
      const iso = localIsoDate(date);
      const label = iso === todayIso ? 'Сегодня' : weekday.format(date).replace('.', '');
      const fullDate = date.toLocaleDateString('ru-RU', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
      return `<button type="button" data-booking-date="${iso}" aria-label="${fullDate}"><span>${label}</span><strong>${date.getDate()}</strong><small>${date.toLocaleDateString('ru-RU', { month: 'short' }).replace('.', '')}</small></button>`;
    }).join('');
    dateStrip.dataset.rangeMode = rangeMode;
    dateStrip.dataset.rangeStart = rangeStartIso;
    dateStrip.dataset.rangeEnd = rangeEndIso;
    dateStrip.dataset.today = todayIso;
  }
  dateStrip.querySelectorAll('[data-booking-date]').forEach(button => {
    const active = button.dataset.bookingDate === selectedDate;
    const isToday = button.dataset.bookingDate === todayIso;
    button.classList.toggle('active', active);
    button.classList.toggle('is-today', isToday);
    button.setAttribute('aria-pressed', String(active));
    if (isToday) button.setAttribute('aria-current', 'date');
    else button.removeAttribute('aria-current');
  });
  updateDateStripEmphasis(dateStrip);
  dateStrip.dataset.selectedDate = selectedDate;
  const picker = $('#scheduleDatePicker');
  if (picker) picker.value = selectedDate;
  const todayButton = $('[data-date-today]');
  if (todayButton) {
    const current = selectedDate === todayIso && calendarView === 'day' && currentFilter === 'day';
    todayButton.hidden = false;
    todayButton.classList.toggle('is-current', current);
    todayButton.setAttribute('aria-pressed', String(current));
  }
  if (rebuildStrip || selectionChanged || forceCenter) {
    const fixedMobileCenter = mobileCenteredRange;
    const immediateCenter = instantCenter || fixedMobileCenter;
    const smoothSelection = !immediateCenter && selectionChanged && !rebuildStrip && Boolean(previousSelectedDate);
    const center = () => centerDateStripSelection(dateStrip, { smooth:smoothSelection, instant:immediateCenter });
    if (immediateCenter) {
      center();
      if (fixedMobileCenter) requestAnimationFrame(center);
    } else requestAnimationFrame(center);
    if (!immediateCenter) window.setTimeout(center, 220);
  }
  bindDateStripResizeCentering(dateStrip);
  if (!dateStrip.dataset.scrollInteractionsBound) {
    let wheelTarget = dateStrip.scrollLeft;
    let wheelFrame = 0;
    let dragPointerId = null;
    let dragStartX = 0;
    let dragStartScrollLeft = 0;
    let hasDragged = false;
    let suppressClick = false;
    let touchStartX = null;
    let touchStartY = null;
    let touchAnchorX = null;
    let touchIntent = '';
    let touchMoved = false;
    const mobileDateStep = () => {
      const buttons = [...dateStrip.querySelectorAll('[data-booking-date]')];
      const activeIndex = buttons.findIndex(button => button.classList.contains('active'));
      const active = buttons[activeIndex];
      const neighbor = buttons[activeIndex + 1] || buttons[activeIndex - 1];
      if (!active || !neighbor) return 36;
      const activeRect = active.getBoundingClientRect();
      const neighborRect = neighbor.getBoundingClientRect();
      const centerDistance = Math.abs((neighborRect.left + neighborRect.right - activeRect.left - activeRect.right) / 2);
      return Math.max(30, Math.min(52, centerDistance * .72));
    };
    const advanceMobileDateGesture = clientX => {
      if (!Number.isFinite(clientX) || touchAnchorX === null) return 0;
      const delta = clientX - touchAnchorX;
      const step = mobileDateStep();
      const count = Math.trunc(Math.abs(delta) / step);
      if (!count) return 0;
      const direction = delta < 0 ? 1 : -1;
      touchAnchorX += (delta < 0 ? -1 : 1) * count * step;
      shiftScheduleDate(direction * count);
      touchMoved = true;
      return count;
    };
    const clampScroll = value => Math.max(0, Math.min(dateStrip.scrollWidth - dateStrip.clientWidth, value));
    const stopWheelAnimation = () => {
      if (wheelFrame) cancelAnimationFrame(wheelFrame);
      wheelFrame = 0;
      wheelTarget = dateStrip.scrollLeft;
    };
    const animateWheel = () => {
      const distance = wheelTarget - dateStrip.scrollLeft;
      if (Math.abs(distance) < 0.75) {
        dateStrip.scrollLeft = wheelTarget;
        wheelFrame = 0;
        return;
      }
      dateStrip.scrollLeft += distance * 0.24;
      wheelFrame = requestAnimationFrame(animateWheel);
    };
    dateStrip.addEventListener('wheel', event => {
      if (window.matchMedia('(max-width: 760px)').matches) return;
      const rawDelta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
      const unit = event.deltaMode === 1 ? 22 : event.deltaMode === 2 ? dateStrip.clientWidth : 1;
      const delta = Math.max(-320, Math.min(320, rawDelta * unit * 1.1));
      const nextTarget = clampScroll(wheelTarget + delta);
      if (!delta || (nextTarget === wheelTarget && Math.abs(wheelTarget - dateStrip.scrollLeft) < 1)) return;
      event.preventDefault();
      wheelTarget = nextTarget;
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        dateStrip.scrollLeft = wheelTarget;
        return;
      }
      if (!wheelFrame) wheelFrame = requestAnimationFrame(animateWheel);
    }, { passive:false });
    dateStrip.addEventListener('pointerdown', event => {
      if (event.pointerType !== 'mouse' || event.button !== 0) return;
      stopWheelAnimation();
      dragPointerId = event.pointerId;
      dragStartX = event.clientX;
      dragStartScrollLeft = dateStrip.scrollLeft;
      hasDragged = false;
    });
    dateStrip.addEventListener('pointermove', event => {
      if (event.pointerId !== dragPointerId) return;
      const delta = event.clientX - dragStartX;
      if (!hasDragged && Math.abs(delta) < 4) return;
      if (window.matchMedia('(max-width: 760px)').matches) {
        const step = mobileDateStep();
        const count = Math.trunc(Math.abs(delta) / step);
        if (!count) return;
        hasDragged = true;
        dragStartX += (delta < 0 ? -1 : 1) * count * step;
        event.preventDefault();
        shiftScheduleDate(delta < 0 ? count : -count);
        return;
      }
      if (!hasDragged) {
        hasDragged = true;
        dateStrip.setPointerCapture?.(event.pointerId);
        dateStrip.classList.add('is-dragging');
      }
      event.preventDefault();
      dateStrip.scrollLeft = clampScroll(dragStartScrollLeft - delta);
      wheelTarget = dateStrip.scrollLeft;
    });
    const finishDrag = event => {
      if (event.pointerId !== dragPointerId) return;
      suppressClick = hasDragged;
      hasDragged = false;
      dragPointerId = null;
      dateStrip.classList.remove('is-dragging');
      if (dateStrip.hasPointerCapture?.(event.pointerId)) dateStrip.releasePointerCapture(event.pointerId);
      if (suppressClick && window.matchMedia('(max-width: 760px)').matches) centerDateStripSelection(dateStrip, { instant:true });
    };
    dateStrip.addEventListener('pointerup', finishDrag);
    dateStrip.addEventListener('pointercancel', finishDrag);
    dateStrip.addEventListener('touchstart', event => {
      if (event.touches.length !== 1) return;
      dateStrip.dataset.programmaticCenterUntil = '0';
      touchStartX = event.touches[0].clientX;
      touchStartY = event.touches[0].clientY;
      touchAnchorX = touchStartX;
      touchIntent = '';
      touchMoved = false;
    }, { passive:true });
    dateStrip.addEventListener('touchmove', event => {
      if (touchStartX === null || event.touches.length !== 1 || !window.matchMedia('(max-width: 760px)').matches) return;
      const touch = event.touches[0];
      const deltaX = touch.clientX - touchStartX;
      const deltaY = touch.clientY - touchStartY;
      if (!touchIntent && Math.max(Math.abs(deltaX), Math.abs(deltaY)) >= 6) {
        touchIntent = Math.abs(deltaX) > Math.abs(deltaY) * 1.15 ? 'horizontal' : 'vertical';
      }
      if (touchIntent !== 'horizontal') return;
      event.preventDefault();
      advanceMobileDateGesture(touch.clientX);
    }, { passive:false });
    dateStrip.addEventListener('touchend', event => {
      const touch = event.changedTouches[0];
      if (touchIntent === 'horizontal' && touch && !touchMoved && touchAnchorX !== null && Math.abs(touch.clientX - touchAnchorX) >= 22) {
        shiftScheduleDate(touch.clientX < touchAnchorX ? 1 : -1);
        touchMoved = true;
      }
      const handled = touchIntent === 'horizontal' && touchMoved;
      touchStartX = null;
      touchStartY = null;
      touchAnchorX = null;
      touchIntent = '';
      touchMoved = false;
      if (!handled) return;
      suppressClick = true;
      event.preventDefault();
      centerDateStripSelection(dateStrip, { instant:true });
    }, { passive:false });
    dateStrip.addEventListener('touchcancel', () => {
      touchStartX = null;
      touchStartY = null;
      touchAnchorX = null;
      touchIntent = '';
      touchMoved = false;
    }, { passive:true });
    dateStrip.addEventListener('click', event => {
      if (!suppressClick) return;
      suppressClick = false;
      event.preventDefault();
      event.stopImmediatePropagation();
    }, true);
    dateStrip.addEventListener('scroll', () => {
      if (!wheelFrame && dragPointerId === null) wheelTarget = dateStrip.scrollLeft;
    }, { passive:true });
    dateStrip.dataset.scrollInteractionsBound = 'true';
  }
  updateCalendarViewControls();
}

function bookingCountWord(count) {
  const absolute = Math.abs(Number(count) || 0) % 100;
  const last = absolute % 10;
  if (absolute > 10 && absolute < 20) return 'записей';
  if (last === 1) return 'запись';
  if (last >= 2 && last <= 4) return 'записи';
  return 'записей';
}

function nextBookingSummaryDate(todayIso) {
  const [year, month, day] = String(todayIso || '').split('-').map(Number);
  const next = new Date(Date.UTC(year, month - 1, day + 1));
  return Number.isFinite(next.getTime()) ? next.toISOString().slice(0, 10) : '';
}

function bookingSummaryStats(items, todayIso, isBlock = isScheduleBlock) {
  const tomorrowIso = nextBookingSummaryDate(todayIso);
  const active = (Array.isArray(items) ? items : [])
    .filter(item => item?.status !== 'cancelled' && !isBlock(item));
  return {
    todayCount:active.filter(item => item.booking_date === todayIso).length,
    tomorrowCount:active.filter(item => item.booking_date === tomorrowIso).length,
    upcomingCount:active.filter(item => item.booking_date >= todayIso).length
  };
}

function updateBookingStats() {
  const today = businessTodayIso();
  const { todayCount, tomorrowCount, upcomingCount } = bookingSummaryStats(bookingSourceItems(), today);
  $('#todayBookingsCount').textContent = String(todayCount);
  $('#tomorrowBookingsCount').textContent = String(tomorrowCount);
  $('#newBookingsCount').textContent = String(upcomingCount);
  $('#todayBookingsLabel').textContent = 'сегодня';
  $('#tomorrowBookingsLabel').textContent = 'завтра';
  $('#upcomingBookingsLabel').textContent = 'впереди';
  $('.dashboard-summary')?.setAttribute('aria-label', `${todayCount} сегодня, ${tomorrowCount} завтра, Всего впереди — ${upcomingCount}`);
  const sidebarBadge = $('#newBookingsBadge');
  if (sidebarBadge) {
    sidebarBadge.textContent = String(upcomingCount);
    sidebarBadge.hidden = true;
  }
}

function filteredBookings() {
  const today = businessTodayIso();
  const items = bookingSourceItems();
  if (currentFilter === 'all') return items;
  if (currentFilter === 'upcoming') return items.filter(item => item.status !== 'cancelled' && item.booking_date >= today);
  return items.filter(item => item.status !== 'cancelled' && item.booking_date === selectedDate);
}

function bookingQueryIsActive() {
  return Boolean(bookingSearchQuery.trim()) || bookingStatusFilter !== 'all' || bookingSourceFilter !== 'all' || Boolean(bookingAnalyticsFilter) || Boolean(bookingAnalyticsScope);
}

function updateBookingQueryTools() {
  const tools = $('#bookingQueryTools');
  if (!tools) return;
  tools.hidden = Boolean(teamCalendarController?.isTeamMode) || currentFilter === 'day' || calendarView !== 'day';
  const reset = $('#bookingQueryReset');
  if (reset) reset.hidden = !bookingQueryIsActive();
  const sourceChip = $('#bookingSourceFilterChip');
  if (sourceChip) {
    const labels = { online:'Онлайн', manual:'Мастером', unknown:'Без данных' };
    sourceChip.hidden = bookingSourceFilter === 'all';
    sourceChip.textContent = bookingSourceFilter === 'all' ? '' : `Создано: ${labels[bookingSourceFilter] || bookingSourceFilter} ×`;
  }
  const analyticsChip = $('#bookingAnalyticsFilterChip');
  if (analyticsChip) {
    const label = String(bookingAnalyticsScope?.label || '').trim();
    analyticsChip.hidden = !label;
    analyticsChip.textContent = label ? `← Статистика · ${label}` : '';
    if (label) analyticsChip.setAttribute('aria-label', `Вернуться к тепловой карте. Сейчас показаны записи: ${label}`);
    else analyticsChip.removeAttribute('aria-label');
  }
}

function applyBookingQuery(items) {
  if (currentFilter === 'day') return items;
  const query = bookingSearchQuery.trim().toLocaleLowerCase('ru-RU');
  const queryDigits = query.replace(/\D/g, '');
  return items.filter(item => {
    if (bookingStatusFilter !== 'all' && bookingStatusClass(item) !== bookingStatusFilter) return false;
    if (bookingSourceFilter !== 'all' && reportBookingSource(item) !== bookingSourceFilter) return false;
    if (!bookingMatchesAnalyticsScope(item)) return false;
    if (bookingAnalyticsFilter === 'debt' && !(reportDebtAmount(item) > 0)) return false;
    if (bookingAnalyticsFilter === 'lost' && !(item.status === 'cancelled' || bookingOutcome(item).visit_status === 'no_show')) return false;
    if (bookingAnalyticsFilter === 'payment-unknown' && !globalThis.MinutaReportReconciliation.paymentUnknown(item, bookingOutcome(item))) return false;
    if (!query) return true;
    const text = [item.client_name, item.client_phone, serviceName(item.services?.name || ''), ...bookingSession(item).map(entry => entry.title), bookingDisplayNote(item)]
      .filter(Boolean)
      .join(' ')
      .toLocaleLowerCase('ru-RU');
    if (text.includes(query)) return true;
    return Boolean(queryDigits) && String(item.client_phone || '').replace(/\D/g, '').includes(queryDigits);
  });
}

function minutesFromTime(value) {
  const [hours, minutes] = String(value || '00:00').slice(0, 5).split(':').map(Number);
  return (hours * 60) + minutes;
}

function timeFromMinutes(value) {
  const normalized = ((Math.round(Number(value) || 0) % 1440) + 1440) % 1440;
  return `${String(Math.floor(normalized / 60)).padStart(2, '0')}:${String(normalized % 60).padStart(2, '0')}`;
}

function timelineBounds(items) {
  const date = new Date(`${selectedDate}T12:00:00`);
  const weekday = ((date.getDay() + 6) % 7) + 1;
  const schedule = scheduleRows.find(row => Number(row.weekday) === weekday);
  let start = schedule?.enabled === false ? 10 * 60 : minutesFromTime(schedule?.start_time || '10:00');
  let end = schedule?.enabled === false ? 20 * 60 : minutesFromTime(schedule?.end_time || '20:00');
  items.forEach(item => {
    const itemStart = minutesFromTime(item.booking_time);
    const itemEnd = itemStart + Number(item.duration_minutes || item.services?.duration_minutes || 60);
    start = Math.min(start, Math.floor(itemStart / 60) * 60);
    end = Math.max(end, Math.ceil(itemEnd / 60) * 60);
  });
  if (end <= start) end = start + 60;
  return { start, end };
}

function scheduleStepForDate(dateIso) {
  const date = parseLocalIsoDate(dateIso);
  if (!date) return 5;
  const weekday = ((date.getDay() + 6) % 7) + 1;
  const row = scheduleRows.find(item => Number(item.weekday) === weekday);
  const step = Number(row?.slot_interval_minutes || 5);
  return Number.isInteger(step) && step >= 5 && step <= 60 ? step : 5;
}

const NEW_BOOKING_GRID_MINUTES = 30;

function isNewBookingGridTime(value) {
  return /^([01]\d|2[0-3]):(?:00|30)$/.test(String(value || ''));
}

function newBookingGridSlots(slots) {
  return [...new Set((slots || []).map(time => String(time || '').slice(0, 5)).filter(isNewBookingGridTime))].sort();
}

function syncSlotIntervalOptions(value = $('#slotInterval')?.value) {
  $$('.slot-step-options [data-slot-interval]').forEach(button => {
    button.setAttribute('aria-selected', String(button.dataset.slotInterval === String(value || '5')));
  });
}

function timelineTimeFromClick(stage, event) {
  const start = Number(stage.dataset.timelineStart);
  const end = Number(stage.dataset.timelineEnd);
  const rect = stage.getBoundingClientRect();
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start || rect.height <= 0) return '';
  const scaleHeight = Number(stage.dataset.timelineNaturalHeight) || rect.height;
  const position = Math.max(0, Math.min(scaleHeight, event.clientY - rect.top));
  const rawMinute = start + ((position / scaleHeight) * (end - start));
  const step = NEW_BOOKING_GRID_MINUTES;
  const snappedMinute = Math.floor(rawMinute / step) * step;
  const firstSlot = Math.ceil(start / step) * step;
  const lastSlot = Math.floor((end - 1) / step) * step;
  const snapped = firstSlot <= lastSlot
    ? Math.max(firstSlot, Math.min(lastSlot, snappedMinute))
    : Math.max(start, Math.min(end - 1, Math.round(rawMinute)));
  return `${String(Math.floor(snapped / 60)).padStart(2, '0')}:${String(snapped % 60).padStart(2, '0')}`;
}

function timelineMinuteFromPointer(stage, clientY, pointerOffsetY, duration, dateIso = selectedDate) {
  const start = Number(stage?.dataset.timelineStart);
  const end = Number(stage?.dataset.timelineEnd);
  const rect = stage?.getBoundingClientRect();
  if (!rect || !Number.isFinite(start) || !Number.isFinite(end) || end <= start || rect.height <= 0) return null;
  const step = scheduleStepForDate(dateIso);
  const scaleHeight = Number(stage.dataset.timelineNaturalHeight) || rect.height;
  const rawMinute = start + (((clientY - rect.top - pointerOffsetY) / scaleHeight) * (end - start));
  const snapped = Math.round(rawMinute / step) * step;
  return Math.max(start, Math.min(end - duration, snapped));
}

function timelineMoveRestriction(item) {
  if (!item) return 'Запись не найдена';
  if (item.is_imported_history) return 'Импортированная запись доступна только для просмотра';
  if (isScheduleBlock(item)) return 'Перерыв переносится через подробное редактирование';
  if (item.series_id) return 'Для серии выберите область переноса в карточке записи';
  if (item.status === 'cancelled') return 'Отменённую запись нельзя переносить';
  if (bookingIsCompleted(item) || ['completed', 'no_show'].includes(item.status)) return 'Завершённую запись нельзя переносить';
  if (bookingMoveTimeIsPast(item.booking_date, String(item.booking_time).slice(0, 5))) return 'Начавшуюся или прошедшую запись нельзя переносить';
  return '';
}

function timelineBookingMoveSnapshot(item) {
  return Object.freeze({
    id:item?.id || '',
    organization_id:item?.organization_id || null,
    location_id:item?.location_id || null,
    service_id:item?.service_id || null,
    booking_date:item?.booking_date || '',
    booking_time:item?.booking_time || '',
    duration_minutes:Number(item?.duration_minutes),
    status:item?.status || '',
    total_price_rub:item?.total_price_rub,
    original_price_rub:item?.original_price_rub,
    services:item?.services ? Object.freeze({ ...item.services }) : null
  });
}

function timelineBookingMatchesMoveSnapshot(item, expected) {
  return Boolean(item && expected
    && item.id === expected.id
    && item.organization_id === expected.organization_id
    && item.location_id === expected.location_id
    && item.service_id === expected.service_id
    && item.booking_date === expected.booking_date
    && String(item.booking_time).slice(0, 5) === String(expected.booking_time).slice(0, 5)
    && Number(item.duration_minutes) === Number(expected.duration_minutes)
    && item.status === expected.status);
}

function timelineMoveRevenueText(item) {
  const amount = Math.max(0, Number(item?.total_price_rub ?? item?.original_price_rub ?? item?.services?.price_rub ?? bookingSessionTotal(item)) || 0);
  return amount > 0 ? `${amount.toLocaleString('ru-RU')} ₽ остаётся в графике` : 'Выручка не изменится';
}

function timelinePlacementShortLabel(issue) {
  const reason = String(issue || '').toLowerCase();
  if (!reason) return 'Свободно';
  if (reason.includes('перерыв')) return 'Перерыв';
  if (reason.includes('занят') || reason.includes('запись')) return 'Занято';
  if (reason.includes('выходн')) return 'Выходной';
  if (reason.includes('прошл')) return 'Прошедшее время';
  if (reason.includes('рабоч')) return 'Вне рабочего дня';
  if (reason.includes('закрыто')) return 'Недоступно';
  return 'Нельзя поставить';
}

function timelineMagneticTarget(item, stage, pointerMinute, dateIso = selectedDate) {
  const start = Number(stage?.dataset.timelineStart);
  const end = Number(stage?.dataset.timelineEnd);
  const duration = Math.max(1, Number(item?.duration_minutes || item?.services?.duration_minutes || 60));
  const step = Math.max(1, scheduleStepForDate(dateIso));
  const min = Number.isFinite(start) ? start : 0;
  const max = Number.isFinite(end) ? Math.max(min, end - duration) : 1440 - duration;
  const bounded = Math.max(min, Math.min(max, pointerMinute));
  const originalMinute = item?.booking_date === dateIso ? minutesFromTime(item.booking_time) : null;
  const directIssue = bookingPlacementIssue(item, dateIso, bounded);
  if (!directIssue) return { minute:bounded, issue:'', magnetized:false, pointerMinute:bounded };
  for (let offset = step; offset <= TIMELINE_MAGNET_RADIUS_MINUTES; offset += step) {
    for (const candidate of [bounded - offset, bounded + offset]) {
      if (candidate < min || candidate > max) continue;
      if (candidate === originalMinute && bounded !== originalMinute) continue;
      if (!bookingPlacementIssue(item, dateIso, candidate)) {
        return { minute:candidate, issue:'', magnetized:true, pointerMinute:bounded, rejectedIssue:directIssue };
      }
    }
  }
  return { minute:bounded, issue:directIssue, magnetized:false, pointerMinute:bounded };
}

function bookingPlacementIssue(item, dateIso, startMinute, { allowPast = false, ignoreSchedule = false, ignoreAutomaticBuffer = false, respectAutomaticBreakReleases = false } = {}) {
  const duration = Math.max(1, Number(item?.duration_minutes || item?.services?.duration_minutes || 60));
  const endMinute = startMinute + duration;
  const automaticBuffer = bookingPolicy.booking_buffer_enabled && !ignoreAutomaticBuffer
    ? Math.min(1440, Math.max(1, Number(bookingPolicy.booking_buffer_minutes) || 60))
    : 0;
  const candidateIsBlock = isScheduleBlock(item);
  if (dateIso < businessTodayIso() && !allowPast) return 'Нельзя переносить запись в прошлое';
  if (!allowPast && bookingMoveTimeIsPast(dateIso, timeFromMinutes(startMinute))) return 'Выбранное время уже прошло';
  const date = parseLocalIsoDate(dateIso);
  if (!date) return 'Не удалось определить выбранную дату';
  if (startMinute < 0 || endMinute > 1440) return 'Запись должна завершиться в выбранную дату';
  if (!ignoreSchedule) {
    const weekday = ((date.getDay() + 6) % 7) + 1;
    const schedule = scheduleRows.find(row => Number(row.weekday) === weekday);
    if (schedule?.enabled === false) return 'В этот день в расписании стоит выходной';
    const scheduleStart = minutesFromTime(schedule?.start_time || '10:00');
    const scheduleEnd = minutesFromTime(schedule?.end_time || '20:00');
    if (startMinute < scheduleStart || endMinute > scheduleEnd) return 'Запись должна оставаться в пределах рабочего дня';
    if (schedule?.break_start && schedule?.break_end) {
      const breakStart = minutesFromTime(schedule.break_start);
      const breakEnd = minutesFromTime(schedule.break_end);
      if (startMinute < breakEnd && endMinute > breakStart) return 'Это время пересекается с перерывом в расписании';
    }
    const dayOff = daysOff.find(entry => {
      if (entry.off_date !== dateIso) return false;
      if (entry.all_day) return true;
      const offStart = minutesFromTime(entry.start_time);
      const offEnd = minutesFromTime(entry.end_time);
      return startMinute < offEnd && endMinute > offStart;
    });
    if (dayOff) return dayOff.all_day ? 'На эту дату установлен выходной' : 'Это время закрыто в исключениях расписания';
  }
  const conflict = allBookings.find(other => {
    if (other.id === item.id || other.status === 'cancelled' || other.booking_date !== dateIso) return false;
    const otherStart = minutesFromTime(other.booking_time);
    const otherEnd = otherStart + Math.max(1, Number(other.duration_minutes || other.services?.duration_minutes || 60));
    return startMinute < otherEnd && endMinute > otherStart;
  });
  if (conflict) return `В ${String(conflict.booking_time).slice(0, 5)} уже есть запись`;
  if (!automaticBuffer || candidateIsBlock) return '';
  if (respectAutomaticBreakReleases && automaticBookingBreaksRemoteAvailable && automaticBookingBreakSegments.has(dateIso)) {
    const segment = automaticBookingBreakSegments.get(dateIso).find(entry => {
      const segmentStart = minutesFromTime(String(entry.start_time || '').slice(0, 5));
      const segmentEnd = minutesFromTime(String(entry.end_time || '').slice(0, 5));
      return startMinute < segmentEnd && endMinute > segmentStart;
    });
    return segment
      ? `В ${String(segment.start_time).slice(0, 5)}–${String(segment.end_time).slice(0, 5)} действует перерыв: автоматический буфер`
      : '';
  }
  const bufferedConflict = allBookings.find(other => {
    if (other.id === item.id || other.status === 'cancelled' || other.booking_date !== dateIso || isScheduleBlock(other)) return false;
    const otherStart = minutesFromTime(other.booking_time);
    const otherEnd = otherStart + Math.max(1, Number(other.duration_minutes || other.services?.duration_minutes || 60));
    return startMinute < otherEnd + automaticBuffer && endMinute > otherStart - automaticBuffer;
  });
  return bufferedConflict
    ? `Рядом с записью в ${String(bufferedConflict.booking_time).slice(0, 5)} действует перерыв ${automaticBuffer} мин`
    : '';
}

function clearTimelineBookingUndo() {
  clearTimeout(timelineBookingUndoTimeout);
  clearInterval(timelineBookingUndoInterval);
  timelineBookingUndoTimeout = null;
  timelineBookingUndoInterval = null;
  timelineBookingUndoHovered = false;
  timelineBookingUndoFocused = false;
  timelineBookingUndo = null;
  const holder = $('#timelineBookingUndo');
  if (holder) {
    holder.hidden = true;
    holder.classList.remove('is-active', 'is-pending', 'is-paused');
  }
  const button = $('#timelineBookingUndoButton');
  if (button) {
    button.disabled = false;
    button.textContent = 'Отменить';
  }
}

function updateTimelineBookingUndoCountdown() {
  if (!timelineBookingUndo) return;
  const seconds = Math.max(0, Math.ceil((timelineBookingUndo.expiresAt - Date.now()) / 1000));
  const label = $('#timelineBookingUndoCountdown');
  if (label) label.textContent = seconds ? `Отмена доступна ещё ${seconds} сек.` : 'Время отмены истекло';
  if (!seconds) clearTimelineBookingUndo();
}

function scheduleTimelineBookingUndoCountdown(restartAnimation = false) {
  if (!timelineBookingUndo) return;
  clearTimeout(timelineBookingUndoTimeout);
  clearInterval(timelineBookingUndoInterval);
  const delay = Math.max(0, timelineBookingUndo.expiresAt - Date.now());
  timelineBookingUndoInterval = setInterval(updateTimelineBookingUndoCountdown, 1000);
  timelineBookingUndoTimeout = setTimeout(clearTimelineBookingUndo, delay + 100);
  const holder = $('#timelineBookingUndo');
  if (holder && restartAnimation) {
    holder.classList.remove('is-active');
    void holder.offsetWidth;
    holder.classList.add('is-active');
  }
}

function pauseTimelineBookingUndoCountdown() {
  if (!timelineBookingUndo || timelineBookingUndo.paused) return;
  timelineBookingUndo.remainingMs = Math.max(0, timelineBookingUndo.expiresAt - Date.now());
  timelineBookingUndo.paused = true;
  clearTimeout(timelineBookingUndoTimeout);
  clearInterval(timelineBookingUndoInterval);
  timelineBookingUndoTimeout = null;
  timelineBookingUndoInterval = null;
  $('#timelineBookingUndo')?.classList.add('is-paused');
}

function resumeTimelineBookingUndoCountdown() {
  if (!timelineBookingUndo || timelineMovePending || !timelineBookingUndo.paused || timelineBookingUndoHovered || timelineBookingUndoFocused) return;
  timelineBookingUndo.expiresAt = Date.now() + Math.max(0, timelineBookingUndo.remainingMs || 0);
  timelineBookingUndo.paused = false;
  $('#timelineBookingUndo')?.classList.remove('is-paused');
  updateTimelineBookingUndoCountdown();
  scheduleTimelineBookingUndoCountdown();
}

function showTimelineBookingUndo(previous, current) {
  const holder = $('#timelineBookingUndo');
  const message = $('#timelineBookingUndoMessage');
  if (!holder || !message || !previous || !current) {
    notify(`Запись перенесена на ${String(current?.booking_time || '').slice(0, 5)}`);
    return;
  }
  clearTimelineBookingUndo();
  timelineBookingUndo = {
    bookingId:current.id,
    previous:{
      booking_date:previous.booking_date,
      booking_time:String(previous.booking_time).slice(0, 5),
      service_id:previous.service_id,
      duration_minutes:Number(previous.duration_minutes),
      status:previous.status
    },
    expected:{
      booking_date:current.booking_date,
      booking_time:String(current.booking_time).slice(0, 5),
      service_id:current.service_id,
      duration_minutes:Number(current.duration_minutes),
      status:current.status
    },
    moveId:current.schedule_move_id || '',
    expiresAt:Date.now() + TIMELINE_UNDO_WINDOW_MS,
    remainingMs:TIMELINE_UNDO_WINDOW_MS,
    paused:false
  };
  const state = timelineBookingUndo;
  holder.hidden = false;
  message.textContent = '';
  const announcement = `Запись перенесена: ${String(previous.booking_time).slice(0, 5)} → ${String(current.booking_time).slice(0, 5)}`;
  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(() => {
    if (timelineBookingUndo === state) message.textContent = announcement;
  });
  else message.textContent = announcement;
  updateTimelineBookingUndoCountdown();
  scheduleTimelineBookingUndoCountdown(true);
}

function timelineBookingMatchesUndoPoint(item, point) {
  return Boolean(item && point
    && item.booking_date === point.booking_date
    && String(item.booking_time).slice(0, 5) === point.booking_time
    && item.service_id === point.service_id
    && Number(item.duration_minutes) === point.duration_minutes
    && item.status === point.status);
}

function finishTimelineBookingDrag({ restore = true } = {}) {
  const state = timelineBookingDrag;
  if (!state) return;
  clearTimeout(state.holdTimer);
  state.label?.remove();
  state.preview?.remove();
  state.stage.classList.remove('is-magnetic-target', 'is-magnetic-invalid');
  state.card.classList.remove('is-dragging', 'is-drag-pressed', 'is-drag-invalid', 'is-magnetized');
  state.card.removeAttribute('aria-grabbed');
  if (restore && state.card.isConnected) state.card.style.top = state.originalTop;
  document.body.classList.remove('timeline-booking-dragging');
  try { state.card.releasePointerCapture(state.pointerId); } catch {}
  timelineBookingDrag = null;
}

function activateTimelineBookingDrag(state) {
  if (!state || timelineBookingDrag !== state || state.active) return;
  state.active = true;
  state.card.classList.add('is-dragging');
  state.card.setAttribute('aria-grabbed', 'true');
  document.body.classList.add('timeline-booking-dragging');
  state.label = document.createElement('span');
  state.label.className = 'timeline-drag-label';
  state.label.innerHTML = '<strong></strong><small></small>';
  state.stage.append(state.label);
  state.preview = document.createElement('span');
  state.preview.className = 'timeline-drag-preview';
  state.preview.setAttribute('aria-hidden', 'true');
  state.stage.append(state.preview);
  updateTimelineBookingDrag(state, state.startY);
  if (state.pointerType === 'touch') navigator.vibrate?.(12);
}

function updateTimelineBookingDrag(state, clientY) {
  const pointerMinute = timelineMinuteFromPointer(state.stage, clientY, state.pointerOffsetY, state.duration);
  if (!Number.isFinite(pointerMinute)) return;
  const target = timelineMagneticTarget(state.item, state.stage, pointerMinute, state.date);
  const minute = target.minute;
  state.targetMinute = minute;
  state.issue = target.issue;
  state.magnetized = target.magnetized;
  const start = Number(state.stage.dataset.timelineStart);
  const end = Number(state.stage.dataset.timelineEnd);
  const rect = state.stage.getBoundingClientRect();
  const scaleHeight = Number(state.stage.dataset.timelineNaturalHeight) || rect.height;
  const top = ((minute - start) / (end - start)) * scaleHeight + 2;
  const endTime = timeFromMinutes(minute + state.duration);
  state.card.style.top = `${top}px`;
  state.card.classList.toggle('is-drag-invalid', Boolean(target.issue));
  state.card.classList.toggle('is-magnetized', Boolean(target.magnetized));
  state.stage.classList.toggle('is-magnetic-target', !target.issue);
  state.stage.classList.toggle('is-magnetic-invalid', Boolean(target.issue));
  if (state.preview) {
    state.preview.classList.toggle('is-invalid', Boolean(target.issue));
    state.preview.classList.toggle('is-magnetized', Boolean(target.magnetized));
    state.preview.style.top = `${top}px`;
    state.preview.style.height = `${Math.max(18, (state.duration / 60) * (scaleHeight / ((end - start) / 60)) - 4)}px`;
  }
  const strong = state.label?.querySelector('strong');
  const small = state.label?.querySelector('small');
  if (strong) strong.textContent = `${timeFromMinutes(minute)}–${endTime}`;
  if (small) small.textContent = target.issue
    ? timelinePlacementShortLabel(target.issue)
    : `${target.magnetized ? 'Подходит · ' : ''}${state.duration} мин · ${timelineMoveRevenueText(state.item)}`;
  if (state.label) {
    state.label.classList.toggle('is-invalid', Boolean(target.issue));
    state.label.classList.toggle('is-magnetized', Boolean(target.magnetized));
    state.label.style.top = `${Math.max(4, top - 52)}px`;
    state.label.title = target.issue || 'Свободное время';
  }
}

function timelineMoveAttemptKey(userId = currentUser?.id) {
  return userId ? `minuta_provider_timeline_move_v157:${userId}` : '';
}

function readTimelineMoveAttempt(userId = currentUser?.id) {
  const key = timelineMoveAttemptKey(userId);
  if (!key) return null;
  try {
    const attempt = JSON.parse(sessionStorage.getItem(key) || 'null');
    if (!attempt || Date.now() - Number(attempt.savedAt || 0) > 30 * 60 * 1000) {
      sessionStorage.removeItem(key);
      return null;
    }
    return attempt;
  } catch { return null; }
}

function writeTimelineMoveAttempt(attempt, userId = currentUser?.id) {
  const key = timelineMoveAttemptKey(userId);
  if (!key) return false;
  try {
    sessionStorage.setItem(key, JSON.stringify({ ...attempt, savedAt:Date.now() }));
    return true;
  } catch { return false; }
}

function clearTimelineMoveAttempt(userId = currentUser?.id) {
  const key = timelineMoveAttemptKey(userId);
  if (!key) return;
  try { sessionStorage.removeItem(key); } catch {}
}

function providerScheduleMoveErrorMessage(error) {
  const reason = `${error?.code || ''}:${error?.message || ''}`;
  const known = {
    '40001:provider_schedule_booking_changed':'Запись изменилась в другой вкладке. Проверьте её и повторите перенос.',
    '23P01:provider_schedule_slot_unavailable':'Это время уже занято или недоступно.',
    '42501:provider_schedule_access_denied':'У вас нет доступа к переносу этой записи.',
    'P0001:provider_schedule_booking_not_found':'Запись не найдена. Обновите журнал.',
    'P0001:provider_schedule_booking_not_actionable':'Эту запись уже нельзя переносить.',
    '55000:provider_schedule_series_requires_editor':'Серию переносите через карточку записи.',
    '55000:provider_schedule_block_requires_editor':'Перерыв изменяйте через его карточку.',
    '22023:invalid_provider_schedule_target':'Выберите корректное время переноса.',
    '22023:provider_schedule_target_in_past':'Выбранное время уже прошло.',
    '22023:provider_schedule_request_reused':'Запрос уже использован для другого переноса.'
  };
  return known[reason] || providerRescheduleErrorMessage(error) || '';
}

function timelineMoveRpcMissing(error) {
  const reason = `${error?.code || ''} ${error?.message || ''} ${error?.details || ''}`;
  return /PGRST202|42883/.test(reason) || /move_minuta_provider_schedule_booking_v157/i.test(reason) && /not find|does not exist|schema cache/i.test(reason);
}

function timelineMoveOutcomeUnknown(error) {
  const reason = `${error?.code || ''} ${error?.message || ''} ${error?.details || ''}`;
  return !error || /PGRST00[012]|fetch|network|timeout|timed out|connection|socket|econn|failed to fetch/i.test(reason);
}

async function moveTimelineBookingAtExpectedState(item, targetDate, targetTime, requestId) {
  const result = await db.rpc('move_minuta_provider_schedule_booking_v157', {
    p_request_id:requestId,
    p_booking:item.id,
    p_date:targetDate,
    p_time:`${targetTime}:00`,
    p_expected_organization:item.organization_id || null,
    p_expected_location:item.location_id || null,
    p_expected_service:item.service_id,
    p_expected_date:item.booking_date,
    p_expected_time:item.booking_time,
    p_expected_duration:Number(item.duration_minutes),
    p_expected_status:item.status
  });
  if (result.error) return { error:result.error };
  const row = result.data;
  const confirmed = row?.action === 'moved' && row?.request_id === requestId && row?.booking_id === item.id
    && row?.performer_id === currentUser?.id && String(row?.booking_date) === targetDate
    && String(row?.booking_time).slice(0, 5) === targetTime && row?.notifications_suppressed === false;
  return confirmed ? { data:row, error:null } : { error:{ code:'MINUTA_BOOKING_UNCONFIRMED', message:'provider_schedule_move_unconfirmed' } };
}

async function persistTimelineBookingMove(state, { recovery = false } = {}) {
  if (bookingUsesDemoData()) { renderBookings(); return; }
  const item = state.item;
  const currentBeforeMove = allBookings.find(booking => booking.id === state.bookingId);
  if (!item || !timelineBookingMatchesMoveSnapshot(currentBeforeMove, item) || timelineMovePending) {
    if (item && currentBeforeMove && !timelineBookingMatchesMoveSnapshot(currentBeforeMove, item)) {
      clearTimelineMoveAttempt();
      notify('Запись изменилась в другой вкладке. Проверьте её и повторите перенос.');
    }
    renderBookings();
    return;
  }
  const targetTime = timeFromMinutes(state.targetMinute);
  const originalTime = String(item.booking_time).slice(0, 5);
  if (targetTime === originalTime) {
    renderBookings();
    return;
  }
  const restriction = timelineMoveRestriction(item);
  const issue = restriction || bookingPlacementIssue(item, state.date, state.targetMinute);
  if (issue) {
    notify(issue);
    renderBookings();
    return;
  }
  if (!requireWrites()) {
    renderBookings();
    return;
  }
  timelineMovePending = true;
  state.card?.classList.add('is-saving-position');
  state.card?.setAttribute('aria-busy', 'true');
  const userId = currentUser.id;
  const generation = sessionGeneration;
  const { data: availableSlots, error: availabilityError } = await getProviderAvailableSlots({
    p_service:item.service_id,
    p_start:state.date,
    p_end:state.date,
    p_ignore_booking: item.id
  });
  if (!sessionIsCurrent(userId, generation)) {
    timelineMovePending = false;
    return;
  }
  const remotelyAvailable = !availabilityError && (availableSlots || []).some(slot => String(slot.booking_time).slice(0, 5) === targetTime);
  if (!remotelyAvailable) {
    timelineMovePending = false;
    notify(availabilityError ? 'Не удалось проверить новое время. Попробуйте ещё раз.' : 'Это время уже занято или недоступно');
    renderBookings();
    return;
  }
  const requestId = state.requestId || createOfflineBookingId();
  state.requestId = requestId;
  writeTimelineMoveAttempt({
    operation:'move',
    requestId,
    bookingId:item.id,
    targetDate:state.date,
    targetTime,
    expected:{
      organization_id:item.organization_id || null,
      location_id:item.location_id || null,
      service_id:item.service_id,
      booking_date:item.booking_date,
      booking_time:item.booking_time,
      duration_minutes:Number(item.duration_minutes),
      status:item.status
    }
  }, userId);
  let moved;
  let error;
  try {
    ({ data:moved, error } = await moveTimelineBookingAtExpectedState(item, state.date, targetTime, requestId));
  } catch (failure) {
    error = failure;
  }
  timelineMovePending = false;
  if (!sessionIsCurrent(userId, generation)) return;
  if (error) {
    const missing = timelineMoveRpcMissing(error);
    const uncertain = !missing && timelineMoveOutcomeUnknown(error);
    if (!uncertain) clearTimelineMoveAttempt(userId);
    notify(missing ? 'Безопасный перенос обновляется на сервере. Пока используйте карточку записи.' : uncertain ? 'Ответ сервера не получен. Проверяем результат автоматически.' : providerScheduleMoveErrorMessage(error) || 'Не удалось подтвердить перенос. Проверьте актуальную запись.');
    await loadBookings({ silent:true });
    return;
  }
  clearTimelineMoveAttempt(userId);
  const previous = { ...item };
  await refreshAfterWrite();
  const current = allBookings.find(booking => booking.id === item.id) || {
    ...item,
    booking_date:state.date,
    booking_time:`${targetTime}:00`,
    schedule_move_id:moved?.move_id
  };
  current.schedule_move_id = moved?.move_id || current.schedule_move_id;
  showTimelineBookingUndo(previous, current);
  if (recovery) notify(`Перенос подтверждён: ${targetTime}`);
}

async function confirmTimelineBookingMove(state) {
  if (!state || timelineMoveConfirmationPending) return;
  const item = state.item;
  const current = allBookings.find(booking => booking.id === state.bookingId);
  const targetTime = timeFromMinutes(state.targetMinute);
  const originalTime = String(item?.booking_time || '').slice(0, 5);
  const issue = timelineMoveRestriction(item) || state.issue || bookingPlacementIssue(item, state.date, state.targetMinute);
  renderBookings();
  if (!item || targetTime === originalTime) return;
  if (!timelineBookingMatchesMoveSnapshot(current, item)) {
    notify('Запись изменилась в другой вкладке. Проверьте её и повторите перенос.');
    return;
  }
  if (issue) {
    notify(issue);
    return;
  }
  timelineMoveConfirmationPending = true;
  const confirmed = await requestProviderConfirmation({
    title:'Перенести запись?',
    message:`${originalTime} → ${targetTime} · ${state.duration} мин. ${timelineMoveRevenueText(item)}. Перед сохранением свободное время проверится ещё раз.`,
    confirmLabel:'Перенести'
  });
  timelineMoveConfirmationPending = false;
  if (!confirmed) return;
  await persistTimelineBookingMove(state);
}

async function performTimelineBookingUndo(undo, requestId, { recovery = false } = {}) {
  if (!undo || !requestId || timelineMovePending || !currentUser?.id) return;
  const item = allBookings.find(booking => booking.id === undo.bookingId);
  if (!timelineBookingMatchesUndoPoint(item, undo.expected)) {
    clearTimelineMoveAttempt();
    clearTimelineBookingUndo();
    notify('Запись уже изменилась. Отмена не выполнена.');
    await loadBookings({ silent:true });
    return;
  }
  const button = $('#timelineBookingUndoButton');
  const holder = $('#timelineBookingUndo');
  pauseTimelineBookingUndoCountdown();
  timelineMovePending = true;
  holder?.classList.add('is-pending');
  if (button) {
    button.disabled = true;
    button.textContent = 'Отменяем…';
  }
  const userId = currentUser.id;
  const generation = sessionGeneration;
  writeTimelineMoveAttempt({
    operation:'undo',requestId,moveId:undo.moveId,bookingId:undo.bookingId,
    previous:undo.previous,expected:undo.expected
  }, userId);
  let data;
  let error;
  try {
    ({ data, error } = await db.rpc('undo_minuta_provider_schedule_booking_v157', {
      p_request_id:requestId,
      p_move:undo.moveId
    }));
  } catch (failure) {
    error = failure;
  }
  timelineMovePending = false;
  if (!sessionIsCurrent(userId, generation)) return;
  const confirmed = !error && data?.action === 'undone' && data?.request_id === requestId
    && data?.booking_id === undo.bookingId && data?.performer_id === userId
    && String(data?.booking_date) === undo.previous.booking_date
    && String(data?.booking_time).slice(0, 5) === undo.previous.booking_time;
  if (!confirmed) {
    const missing = timelineMoveRpcMissing(error);
    const uncertain = !missing && timelineMoveOutcomeUnknown(error);
    if (!uncertain) clearTimelineMoveAttempt(userId);
    holder?.classList.remove('is-pending');
    if (button) {
      button.disabled = false;
      button.textContent = 'Отменить';
    }
    resumeTimelineBookingUndoCountdown();
    notify(missing ? 'Безопасная отмена обновляется на сервере. Повторите позже.' : uncertain ? 'Ответ сервера не получен. Проверяем отмену автоматически.' : providerScheduleMoveErrorMessage(error) || 'Не удалось отменить перенос. Проверьте актуальную запись.');
    await loadBookings({ silent:true });
    return;
  }
  clearTimelineMoveAttempt(userId);
  clearTimelineBookingUndo();
  await refreshAfterWrite();
  notify(`${recovery ? 'Отмена подтверждена' : 'Перенос отменён'} · ${undo.previous.booking_time}`);
}

async function undoLastTimelineBookingMove() {
  const undo = timelineBookingUndo;
  if (!undo || timelineMovePending || !currentUser?.id) return;
  await performTimelineBookingUndo(undo, createOfflineBookingId());
}

async function recoverPendingTimelineBookingMove() {
  const attempt = readTimelineMoveAttempt();
  if (!attempt || timelineMoveRecoveryPending || timelineMovePending || bookingUsesDemoData() || !currentUser?.id) return;
  timelineMoveRecoveryPending = true;
  try {
    const userId = currentUser.id;
    const generation = sessionGeneration;
    let receipt;
    try {
      receipt = await db.rpc('get_minuta_provider_schedule_move_v157', { p_request_id:attempt.requestId });
    } catch (failure) {
      receipt = { error:failure };
    }
  if (!sessionIsCurrent(userId, generation)) {
    timelineMoveRecoveryPending = false;
    return;
  }
  if (!receipt.error && attempt.operation === 'undo' && receipt.data?.action === 'undone' && receipt.data?.booking_id === attempt.bookingId) {
    clearTimelineMoveAttempt(userId);
    clearTimelineBookingUndo();
    await refreshAfterWrite();
    notify(`Отмена подтверждена · ${String(receipt.data.booking_time).slice(0, 5)}`);
    timelineMoveRecoveryPending = false;
    return;
  }
  if (!receipt.error && attempt.operation !== 'undo' && receipt.data?.action === 'moved' && receipt.data?.booking_id === attempt.bookingId) {
    clearTimelineMoveAttempt(userId);
    const current = allBookings.find(booking => booking.id === attempt.bookingId);
    if (current && receipt.data?.move_id) {
      current.schedule_move_id = receipt.data.move_id;
      showTimelineBookingUndo({ id:attempt.bookingId, ...attempt.expected }, current);
    }
    notify(`Перенос подтверждён: ${String(receipt.data.booking_time).slice(0, 5)}`);
    timelineMoveRecoveryPending = false;
    return;
  }
  if (timelineMoveRpcMissing(receipt.error)) {
    clearTimelineMoveAttempt(userId);
    timelineMoveRecoveryPending = false;
    return;
  }
  if (receipt.error && timelineMoveOutcomeUnknown(receipt.error)) {
    timelineMoveRecoveryPending = false;
    return;
  }
  if (receipt.error) {
    clearTimelineMoveAttempt(userId);
    timelineMoveRecoveryPending = false;
    return;
  }
  const current = allBookings.find(booking => booking.id === attempt.bookingId);
  if (attempt.operation === 'undo') {
    if (current && timelineBookingMatchesUndoPoint(current, attempt.expected)) {
      timelineMoveRecoveryPending = false;
      await performTimelineBookingUndo({
        bookingId:attempt.bookingId,moveId:attempt.moveId,
        previous:attempt.previous,expected:attempt.expected,
        expiresAt:Date.now() + TIMELINE_UNDO_WINDOW_MS,remainingMs:TIMELINE_UNDO_WINDOW_MS,paused:false
      }, attempt.requestId, { recovery:true });
      return;
    }
    clearTimelineMoveAttempt(userId);
    timelineMoveRecoveryPending = false;
    return;
  }
  const expected = current && timelineBookingMatchesUndoPoint(current, {
    booking_date:attempt.expected.booking_date,
    booking_time:String(attempt.expected.booking_time).slice(0, 5),
    service_id:attempt.expected.service_id,
    duration_minutes:Number(attempt.expected.duration_minutes),
    status:attempt.expected.status
  });
  if (expected) {
    await persistTimelineBookingMove({
      item:timelineBookingMoveSnapshot(current),
      bookingId:current.id,
      date:attempt.targetDate,
      targetMinute:minutesFromTime(attempt.targetTime),
      duration:Number(current.duration_minutes),
      requestId:attempt.requestId,
      card:document.createElement('span')
    }, { recovery:true });
  } else {
    clearTimelineMoveAttempt(userId);
  }
  } finally {
    timelineMoveRecoveryPending = false;
  }
}

function beginTimelineBookingDrag(event, card) {
  if (timelineBookingDrag || scheduleDaySwipe || timelineMovePending || timelineMoveConfirmationPending || !writesAllowed || event.button !== 0 || !card.hasAttribute('data-timeline-movable')) return;
  if ((event.pointerType === 'touch' || event.pointerType === 'pen') && !event.target.closest('.timeline-drag-handle')) return;
  const stage = card.closest('.timeline-stage');
  const item = allBookings.find(booking => booking.id === card.dataset.openBooking);
  if (!stage || !item) return;
  const restriction = timelineMoveRestriction(item);
  if (restriction) {
    notify(restriction);
    return;
  }
  const rect = card.getBoundingClientRect();
  const visualTop = Number.parseFloat(card.style.top) || 0;
  const timelineTop = Number(card.dataset.mobileTimelineTop) || visualTop;
  const state = {
    pointerId:event.pointerId,
    pointerType:event.pointerType,
    card,
    stage,
    item:timelineBookingMoveSnapshot(item),
    bookingId:item.id,
    date:selectedDate,
    duration:Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60)),
    startX:event.clientX,
    startY:event.clientY,
    pointerOffsetY:event.clientY - rect.top + Math.max(0, visualTop - timelineTop),
    originalTop:card.style.top,
    targetMinute:minutesFromTime(item.booking_time),
    active:false,
    holdTimer:null,
    label:null,
    preview:null,
    issue:'',
    magnetized:false
  };
  timelineBookingDrag = state;
  card.classList.add('is-drag-pressed');
  card.setPointerCapture?.(event.pointerId);
  if (event.pointerType === 'touch' || event.pointerType === 'pen') {
    state.holdTimer = setTimeout(() => activateTimelineBookingDrag(state), TIMELINE_TOUCH_HOLD_MS);
  }
}

function finishScheduleDaySwipe(state, event) {
  if (!state || scheduleDaySwipe !== state) return;
  const deltaX = event.clientX - state.startX;
  state.surface.classList.remove('is-day-swiping');
  state.surface.style.removeProperty('--day-swipe-x');
  try { state.surface.releasePointerCapture(state.pointerId); } catch {}
  scheduleDaySwipe = null;
  if (!state.active || Math.abs(deltaX) < SCHEDULE_SWIPE_THRESHOLD_PX) return;
  gestureClickSuppressedUntil = Date.now() + 450;
  shiftScheduleDate(deltaX < 0 ? 1 : -1);
}

function beginScheduleDaySwipe(event, surface) {
  if ((event.pointerType !== 'touch' && event.pointerType !== 'pen') || event.button !== 0 || currentFilter !== 'day' || timelineBookingDrag || timelineMovePending) return;
  if (event.target.closest('.timeline-booking,.provider-booking,input,select,textarea,a,[contenteditable="true"]')) return;
  scheduleDaySwipe = {
    pointerId:event.pointerId,
    surface,
    startX:event.clientX,
    startY:event.clientY,
    active:false
  };
}

function openTimelineBooking(stage, event) {
  if (!requireBookingWrites()) return;
  const time = timelineTimeFromClick(stage, event);
  if (!time) return;
  dismissScheduleCreateHint();
  openTimelineBookingAtTime(time, stage.dataset.timelineDate || selectedDate);
}

function openTimelineBookingAtTime(time, dateIso = selectedDate) {
  if (!requireBookingWrites() || !/^\d{2}:\d{2}$/.test(String(time)) || !/^\d{4}-\d{2}-\d{2}$/.test(String(dateIso))) return;
  const today = businessTodayIso();
  openNewBookingSheet(time, { date:dateIso, historical:dateIso < today || (dateIso === today && bookingMoveTimeIsPast(dateIso, time)) });
}

function timelineKeyboardMinute(stage) {
  const start = Number(stage.dataset.timelineStart || 0);
  const end = Math.max(start, Number(stage.dataset.timelineEnd || start) - 1);
  const firstSlot = Math.ceil(start / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  const lastSlot = Math.floor(end / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  const stored = Number(stage.dataset.timelineKeyboardMinute);
  if (firstSlot > lastSlot) return start;
  const aligned = Math.floor((Number.isFinite(stored) ? stored : firstSlot) / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  return Math.max(firstSlot, Math.min(lastSlot, aligned));
}

function setTimelineKeyboardMinute(stage, minute) {
  const start = Number(stage.dataset.timelineStart || 0);
  const end = Math.max(start, Number(stage.dataset.timelineEnd || start) - 1);
  const firstSlot = Math.ceil(start / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  const lastSlot = Math.floor(end / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  const aligned = Math.floor(Number(minute || firstSlot) / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  const value = firstSlot <= lastSlot ? Math.max(firstSlot, Math.min(lastSlot, aligned)) : start;
  const time = timeFromMinutes(value);
  stage.dataset.timelineKeyboardMinute = String(value);
  stage.setAttribute('aria-label', `Выбор свободного времени. Выбрано ${time}. Стрелками измените время, Enter создаст запись`);
  return time;
}

document.addEventListener('keydown', event => {
  const stage = event.target.closest?.('[data-create-booking-at]');
  if (!stage || event.target.closest?.('.timeline-booking')) return;
  const current = timelineKeyboardMinute(stage);
  const moves = { ArrowLeft:-30, ArrowDown:-30, ArrowRight:30, ArrowUp:30, PageDown:-60, PageUp:60 };
  if (Object.hasOwn(moves, event.key)) {
    event.preventDefault();
    setTimelineKeyboardMinute(stage, current + moves[event.key]);
    return;
  }
  if (event.key === 'Home' || event.key === 'End') {
    event.preventDefault();
    const target = event.key === 'Home'
      ? Number(stage.dataset.timelineStart || 0)
      : Number(stage.dataset.timelineEnd || 0) - 5;
    setTimelineKeyboardMinute(stage, target);
    return;
  }
  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    openTimelineBookingAtTime(setTimelineKeyboardMinute(stage, current), stage.dataset.timelineDate || selectedDate);
  }
});

function bookingClientNote(item) {
  return String(clientNotes.get(normalizePhone(item?.client_phone)) || '').trim();
}

function bookingDisplayNote(item) {
  return isScheduleBlock(item)
    ? String(pendingBookingNotes.has(item?.id) ? bookingNotes.get(item?.id) ?? '' : item?.provider_note || bookingNotes.get(item?.id) || '').trim()
    : bookingClientNote(item);
}

function bookingSeriesMarkup(item) {
  const occurrence = Number(item?.series_occurrence || 0);
  const storedTotal = Number(item?.booking_series?.occurrence_count || 0);
  const total = item?.series_id
    ? Math.max(storedTotal, occurrence, ...allBookings.filter(entry => entry.series_id === item.series_id).map(entry => Number(entry.series_occurrence || 0)))
    : 0;
  return item?.series_id && occurrence > 0
    ? `<span class="booking-series-badge">Серия · визит ${occurrence}${total > 1 ? ` из ${total}` : ''}</span>`
    : '';
}

function actionableSeriesBookings(item, scope = 'all') {
  if (!item?.series_id) return item ? [item] : [];
  return allBookings.filter(entry => entry.series_id === item.series_id
    && entry.status !== 'cancelled'
    && entry.booking_date >= businessTodayIso()
    && bookingOutcome(entry).visit_status === 'scheduled'
    && (scope === 'all'
      || (scope === 'following' && Number(entry.series_occurrence) >= Number(item.series_occurrence))
      || (scope === 'one' && entry.id === item.id)))
    .sort((a, b) => Number(a.series_occurrence) - Number(b.series_occurrence));
}

function seriesBookingCountLabel(count) {
  const mod100 = count % 100;
  const mod10 = count % 10;
  const word = mod100 >= 11 && mod100 <= 14 ? 'записей' : mod10 === 1 ? 'запись' : mod10 >= 2 && mod10 <= 4 ? 'записи' : 'записей';
  return `${count} ${word}`;
}

function bookingSeriesScopeMarkup(item, name, actionLabel) {
  if (!item?.series_id) return '';
  const following = actionableSeriesBookings(item, 'following').length;
  const all = actionableSeriesBookings(item, 'all').length;
  const sameFutureScope = following === all && all > 1;
  return `<fieldset class="booking-series-scope"><legend>${escapeHtml(actionLabel)}</legend>
    <label><input type="radio" name="${name}" value="one" checked><span><strong>Только эту запись</strong><small>Остальные визиты не изменятся</small></span></label>
    <label><input type="radio" name="${name}" value="following"><span><strong>Эту и последующие</strong><small>Выбранная и все после неё · ${seriesBookingCountLabel(following)}</small></span></label>
    <label><input type="radio" name="${name}" value="all"><span><strong>Все будущие записи</strong><small>Все предстоящие в серии · ${seriesBookingCountLabel(all)}; прошедшие сохранятся</small></span></label>
    ${sameFutureScope ? '<small class="booking-series-same-result">Сейчас результат одинаковый: перед выбранной записью нет других предстоящих визитов серии.</small>' : ''}
  </fieldset>`;
}

function seriesRpcErrorMessage(error, action) {
  const reason = String(error?.message || '');
  if (reason.includes('series_slot_unavailable') || reason.includes('overlap') || reason.includes('resource_unavailable') || reason.includes('booking_buffer_conflict')) {
    return 'Одно из новых времён занято. Серия осталась без изменений.';
  }
  if (reason.includes('series_reschedule_out_of_range')) return 'После переноса часть серии окажется в прошлом или слишком далеко. Выберите более позднюю дату.';
  if (/manage_minuta_booking_series|schema cache|could not find/i.test(reason)) return 'Управление сериями пока не установлено. Сначала примените миграцию v79.';
  return action === 'cancel'
    ? 'Не удалось отменить выбранные записи. Серия осталась без изменений.'
    : 'Не удалось перенести выбранные записи. Серия осталась без изменений.';
}

function stackMinuteTimelineItems(timelineItems, gap = 6) {
  const minuteItems = timelineItems.filter(entry => entry.minuteOnly).sort((a, b) => a.top - b.top || a.index - b.index);
  let previousMinuteBottom = -Infinity;
  minuteItems.forEach(entry => {
    entry.visualTop = Math.max(entry.top, previousMinuteBottom + gap);
    previousMinuteBottom = entry.visualTop + entry.height;
  });
}

function automaticBookingBreaks(items, dateIso = selectedDate) {
  if (!bookingPolicy.booking_buffer_enabled) return [];
  if (automaticBookingBreaksRemoteAvailable && automaticBookingBreakSegments.has(dateIso)) {
    return automaticBookingBreakSegments.get(dateIso).map((segment, index) => {
      const start = String(segment.start_time || '').slice(0, 5);
      const end = String(segment.end_time || '').slice(0, 5);
      const duration = Math.max(1, minutesFromTime(end) - minutesFromTime(start));
      return {
        id:`automatic-break:${dateIso}:${start}:${end}:${index}`,
        performer_id:currentUser?.id || '',
        booking_date:dateIso,
        booking_time:`${start}:00`,
        duration_minutes:duration,
        client_name:'Перерыв',
        client_phone:SCHEDULE_BLOCK_PHONE,
        status:'confirmed',
        automatic_break:true,
        automatic_break_source_count:Math.max(1, Number(segment.source_count) || 1),
        automatic_break_fingerprint:String(segment.segment_fingerprint || ''),
        services:{ name:'Перерыв', duration_minutes:duration }
      };
    });
  }
  const buffer = Math.min(1440, Math.max(1, Number(bookingPolicy.booking_buffer_minutes) || 60));
  const date = parseLocalIsoDate(dateIso);
  if (!date) return [];
  const weekday = ((date.getDay() + 6) % 7) + 1;
  const schedule = scheduleRows.find(row => Number(row.weekday) === weekday);
  if (schedule?.enabled === false) return [];
  const workStart = minutesFromTime(schedule?.start_time || '10:00');
  const workEnd = minutesFromTime(schedule?.end_time || '20:00');
  if (workEnd <= workStart) return [];
  const active = items.filter(item => item.status !== 'cancelled' && item.booking_date === dateIso);
  const bookings = active.filter(item => !isScheduleBlock(item));
  if (!bookings.length) return [];
  const occupied = active.map(item => {
    const start = minutesFromTime(item.booking_time);
    return [start, start + Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60))];
  });
  const candidates = bookings.flatMap(item => {
    const start = minutesFromTime(item.booking_time);
    const end = start + Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60));
    const source = {
      bookingId:String(item.id || ''),
      bookingDate:item.booking_date,
      bookingTime:String(item.booking_time || '').slice(0, 5),
      duration:Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60))
    };
    return [
      { start:Math.max(workStart, start - buffer), end:start, side:'before', source },
      { start:end, end:Math.min(workEnd, end + buffer), side:'after', source }
    ];
  }).filter(candidate => candidate.end > candidate.start);
  const subtractRange = (segments, [occupiedStart, occupiedEnd]) => segments.flatMap(([start, end]) => {
    if (occupiedEnd <= start || occupiedStart >= end) return [[start, end]];
    return [[start, Math.min(end, occupiedStart)], [Math.max(start, occupiedEnd), end]].filter(([left, right]) => right > left);
  });
  const clearSegments = candidates.flatMap(candidate => {
    const segments = occupied.reduce((current, occupiedRange) => subtractRange(current, occupiedRange), [[candidate.start, candidate.end]]);
    return segments.map(([start, end]) => ({ start, end, sourceKey:`${candidate.source.bookingId}:${candidate.side}` }));
  }).sort((left, right) => left.start - right.start);
  const merged = [];
  clearSegments.forEach(({ start, end, sourceKey }) => {
    const previous = merged.at(-1);
    if (previous && start <= previous.end) {
      previous.end = Math.max(previous.end, end);
      previous.sources.add(sourceKey);
    } else merged.push({ start, end, sources:new Set([sourceKey]) });
  });
  return merged.map(({ start, end, sources }, index) => ({
    id:`automatic-break:${dateIso}:${start}:${end}:${index}`,
    performer_id:currentUser?.id || '',
    booking_date:dateIso,
    booking_time:`${timeFromMinutes(start)}:00`,
    duration_minutes:end - start,
    client_name:'Перерыв',
    client_phone:SCHEDULE_BLOCK_PHONE,
    status:'confirmed',
    automatic_break:true,
    automatic_break_source_count:sources.size,
    services:{ name:'Перерыв', duration_minutes:end - start }
  }));
}

async function loadAutomaticBookingBreaks(dateIso = selectedDate, userId = currentUser?.id, generation = sessionGeneration) {
  if (!userId || !parseLocalIsoDate(dateIso)) return { ok:false };
  const result = await db.rpc('get_minuta_provider_automatic_breaks_v158', { p_date:dateIso });
  if (!sessionIsCurrent(userId, generation)) return { ok:false, stale:true };
  if (result.error) {
    const missing = isMissingRpc(result.error, 'get_minuta_provider_automatic_breaks_v158');
    if (missing) {
      automaticBookingBreakSegments.delete(dateIso);
      automaticBookingBreaksRemoteAvailable = false;
    }
    return { ok:false, missing };
  }
  automaticBookingBreakSegments.set(dateIso, Array.isArray(result.data) ? result.data : []);
  automaticBookingBreaksRemoteAvailable = true;
  return { ok:true };
}

const SCHEDULE_CREATE_HINT_STORAGE_PREFIX = 'minuta-schedule-create-hint-v1';

function scheduleCreateHintStorageKey(userId = currentUser?.id) {
  return `${SCHEDULE_CREATE_HINT_STORAGE_PREFIX}:${userId || 'guest'}`;
}

function scheduleCreateHintVisible({ userId = currentUser?.id, hasExistingBookings = allBookings.length > 0 } = {}) {
  if (!userId) return false;
  const key = scheduleCreateHintStorageKey(userId);
  let state;
  try {
    state = localStorage.getItem(key);
    if (state === 'dismissed') return false;
    if (hasExistingBookings) {
      localStorage.setItem(key, 'dismissed');
      return false;
    }
    if (state === 'pending') return true;
    localStorage.setItem(key, hasExistingBookings ? 'dismissed' : 'pending');
  } catch { return !hasExistingBookings; }
  return !hasExistingBookings;
}

function scheduleCreateHintMarkup(options) {
  return scheduleCreateHintVisible(options) ? `<span class="timeline-create-hint">${uiIcon('plus')} Нажмите на свободное время</span>` : '';
}

function dismissScheduleCreateHint(userId = currentUser?.id, root = document) {
  if (!userId) return false;
  try { localStorage.setItem(scheduleCreateHintStorageKey(userId), 'dismissed'); } catch {}
  root.querySelectorAll?.('.timeline-create-hint').forEach(hint => hint.remove());
  return true;
}

function renderTimeline(sourceItems) {
  const operationalItems = sourceItems.filter(item => !item.is_imported_history);
  const items = [...sourceItems, ...automaticBookingBreaks(operationalItems)];
  const holder = $('#providerBookings');
  const mobileTimeline = window.matchMedia('(max-width: 760px)').matches;
  const fullBounds = timelineBounds(items);
  let { start, end } = fullBounds;
  const currentClock = selectedDate === businessTodayIso() ? businessClock() : null;
  const hourHeight = mobileTimeline ? 72 : 76;
  const naturalTimelineHeight = ((end - start) / 60) * hourHeight;
  const timelineItems = items.map((item, index) => {
    const itemStart = minutesFromTime(item.booking_time);
    const duration = Number(item.duration_minutes || item.services?.duration_minutes || 60);
    const top = ((itemStart - start) / 60) * hourHeight;
    const naturalHeight = (duration / 60) * hourHeight;
    const minuteOnly = duration <= 1;
    // Реальная высота одной минуты слишком мала для текста. Оставляем точные
    // время и длительность, но даём такой записи безопасную визуальную карточку.
    const height = minuteOnly ? (mobileTimeline ? 44 : 40) : mobileTimeline && duration < 30 ? 24 : Math.max(mobileTimeline ? 30 : 36, naturalHeight - 4);
    return { item, index, duration, top, visualTop:top, height, minuteOnly };
  });
  stackMinuteTimelineItems(timelineItems);
  const nextTimelineBookingId = currentClock
    ? timelineItems
      .filter(({ item }) => !item.automatic_break && item.status !== 'cancelled' && minutesFromTime(item.booking_time) > currentClock.minutes)
      .sort((left, right) => minutesFromTime(left.item.booking_time) - minutesFromTime(right.item.booking_time))[0]?.item?.id || ''
    : '';
  const totalHeight = Math.max(naturalTimelineHeight, ...timelineItems.map(entry => entry.visualTop + entry.height + 4));
  const labels = [];
  const lines = [];
  for (let minute = start; minute <= end; minute += 60) {
    const label = `${String(Math.floor(minute / 60)).padStart(2, '0')}:00`;
    const top = ((minute - start) / 60) * hourHeight;
    labels.push(`<span class="timeline-hour" style="top:${top}px">${label}</span>`);
    if (minute + 30 < end) labels.push(`<span class="timeline-hour timeline-half-hour" style="top:${top + hourHeight / 2}px">${String(Math.floor(minute / 60)).padStart(2, '0')}:30</span>`);
    lines.push(`<i class="timeline-grid-line" style="top:${top}px" aria-hidden="true"></i>`);
  }
  const cards = timelineItems.map(({ item, duration, top, visualTop, height, minuteOnly }) => {
    const startTime = String(item.booking_time).slice(0, 5);
    const endTime = timeFromMinutes(minutesFromTime(item.booking_time) + duration);
    const timeRange = `${startTime}–${endTime}`;
    const statusText = bookingStatus(item);
    const statusClass = bookingStatusClass(item);
    // Карточкам до 45 минут нужен компактный двухстрочный макет: обычные
    // внутренние отступы и крупная метка клиента не помещаются в их высоту.
    const compactMobile = mobileTimeline && height < 54;
    const compact = height < 54 ? ' compact' : '';
    const tightMobile = mobileTimeline && !minuteOnly && duration <= 60;
    const block = isScheduleBlock(item);
    const note = bookingDisplayNote(item);
    const notePresence = Boolean(note && (compactBookingCardsEnabled() || displayPreferences.show_notes));
    const visitText = block ? '' : bookingVisitSummaryText(item);
    const visitMarkup = block ? '' : bookingVisitSummaryMarkup(item, 'timeline-client-visit');
    const clientDetails = block ? (item.automatic_break ? 'Автоматический перерыв' : 'Занятое время') : [item.client_name, visitText, `${duration} мин`].filter(Boolean).join(' · ');
    const clientDetailsMarkup = block
      ? ''
      : `<span class="timeline-client-name">${escapeHtml(item.client_name)}</span>${visitMarkup ? `<span class="timeline-client-visit-wrap"> · ${visitMarkup}</span>` : ''}`;
    const timelineClientRow = compactMobile
      ? ''
      : tightMobile && !block
      ? `<span class="timeline-booking-client-row"><small class="timeline-booking-client"><span class="timeline-mobile-time">${timeRange} · </span><span class="timeline-client-name">${escapeHtml(item.client_name)}</span>${notePresence ? '<span> · есть заметка</span>' : ''}</small></span>`
      : `<span class="timeline-booking-client-row"><small class="timeline-booking-client"><span class="timeline-mobile-time">${timeRange}${block ? '' : ' · '}</span>${clientDetailsMarkup}</small></span>`;
    const ariaDetails = displayPreferences.show_notes && note ? `${clientDetails}, заметка: ${note}` : clientDetails;
    const highlightClasses = block ? '' : clientHighlightClasses(item.client_phone);
    const badgeDetails = block || !displayPreferences.show_client_labels ? '' : clientBadgeText(item.client_phone);
    const badgeMarkup = block || !displayPreferences.show_client_labels
      ? ''
      : clientBadgeMarkup(item.client_phone, tightMobile ? { limit:1, showLabels:false } : mobileTimeline ? { limit:1, showLabels:true } : { limit:1 });
    const imported = Boolean(item.is_imported_history);
    const moveRestriction = timelineMoveRestriction(item);
    const movable = !imported && !moveRestriction;
    const itemStartMinute = minutesFromTime(item.booking_time);
    const temporalClass = currentClock && item.status !== 'cancelled'
      ? currentClock.minutes >= itemStartMinute && currentClock.minutes < itemStartMinute + duration
        ? ' is-current-booking'
        : item.id === nextTimelineBookingId
          ? ' is-next-booking'
          : itemStartMinute + duration <= currentClock.minutes
            ? ' is-past-booking'
            : ''
      : '';
    const timelineStatus = block
      ? ''
      : imported
      ? `<span class="timeline-booking-status">Импортировано</span>`
      : statusClass === 'visited'
      ? `<span class="timeline-booking-status timeline-booking-status-icon"><span aria-hidden="true">${uiIcon('check')}</span><span class="sr-only">Статус: ${escapeHtml(statusText)}</span></span>`
      : `<span class="timeline-booking-status">${escapeHtml(statusText)}</span>`;
    const serviceMarkup = block ? escapeHtml(item.automatic_break ? 'Автоперерыв' : item.client_name || 'Перерыв') : timelineServiceNameMarkup(item.services?.name || 'Услуга', item.service_id);
    const automaticBreakSourceMarkup = item.automatic_break
      ? '<span class="timeline-automatic-break-source">Автоматический · из правил записи</span>'
      : '';
    const serviceTitleMarkup = block ? `${serviceMarkup}${automaticBreakSourceMarkup}` : `<span class="timeline-service-title">${serviceMarkup}</span><span class="timeline-service-duration">· ${duration} мин</span>`;
    const renderedNote = mobileTimeline ? '' : bookingNotePresenceMarkup(note, 'timeline-booking-note-presence');
    const renderedStatus = mobileTimeline ? '' : timelineStatus;
    const mobileBadgeMarkup = mobileTimeline ? badgeMarkup : '';
    const desktopBadgeMarkup = mobileTimeline ? '' : badgeMarkup;
    const cardContent = minuteOnly && !mobileTimeline
      ? `<span class="timeline-booking-copy timeline-booking-minute-copy"><strong><span class="timeline-booking-minute-time">${timeRange}</span><span aria-hidden="true"> · </span>${serviceTitleMarkup}</strong></span>`
      : `<span class="timeline-booking-time"><b>${startTime}</b><small>–${endTime}</small></span>
      <span class="timeline-booking-copy">${mobileBadgeMarkup}<strong>${serviceTitleMarkup}</strong>${timelineClientRow}${desktopBadgeMarkup}${renderedNote}</span>
      ${renderedStatus}`;
    const dragHandle = movable ? '<span class="timeline-drag-handle" aria-hidden="true"></span>' : '';
    const tight = tightMobile ? ' timeline-tight' : '';
    const className = `timeline-booking status-${statusClass} color-${bookingColor(item)}${compact}${tight}${minuteOnly ? ' minute-only' : ''}${item.automatic_break ? ' automatic-break' : ''}${imported ? ' is-imported-history' : ''}${notePresence ? ' has-note' : ''}${highlightClasses}${temporalClass}${item.id === recentlyCreatedBookingId ? ' booking-created-highlight' : ''}`;
    const ariaLabel = `${escapeHtml(block ? (item.client_name || 'Занятое время') : serviceName(item.services?.name || 'Услуга'))}, с ${startTime} до ${endTime}, ${escapeHtml(ariaDetails)}${badgeDetails ? `, метки клиента: ${escapeHtml(badgeDetails)}` : ''}, статус: ${escapeHtml(item.automatic_break ? 'автоматический перерыв' : statusText)}`;
    const timelineStyle = `top:${visualTop + 2}px;height:${height}px${tightMobile ? ';padding:5px 9px!important;overflow:hidden!important' : ''}`;
    return item.automatic_break
      ? `<button class="${className}" type="button" data-open-automatic-break data-automatic-break-date="${escapeHtml(item.booking_date)}" data-automatic-break-start="${startTime}" data-automatic-break-end="${endTime}" data-automatic-break-source-count="${Number(item.automatic_break_source_count) || 1}" data-automatic-break-fingerprint="${escapeHtml(item.automatic_break_fingerprint || '')}" data-booking-duration="${duration}" data-mobile-timeline-top="${top + 2}" style="${timelineStyle}" aria-haspopup="dialog" aria-controls="bookingSheet" aria-label="${ariaLabel}. Открыть управление перерывом" title="Открыть управление автоматическим перерывом">${cardContent}</button>`
      : `<button class="${className}" type="button" data-open-booking="${item.id}" ${imported ? 'data-imported-history' : ''} ${movable ? 'data-timeline-movable aria-describedby="timelineMoveInstruction" aria-keyshortcuts="Shift+ArrowUp Shift+ArrowDown"' : ''} data-booking-duration="${duration}" data-mobile-timeline-top="${top + 2}" style="${timelineStyle}" aria-label="${ariaLabel}" title="${imported ? 'Импортированная запись · только просмотр' : moveRestriction || 'Перетащите или нажмите Shift и стрелку, чтобы изменить время'}">${cardContent}${dragHandle}</button>`;
  }).join('');
  const nowMarker = scheduleNowMarkerMarkup(selectedDate, start, end, hourHeight, 'timeline-now-marker');
  const emptyHintTop = Math.max(30, Math.min(120, Math.max(60, 720 - start), (end - start) / 2)) / 60 * hourHeight;
  holder.className = 'provider-bookings timeline-view';
  holder.innerHTML = `<div class="day-timeline" style="--timeline-height:${totalHeight}px;--half-hour-offset:${hourHeight / 2}px;--timeline-empty-hint-top:${emptyHintTop}px"><div class="timeline-hours">${labels.join('')}</div><div class="timeline-stage" data-create-booking-at data-timeline-date="${selectedDate}" data-timeline-start="${start}" data-timeline-end="${end}" data-timeline-natural-height="${naturalTimelineHeight}" data-timeline-keyboard-minute="${start}" role="group" tabindex="0" aria-label="Выбор свободного времени. Выбрано ${timeFromMinutes(start)}. Стрелками измените время, Enter создаст запись">${lines.join('')}${nowMarker}${scheduleCreateHintMarkup()}${cards || `<div class="timeline-empty-state"><span>${uiIcon('plus')}</span><strong>День свободен</strong><small>Нажмите на нужное время, чтобы записать клиента или поставить перерыв</small></div>`}</div></div>`;
  if (typeof updateScheduleNowMarkers === 'function') updateScheduleNowMarkers();
}

function renderBookingList(items, emptyMessage = 'На выбранный период всё свободно.') {
  const holder = $('#providerBookings');
  const mobileList = window.matchMedia('(max-width: 760px)').matches;
  holder.className = 'provider-bookings schedule-list';
  holder.dataset.recordsFilter = currentFilter;
  if (!items.length) {
    holder.innerHTML = bookingEmptyMarkup(emptyMessage);
    applyWriteAvailability();
    return;
  }
  const dateFormat = new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'short', weekday: 'short' });
  holder.innerHTML = items.map(item => {
    const itemDate = new Date(`${item.booking_date}T12:00:00`);
    const time = String(item.booking_time).slice(0, 5);
    const duration = Number(item.duration_minutes || item.services?.duration_minutes || 60);
    const endTime = timeFromMinutes(minutesFromTime(time) + duration);
    const statusText = bookingStatus(item);
    const statusClass = bookingStatusClass(item);
    const phone = escapeHtml(String(item.client_phone || ''));
    const resultSummary = item.is_imported_history || bookingOutcome(item).visit_status === 'no_show' ? '' : outcomeSummary(item);
    const block = isScheduleBlock(item);
    const note = bookingDisplayNote(item);
    const notePresence = bookingNotePresenceMarkup(note, 'provider-booking-note-presence');
    const visitMarkup = block ? '' : bookingVisitSummaryMarkup(item);
    const fullTitle = block ? (item.client_name || 'Перерыв') : serviceName(item.services?.name || 'Услуга');
    const title = block ? fullTitle : serviceScheduleName(fullTitle, item.service_id);
    const breakOrigin = item.automatic_break ? 'Автоматический · по правилам' : 'Ручной';
    const details = block ? `${breakOrigin} перерыв` : [item.client_name, displayPreferences.show_phone ? item.client_phone : '', bookingVisitSummaryText(item)].filter(Boolean).join(', ');
    const openAttributes = item.automatic_break
      ? `data-open-automatic-break data-automatic-break-date="${escapeHtml(item.booking_date)}" data-automatic-break-start="${time}" data-automatic-break-end="${endTime}" data-automatic-break-source-count="${Number(item.automatic_break_source_count) || 1}" data-automatic-break-fingerprint="${escapeHtml(item.automatic_break_fingerprint || '')}" data-booking-duration="${duration}" aria-haspopup="dialog" aria-controls="bookingSheet"`
      : `data-open-booking="${escapeHtml(item.id)}"`;
    const actionLabel = item.automatic_break ? 'Открыть управление перерывом' : 'Открыть подробности';
    return `<article class="provider-booking status-${statusClass} color-${bookingColor(item)}${item.is_imported_history ? ' is-imported-history' : ''}${block ? ' is-schedule-block' : clientHighlightClasses(item.client_phone)}${item.automatic_break ? ' automatic-break' : ''}${item.id === recentlyCreatedBookingId ? ' booking-created-highlight' : ''}">
      <button class="provider-booking-open" type="button" ${openAttributes} aria-label="${escapeHtml(fullTitle)}, с ${time} до ${endTime}, ${escapeHtml(details)}. ${actionLabel}">
        <span class="booking-time-column"><strong>${time}<small>до ${endTime}</small></strong><span>${dateFormat.format(itemDate)}</span></span>
        <span class="booking-main"><span class="provider-booking-top"><h3>${escapeHtml(title)}</h3></span>
        ${block ? `<span class="provider-booking-client-line"><span class="booking-break-origin">${breakOrigin}</span></span>` : `<span class="provider-booking-client-line"><span class="booking-client-name-row"><strong>${escapeHtml(item.client_name)}</strong>${displayPreferences.show_client_labels ? clientBadgeMarkup(item.client_phone, { limit:1, showLabels:mobileList }) : ''}</span>${displayPreferences.show_phone ? `<span class="provider-booking-phone">${phone}</span>` : ''}</span>`}
        <span class="provider-booking-signals">${block ? '' : `<span class="booking-status">${statusText}</span>${visitMarkup}`}${bookingSeriesMarkup(item)}${notePresence}${Number(item.deposit_amount_rub || 0) > 0 ? `<span class="booking-prepayment-badge status-${escapeHtml(item.payment_status)}">${item.payment_status === 'paid' ? 'Оплачено' : item.payment_status === 'refunded' ? 'Возврат' : 'Ждёт оплаты'}</span>` : ''}${resultSummary ? `<span class="booking-outcome-summary">${escapeHtml(resultSummary)}</span>` : ''}</span></span>
        <span class="provider-booking-chevron" aria-hidden="true">›</span>
      </button>
    </article>`;
  }).join('');
}

function bookingEmptyMarkup(message, extraClass = '') {
  return `<div class="provider-empty schedule-empty${extraClass ? ` ${escapeHtml(extraClass)}` : ''}"><span class="provider-empty-icon">${uiIcon('check')}</span><strong>Записей нет</strong><small>${escapeHtml(message)}</small><button class="primary schedule-empty-create" type="button" data-create-empty-booking>${uiIcon('plus')}<span>Создать запись</span></button></div>`;
}

function bookingClientProfileActionMarkup(item, { primary = false } = {}) {
  const phone = normalizePhone(item?.client_phone);
  if (!phone || isScheduleBlock(item)) return '';
  return `<button class="${primary ? 'primary ' : 'secondary-button '}booking-client-profile-action" type="button" data-open-client-profile="${escapeHtml(phone)}" data-client-booking-id="${escapeHtml(item.id)}">${uiIcon('user')}<span>Открыть карточку клиента</span></button>`;
}

function clientCompletedVisits(client, now = new Date()) {
  return (client?.bookings || []).filter(item => {
    const outcome = bookingOutcome(item);
    if (outcome.visit_status === 'completed') return true;
    if (outcome.visit_status === 'no_show') return false;
    return item.status !== 'cancelled' && new Date(`${item.booking_date}T${String(item.booking_time).slice(0,8)}`) < now;
  });
}

function clientRelationshipFacts(client, completedVisits = clientCompletedVisits(client)) {
  const importedRows = completedVisits.filter(item => item.is_imported_history).length;
  const visits = completedVisits.length - importedRows + Math.max(importedRows, Number(client?.imported?.visit_count || 0));
  const relationship = window.PrimeTimeClientRelationship;
  if (!relationship) return {
    visits,
    level:0,title:'Новый клиент',progress:0,milestone:'До первого визита — 1 визит'
  };
  const facts = relationship.relationship({
    completedVisits:visits
  });
  const reliability = relationship.reliability((client?.bookings || []).map(item => ({
    bookingDate:item.booking_date,
    bookingTime:item.booking_time,
    status:item.status,
    cancellationReason:item.cancellation_reason || '',
    visitStatus:bookingOutcome(item).visit_status
  })));
  return { ...facts, reliability };
}

function clientNextBookingAfter(client, currentItem, now = new Date()) {
  const currentStart = new Date(`${currentItem?.booking_date || ''}T${String(currentItem?.booking_time || '').slice(0,8)}`);
  const threshold = Number.isNaN(currentStart.getTime()) || currentStart < now ? now : currentStart;
  return (client?.bookings || [])
    .filter(candidate => {
      if (String(candidate.id || '') === String(currentItem?.id || '')) return false;
      if (candidate.status === 'cancelled' || bookingOutcome(candidate).visit_status !== 'scheduled') return false;
      const candidateStart = new Date(`${candidate.booking_date}T${String(candidate.booking_time).slice(0,8)}`);
      return !Number.isNaN(candidateStart.getTime()) && candidateStart > threshold;
    })
    .sort((left, right) => `${left.booking_date}T${left.booking_time}`.localeCompare(`${right.booking_date}T${right.booking_time}`))[0] || null;
}

function bookingClientOverviewMarkup(item, now = new Date()) {
  const phone = normalizePhone(item?.client_phone);
  const client = buildClients().find(entry => entry.phone === phone);
  if (!client) return '';
  const completedVisits = clientCompletedVisits(client, now);
  const visits = Math.max(completedVisits.length, Number(client.imported?.visit_count || 0));
  const spent = completedVisits.reduce((sum, booking) => sum + Math.max(0, Number(bookingOutcome(booking).amount_rub || 0)), 0);
  const upcoming = clientNextBookingAfter(client, item, now);
  const lastVisit = [...completedVisits].sort((left, right) => `${right.booking_date}${right.booking_time}`.localeCompare(`${left.booking_date}${left.booking_time}`))[0];
  const lastVisitDate = lastVisit?.booking_date || client.imported?.last_visit_on || '';
  const lastVisitText = lastVisitDate ? new Date(`${lastVisitDate}T12:00:00`).toLocaleDateString('ru-RU', { day:'numeric', month:'short', year:'numeric' }) : '';
  const upcomingText = upcoming ? `${new Date(`${upcoming.booking_date}T12:00:00`).toLocaleDateString('ru-RU', { day:'numeric', month:'short' })} · ${String(upcoming.booking_time).slice(0,5)}` : '';
  const currentServiceKey = favoriteServiceNameKey(item?.services?.name || '');
  const favorites = clientFavoriteServiceFacts(completedVisits.filter(booking => favoriteServiceNameKey(booking.services?.name || '') !== currentServiceKey))
    .map(service => service.name)
    .filter(name => favoriteServiceNameKey(name) !== currentServiceKey);
  const hasHistory = visits > 0 || spent > 0 || Boolean(lastVisitDate);
  const historyMarkup = hasHistory
    ? `<article class="booking-client-history"><small>Последний визит</small><strong>${escapeHtml(lastVisitText || 'Дата неизвестна')}</strong></article>`
    : '<article class="booking-client-history is-empty"><small>История посещений</small><strong>Пока нет</strong></article>';
  const upcomingMarkup = upcoming
    ? `<article class="booking-client-next"><small>Следующая запись</small><strong>${escapeHtml(upcomingText)}</strong><span>${escapeHtml(serviceName(upcoming.services?.name || 'Услуга'))}</span></article>`
    : '<article class="booking-client-next is-empty"><small>Следующая запись</small><strong>Не запланирована</strong><span>После этой записи новых визитов нет</span></article>';
  const summary = hasHistory ? `История клиента · ${visits} ${reportVisitWord(visits)} · ${money(spent)}` : 'Первый визит';
  return `<details class="booking-client-overview booking-sheet-disclosure${hasHistory ? '' : ' is-first-visit'}">
    <summary><strong>${escapeHtml(summary)}</strong></summary>
    <div class="booking-client-overview-body" aria-label="Сведения о клиенте">
      <div class="booking-client-overview-stats">${historyMarkup}${upcomingMarkup}</div>
      ${favorites.length ? `<div class="booking-client-overview-favorites"><small>Любимые услуги</small><span>${favorites.map(name => `<b>${escapeHtml(name)}</b>`).join('')}</span></div>` : ''}
    </div>
  </details>`;
}

function bookingDetailSeriesMarkup(item) {
  const occurrence = Number(item?.series_occurrence || 0);
  const storedTotal = Number(item?.booking_series?.occurrence_count || 0);
  const total = item?.series_id
    ? Math.max(storedTotal, occurrence, ...allBookings.filter(entry => entry.series_id === item.series_id).map(entry => Number(entry.series_occurrence || 0)))
    : 0;
  return item?.series_id && occurrence > 0
    ? `<span class="booking-detail-series">Серия · ${occurrence}${total > 1 ? ` из ${total}` : ''}</span>`
    : '';
}

function bookingDetailHeaderMarkup(item, date, duration, statusText, statusClass, priceText, extraMarkup = '') {
  const imported = Boolean(item?.is_imported_history);
  const compactStatus = imported ? 'Импорт' : bookingStatus(item);
  const statusAccessibility = compactStatus !== statusText ? ` aria-label="${escapeHtml(statusText)}" title="${escapeHtml(statusText)}"` : '';
  return `<div class="booking-detail-heading">
      <small class="booking-sheet-kicker">${date.toLocaleDateString('ru-RU', { day:'numeric', month:'long', weekday:'long' })}</small>
      <span class="booking-status status-${statusClass}"${statusAccessibility}>${escapeHtml(compactStatus)}</span>
    </div>
    <h2 id="bookingSheetTitle">${escapeHtml(serviceName(item.services?.name || 'Услуга'))}</h2>
    <div class="booking-detail-facts" aria-label="${escapeHtml(`Время ${String(item.booking_time).slice(0, 5)}, длительность ${duration} минут, стоимость ${priceText}`)}">
      <strong>${String(item.booking_time).slice(0, 5)}</strong><i aria-hidden="true">·</i><span>${duration} мин</span><i aria-hidden="true">·</i><span>${escapeHtml(priceText)}</span>
    </div>
    ${extraMarkup ? `<div class="booking-detail-signals">${extraMarkup}</div>` : ''}`;
}

function bookingDetailClientMarkup(item, { editableAvatar = true } = {}) {
  const phoneValue = String(item?.client_phone || '');
  const phoneHref = escapeHtml(phoneValue.replace(/[^+\d]/g, ''));
  const avatar = editableAvatar
    ? clientAvatarEditorMarkup(item.client_phone, item.client_name, item.id)
    : `<span class="booking-sheet-client-avatar">${clientAvatarContent(item.client_phone, item.client_name)}</span>`;
  return `<div class="booking-sheet-client">${avatar}<div class="booking-sheet-client-copy"><div class="booking-sheet-client-name"><strong>${escapeHtml(item.client_name || 'Клиент')}</strong>${clientBadgeMarkup(item.client_phone, { limit:1, showLabels:true })}</div><a href="tel:${phoneHref}">${escapeHtml(phoneValue)}</a></div></div>`;
}

function bookingClientResultMarkup(item) {
  if (!item || item.status === 'cancelled') return '';
  return `<details class="booking-sheet-disclosure booking-client-result-disclosure" id="bookingClientResultDisclosure">
    <summary><div><small>До и после сеанса</small><strong>Фото и результат</strong></div><span>${uiIcon('image')}<span data-booking-result-summary>Не заполнено</span></span></summary>
    <form class="booking-visit-result-form" id="bookingVisitResultForm" data-booking-id="${escapeHtml(item.id)}">
      <a class="settings-help-link" href="help/article.html?slug=client-private-results" target="_blank" rel="noopener noreferrer">Как хранится приватно <span aria-hidden="true">↗</span></a>
      <button class="primary" type="submit">Сохранить результат</button>
    </form>
  </details>`;
}

function focusCreatedBooking(id) {
  recentlyCreatedBookingId = String(id || '');
  if (!recentlyCreatedBookingId) return;
  if (recentlyCreatedBookingTimer) clearTimeout(recentlyCreatedBookingTimer);
  renderBookingData();
  requestAnimationFrame(() => {
    const card = $$('[data-open-booking]').find(item => item.dataset.openBooking === recentlyCreatedBookingId);
    card?.scrollIntoView({ behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block:'center' });
    card?.focus({ preventScroll:true });
  });
  recentlyCreatedBookingTimer = setTimeout(() => {
    recentlyCreatedBookingId = '';
    $$('.booking-created-highlight').forEach(card => card.classList.remove('booking-created-highlight'));
  }, 4200);
}

function openBookingSheet(id) {
  const item = bookingSourceItems().find(booking => booking.id === id);
  if (!item) return;
  $('#bookingSheet').dataset.bookingId = String(item.id || '');
  $('#bookingSheet').dataset.assistantContext = 'booking';
  const date = new Date(`${item.booking_date}T12:00:00`);
  const duration = Number(item.duration_minutes || item.services?.duration_minutes || 60);
  const statusText = bookingStatus(item, true);
  const statusClass = bookingStatusClass(item);
  const messageButton = clientMessageButtonMarkup(item);
  const conversationButton = providerConversationButtonMarkup(item);
  const note = bookingDisplayNote(item);
  const outcome = bookingOutcome(item);
  const minuteRate = bookingMinuteRate(item);
  const actualMinutes = Number(outcome.actual_duration_minutes || 0);
  const calculatedAmount = Number(outcome.calculated_amount_rub || (actualMinutes ? actualMinutes * minuteRate : bookingSessionTotal(item)));
  const amount = Number(outcome.amount_rub || calculatedAmount);
  $('#bookingSheet').classList.remove('booking-sheet-wide', 'new-booking-sheet', 'booking-sheet-detail');
  applyClientHighlightClasses($('#bookingSheet'), isScheduleBlock(item) ? '' : item.client_phone, 'booking-sheet-');
  if (item.is_imported_history) {
    const sourceName = String(item.source_provider_name || 'Прежний журнал').trim();
    $('#bookingSheet').classList.add('booking-sheet-detail');
    $('#bookingSheetContent').innerHTML = `${bookingDetailHeaderMarkup(item, date, duration, statusText, statusClass, money(bookingSessionTotal(item)))}
      <div class="booking-sheet-summary">${bookingDetailClientMarkup(item, { editableAvatar:false })}</div>
      ${bookingClientOverviewMarkup(item)}
      <div class="booking-sheet-actions booking-detail-primary-action">${bookingClientProfileActionMarkup(item, { primary:true })}</div>
      <details class="booking-sheet-disclosure imported-history-readonly"><summary><strong>Импорт · ${escapeHtml(sourceName)}</strong></summary><div class="imported-history-readonly-body"><strong>Архивная запись доступна только для просмотра.</strong>${item.source_note ? `<p>${escapeHtml(item.source_note)}</p>` : ''}</div></details>`;
    $('#bookingSheet').hidden = false;
    document.body.classList.add('booking-sheet-open');
    return;
  }
  if (isScheduleBlock(item)) {
    $('#bookingSheetContent').innerHTML = `<small class="booking-sheet-kicker">${date.toLocaleDateString('ru-RU', { day:'numeric', month:'long', weekday:'long' })}</small>
      <h2 id="bookingSheetTitle">${escapeHtml(item.client_name || 'Перерыв')}</h2>
      <div class="booking-sheet-meta"><strong>${String(item.booking_time).slice(0, 5)}</strong><span>${duration} минут</span><span class="booking-status status-block">Занято</span></div>
      <div class="booking-sheet-block"><span>◼</span><div><small>Блокировка времени</small><strong>Клиенты не смогут записаться на этот интервал.</strong></div></div>
      ${bookingColorPicker(`bookingColor-${item.id}`, bookingColor(item), item.id)}
      <details class="booking-sheet-disclosure booking-note-disclosure" ${note ? 'open' : ''}>
        <summary><div><small>О перерыве</small><strong>Заметка</strong></div><span class="booking-note-state">${note ? 'Добавлена' : 'Добавить'}</span></summary>
        <form class="booking-sheet-note-editor" id="bookingBlockNoteForm" data-booking-id="${item.id}">
          <label class="sr-only" for="bookingBlockNote">Заметка к перерыву</label><textarea id="bookingBlockNote" maxlength="1000" rows="2" placeholder="Например, обед или личное дело">${escapeHtml(note)}</textarea>
          <button class="secondary-button" type="submit">Сохранить заметку</button>
        </form>
      </details>
      ${item.status !== 'cancelled' ? `<div class="booking-sheet-actions"><button class="primary" type="button" data-edit-booking="${item.id}">Изменить</button><button class="secondary-button danger" type="button" data-booking-status="cancelled" data-booking-id="${item.id}">Освободить время</button></div>` : ''}
      <div class="booking-delete-zone"><button class="booking-delete-action" type="button" data-delete-booking="${item.id}">Удалить время навсегда</button></div>`;
    $('#bookingSheet').hidden = false;
    document.body.classList.add('booking-sheet-open');
    $('#bookingBlockNoteForm')?.addEventListener('submit', saveBookingBlockNote);
    return;
  }
  $('#bookingSheet').classList.add('booking-sheet-detail');
  const bookingDetailPrice = isPerMinuteBooking(item) ? `${money(minuteRate)}/мин` : money(bookingSessionTotal(item));
  $('#bookingSheetContent').innerHTML = `${bookingDetailHeaderMarkup(item, date, duration, statusText, statusClass, bookingDetailPrice, `${autoCompleteSettingsActionMarkup(item)}${bookingDetailSeriesMarkup(item)}`)}
    <div class="booking-sheet-summary">${bookingDetailClientMarkup(item)}</div>
    ${bookingClientOverviewMarkup(item)}
    <div class="booking-sheet-actions booking-repeat-actions">${bookingClientProfileActionMarkup(item, { primary:true })}<button class="secondary-button booking-repeat-action" type="button" data-repeat-booking="${item.id}">${uiIcon('refresh')} Повторить запись</button><button class="secondary-button booking-repeat-action" type="button" data-commerce-booking-sale="${item.id}">${uiIcon('plus')} Продать</button></div>
    <div class="booking-sheet-secondary">
    ${bookingSessionMarkup(item)}
    ${bookingClientLabelsMarkup(item.client_phone, item.id)}
    ${compactBookingColorPicker(`bookingColor-${item.id}`, bookingColor(item), item.id)}
    <details class="booking-sheet-disclosure booking-note-disclosure" ${note ? 'open' : ''}>
      <summary><div><small>О клиенте</small><strong>Заметка</strong></div><span class="booking-note-state">${note ? 'Добавлена' : 'Добавить'}</span></summary>
      <form class="booking-sheet-note-editor" id="bookingSheetNoteForm" data-client-phone="${escapeHtml(normalizePhone(item.client_phone))}">
        <label class="sr-only" for="bookingSheetClientNote">Заметка о клиенте</label><textarea id="bookingSheetClientNote" maxlength="1000" rows="2" placeholder="Пожелания, особенности или важная информация">${escapeHtml(note)}</textarea>
        <button class="secondary-button" type="submit">Сохранить заметку</button>
      </form>
    </details>
    ${Number(item.deposit_amount_rub || 0) > 0 ? `<form class="booking-prepayment-form" id="bookingPrepaymentForm" data-booking-id="${item.id}"><div><small>До визита</small><h3>Предоплата ${money(item.deposit_amount_rub)}</h3></div><label>Статус<select id="bookingPrepaymentStatus"><option value="pending" ${item.payment_status === 'pending' ? 'selected' : ''}>Ожидается</option><option value="paid" ${item.payment_status === 'paid' ? 'selected' : ''}>Оплачено</option><option value="refunded" ${item.payment_status === 'refunded' ? 'selected' : ''}>Возвращено</option></select></label><button class="secondary-button" type="submit">Сохранить предоплату</button></form>` : ''}
    ${bookingClientResultMarkup(item)}
    ${quickVisitOutcomeMarkup(item)}
    ${item.status !== 'cancelled' ? `<details class="booking-sheet-disclosure booking-outcome-disclosure" ${outcome.visit_status === 'scheduled' ? '' : 'open'}><summary><div><small>После визита</small><strong>Результат и оплата</strong></div><span>${uiIcon(outcome.visit_status === 'completed' ? 'check' : outcome.visit_status === 'no_show' ? 'close' : 'clock')}${automaticOutcomeHint(item) || outcomeVisitLabel(outcome)}</span></summary><form class="booking-outcome-form" id="bookingOutcomeForm" data-booking-id="${item.id}" data-minute-rate="${minuteRate}"><label>Результат визита<select id="outcomeVisitStatus"><option value="scheduled" ${outcome.visit_status === 'scheduled' ? 'selected' : ''}>Запланирован</option><option value="completed" ${outcome.visit_status === 'completed' ? 'selected' : ''}>Состоялся</option><option value="no_show" ${outcome.visit_status === 'no_show' ? 'selected' : ''}>Не пришёл</option></select></label><div id="outcomePaymentFields" ${outcome.visit_status === 'completed' ? '' : 'hidden'}>${isPerMinuteBooking(item) ? `<div class="booking-minute-calculator"><label>Фактическое время, мин<input id="outcomeActualMinutes" type="number" min="1" max="1440" step="1" value="${actualMinutes || ''}" placeholder="Например, 37" required></label><div><small>Расчёт</small><strong id="outcomeCalculatedAmount">${actualMinutes ? `${actualMinutes} × ${money(minuteRate)} = ${money(calculatedAmount)}` : `Укажите минуты · ${money(minuteRate)}/мин`}</strong></div></div>` : ''}<div class="booking-outcome-payment"><label>Оплата<select id="outcomePaymentMethod"><option value="unpaid" ${outcome.payment_method === 'unpaid' ? 'selected' : ''}>Не оплачено</option><option value="cash" ${outcome.payment_method === 'cash' ? 'selected' : ''}>Наличные</option><option value="transfer" ${outcome.payment_method === 'transfer' ? 'selected' : ''}>Перевод</option><option value="card" ${outcome.payment_method === 'card' ? 'selected' : ''}>Карта</option></select></label><label>Получено, ₽<input id="outcomeAmount" type="number" min="0" max="1000000" step="1" value="${amount}"></label></div></div><button class="primary" type="submit">Сохранить результат</button></form></details>` : ''}
    </div>
    ${conversationButton || messageButton ? `<div class="booking-sheet-actions booking-message-actions">${conversationButton}${messageButton}</div>` : ''}
    ${item.status !== 'cancelled' && !bookingIsCompleted(item) ? `<div class="booking-sheet-actions">${item.status === 'new' ? `<button class="primary" type="button" data-booking-status="confirmed" data-booking-id="${item.id}">Подтвердить</button>` : ''}<button class="secondary-button" type="button" data-edit-booking="${item.id}">Перенести</button>${item.series_id ? `<button class="secondary-button danger" type="button" data-cancel-booking-series="${item.id}">Отменить</button>` : ''}</div>` : ''}
    <div class="booking-delete-zone"><button class="booking-delete-action" type="button" data-delete-booking="${item.id}">Удалить запись</button></div>`;
  $('#bookingSheet').hidden = false;
  document.body.classList.add('booking-sheet-open');
  if (bookingUsesDemoData()) {
    $('#bookingSheetContent').querySelectorAll('.booking-repeat-actions,.booking-sheet-secondary,.booking-sheet-actions,.booking-delete-zone').forEach(element => { element.hidden = true; });
    return;
  }
  clientResultsController.mount({ form:$('#bookingVisitResultForm'), booking:item, expandEditor:true });
  $('#bookingVisitResultForm')?.addEventListener('submit', saveBookingVisitResult);
  $('#bookingOutcomeForm')?.addEventListener('submit', saveBookingOutcome);
  $('#bookingPrepaymentForm')?.addEventListener('submit', savePrepaymentStatus);
  $('#bookingSheetNoteForm')?.addEventListener('submit', saveBookingSheetNote);
  $('#outcomeVisitStatus')?.addEventListener('change', toggleOutcomePaymentFields);
  $('#outcomeActualMinutes')?.addEventListener('input', updateOutcomeMinuteCalculation);
  $('#outcomePaymentMethod')?.addEventListener('change', () => { updateOutcomeMinuteCalculation(); toggleOutcomePaymentFields(); });
  toggleOutcomePaymentFields();
  updateOutcomeMinuteCalculation();
}

function automaticBreakReleaseAttemptKey(userId = currentUser?.id) {
  return `minuta-automatic-break-release-v158-${userId || 'anonymous'}`;
}

function readAutomaticBreakReleaseAttempt(userId = currentUser?.id) {
  try { return JSON.parse(sessionStorage.getItem(automaticBreakReleaseAttemptKey(userId)) || 'null'); }
  catch { return null; }
}

function writeAutomaticBreakReleaseAttempt(attempt, userId = currentUser?.id) {
  try { sessionStorage.setItem(automaticBreakReleaseAttemptKey(userId), JSON.stringify(attempt)); }
  catch { /* A private browser may deny session storage; server idempotency still applies to this attempt. */ }
}

function clearAutomaticBreakReleaseAttempt(requestId = '', userId = currentUser?.id) {
  try {
    const attempt = readAutomaticBreakReleaseAttempt(userId);
    if (!requestId || attempt?.requestId === requestId) sessionStorage.removeItem(automaticBreakReleaseAttemptKey(userId));
  } catch { /* no-op */ }
}

function trapBookingSheetFocus(event) {
  const sheet = $('#bookingSheet');
  if (event.key !== 'Tab' || sheet?.hidden) return;
  const panel = sheet.querySelector('.booking-sheet-panel');
  const focusable = [...panel.querySelectorAll('a[href], button:not([disabled]), summary, input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])')]
    .filter(element => !element.hidden && element.getAttribute('aria-hidden') !== 'true');
  if (!focusable.length) { event.preventDefault(); panel.focus?.(); return; }
  const first = focusable[0];
  const last = focusable.at(-1);
  if (event.shiftKey && (document.activeElement === first || !panel.contains(document.activeElement))) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && (document.activeElement === last || !panel.contains(document.activeElement))) {
    event.preventDefault();
    first.focus();
  }
}

$('#bookingSheet')?.addEventListener('keydown', trapBookingSheetFocus);

function openAutomaticBreakSheet(source) {
  const dateIso = String(source?.dataset.automaticBreakDate || '');
  const start = String(source?.dataset.automaticBreakStart || '').slice(0, 5);
  const end = String(source?.dataset.automaticBreakEnd || '').slice(0, 5);
  const sourceCount = Math.max(1, Number(source?.dataset.automaticBreakSourceCount) || 1);
  const fingerprint = String(source?.dataset.automaticBreakFingerprint || '');
  const date = parseLocalIsoDate(dateIso);
  if (!date || !/^\d{2}:\d{2}$/.test(start) || !/^\d{2}:\d{2}$/.test(end)) return;
  const sheet = $('#bookingSheet');
  automaticBreakSheetInvoker = source;
  sheet.dataset.assistantContext = 'automatic-break';
  sheet.classList.remove('booking-sheet-wide');
  $('#bookingSheetContent').innerHTML = `<small class="booking-sheet-kicker">${date.toLocaleDateString('ru-RU', { day:'numeric', month:'long', weekday:'long' })}</small>
    <h2 id="bookingSheetTitle">Автоматический перерыв</h2>
    <div class="booking-sheet-meta"><strong>${start}–${end}</strong><span>Из правил записи</span></div>
    <div class="booking-sheet-block automatic-break-explanation"><span aria-hidden="true">◼</span><div><small>Буфер до или после записи</small><strong>Это время закрыто автоматически, чтобы между визитами оставался перерыв.</strong><p>${sourceCount > 1 ? `Интервал образован ${sourceCount} пересекающимися буферами. Освобождение завершится только после безопасного исключения каждого источника.` : 'Можно освободить только этот интервал. Остальные автоматические и ручные перерывы останутся.'}</p></div></div>
    <div class="booking-sheet-actions automatic-break-actions">
      <button class="primary" type="button" data-release-automatic-break data-automatic-break-date="${escapeHtml(dateIso)}" data-automatic-break-start="${start}" data-automatic-break-end="${end}" data-automatic-break-source-count="${sourceCount}" data-automatic-break-fingerprint="${escapeHtml(fingerprint)}" ${automaticBookingBreaksRemoteAvailable && fingerprint ? '' : 'disabled'}>Освободить только это время</button>
      <button class="secondary-button" type="button" data-open-automatic-break-settings>Настроить правило</button>
    </div>
    ${automaticBookingBreaksRemoteAvailable && fingerprint ? '' : '<p class="booking-sheet-warning">Точечное освобождение станет доступно после проверки интервала сервером.</p>'}
    <div class="booking-delete-zone"><button class="booking-delete-action" type="button" data-disable-automatic-breaks>Отключить все автоматические перерывы</button></div>`;
  sheet.hidden = false;
  document.body.classList.add('booking-sheet-open');
  applyWriteAvailability();
  requestAnimationFrame(() => $('#bookingSheetContent [data-release-automatic-break]:not(:disabled), #bookingSheetContent [data-open-automatic-break-settings]')?.focus());
}

async function openAutomaticBreakSettings() {
  automaticBreakSheetInvoker = null;
  closeBookingSheet();
  await Promise.resolve(setProviderView('settings'));
  await new Promise(resolve => requestAnimationFrame(resolve));
  const sectionButton = $('[data-provider-panel="settings"] [data-section-target="bookingRulesCard"]')
    || $('[data-section-target="bookingRulesCard"]');
  if (sectionButton) scrollToProviderSection(sectionButton);
  const details = $('#bookingRulesCard .booking-advanced-settings');
  if (details) details.open = true;
  const input = $('#bookingBufferEnabled');
  const setting = input?.closest('.booking-buffer-setting');
  setting?.classList.add('is-guided');
  requestAnimationFrame(() => input?.focus({ preventScroll:true }));
  setTimeout(() => setting?.classList.remove('is-guided'), 1800);
}

async function releaseAutomaticBreak(button) {
  if (!requireWrites() || !automaticBookingBreaksRemoteAvailable) return;
  const userId = currentUser?.id || '';
  const generation = sessionGeneration;
  if (!userId) return;
  const dateIso = String(button.dataset.automaticBreakDate || '');
  const start = String(button.dataset.automaticBreakStart || '').slice(0, 5);
  const end = String(button.dataset.automaticBreakEnd || '').slice(0, 5);
  const sourceCount = Math.max(1, Number(button.dataset.automaticBreakSourceCount) || 1);
  const expectedFingerprint = String(button.dataset.automaticBreakFingerprint || '');
  if (!expectedFingerprint) return;
  const confirmed = await requestProviderConfirmation({
    title:'Освободить только это время?',
    message:sourceCount > 1
      ? `Интервал создан ${sourceCount} пересекающимися буферами. Все их источники будут исключены только для ${start}–${end}; остальные перерывы сохранятся.`
      : `Интервал ${start}–${end} станет свободным. Правило и остальные автоматические перерывы сохранятся.`,
    confirmLabel:'Освободить время',
    initialFocus:'cancel'
  });
  if (!confirmed || !sessionIsCurrent(userId, generation)) return;
  const fingerprint = `${dateIso}|${start}|${end}|${expectedFingerprint}`;
  const stored = readAutomaticBreakReleaseAttempt(userId);
  const requestId = stored?.fingerprint === fingerprint && stored?.requestId ? stored.requestId : createOfflineBookingId();
  const attempt = { requestId, fingerprint, savedAt:Date.now() };
  writeAutomaticBreakReleaseAttempt(attempt, userId);
  const label = button.textContent;
  button.disabled = true;
  button.textContent = 'Освобождаем…';
  const { data, error } = await db.rpc('release_minuta_provider_automatic_break_v158', {
    p_request_id:requestId,
    p_date:dateIso,
    p_start:`${start}:00`,
    p_end:`${end}:00`,
    p_expected_segment_fingerprint:expectedFingerprint
  });
  const released = !error && data?.action === 'released' && data?.request_id === requestId;
  if (!sessionIsCurrent(userId, generation)) {
    if (released) clearAutomaticBreakReleaseAttempt(requestId, userId);
    return;
  }
  if (button.isConnected) {
    button.disabled = false;
    button.textContent = label;
  }
  if (!released) {
    if (!window.MinutaProviderReadFetch?.isConnectionError?.(error)) clearAutomaticBreakReleaseAttempt(requestId, userId);
    const reason = String(error?.message || '');
    notify(reason.includes('buffer_interval_changed')
      ? 'Перерыв уже изменился. Обновите расписание и откройте его снова.'
      : 'Не удалось освободить время. Ничего не изменено.');
    return;
  }
  clearAutomaticBreakReleaseAttempt(requestId, userId);
  const previousSegments = automaticBookingBreakSegments.get(dateIso) || [];
  const releasedSegments = previousSegments.filter(segment => {
    const segmentStart = String(segment.start_time || '').slice(0, 5);
    const segmentEnd = String(segment.end_time || '').slice(0, 5);
    return String(segment.segment_fingerprint || '') !== expectedFingerprint && (segmentStart !== start || segmentEnd !== end);
  });
  automaticBookingBreakSegments.set(dateIso, releasedSegments);
  const breakRefresh = await loadAutomaticBookingBreaks(dateIso, userId, generation);
  if (!sessionIsCurrent(userId, generation)) return;
  if (!breakRefresh.ok) {
    automaticBookingBreakSegments.set(dateIso, releasedSegments);
    automaticBookingBreaksRemoteAvailable = true;
  }
  automaticBreakSheetInvoker = null;
  closeBookingSheet();
  renderBookingData();
  requestAnimationFrame(() => $('.timeline-stage')?.focus({ preventScroll:true }));
  notify(breakRefresh.ok
    ? 'Это время свободно. Остальные перерывы сохранены.'
    : 'Время освобождено. Не удалось обновить остальные перерывы — обновите расписание.');
}

async function disableAutomaticBookingBreaks(button) {
  if (!requireWrites()) return;
  const userId = currentUser?.id || '';
  const generation = sessionGeneration;
  if (!userId) return;
  const confirmed = await requestProviderConfirmation({
    title:'Отключить все автоматические перерывы?',
    message:'Исчезнут все интервалы, созданные правилом буфера до и после записи. Ручные перерывы останутся.',
    confirmLabel:'Отключить все',
    initialFocus:'cancel'
  });
  if (!confirmed || !sessionIsCurrent(userId, generation)) return;
  const label = button.textContent;
  button.disabled = true;
  button.textContent = 'Отключаем…';
  const { error } = await db.from('booking_policies').update({ booking_buffer_enabled:false }).eq('performer_id', userId);
  if (!sessionIsCurrent(userId, generation)) return;
  if (button.isConnected) {
    button.disabled = false;
    button.textContent = label;
  }
  if (error) { notify('Не удалось отключить автоматические перерывы'); return; }
  bookingPolicy = { ...bookingPolicy, booking_buffer_enabled:false };
  if ($('#bookingBufferEnabled')) $('#bookingBufferEnabled').checked = false;
  automaticBreakSheetInvoker = null;
  closeBookingSheet();
  renderBookingData();
  requestAnimationFrame(() => $('.timeline-stage')?.focus({ preventScroll:true }));
  notify('Автоматические перерывы отключены. Ручные сохранены.');
  await refreshAfterWrite();
}

function openBookingSeriesCancellation(id) {
  const item = allBookings.find(booking => booking.id === id);
  if (!item?.series_id || item.status === 'cancelled' || bookingOutcome(item).visit_status !== 'scheduled') return;
  $('#bookingSheet').dataset.bookingId = String(item.id || '');
  $('#bookingSheet').dataset.assistantContext = 'series-cancellation';
  $('#bookingSheet').classList.remove('booking-sheet-wide');
  $('#bookingSheetContent').innerHTML = `<div class="booking-editor-heading"><button class="booking-editor-back" type="button" data-back-booking="${item.id}">${uiIcon('arrow-left')}<span>Назад</span></button>
    <small class="booking-sheet-kicker">Серия записей</small></div><h2 id="bookingSheetTitle">Какие записи отменить?</h2>
    <form class="booking-editor-form booking-series-cancel-form" id="bookingSeriesCancelForm" data-booking-id="${item.id}">
      ${bookingSeriesScopeMarkup(item, 'cancelBookingSeriesScope', 'Выберите часть серии')}
      <p class="booking-series-warning">Освободившиеся окна снова увидят клиенты. Прошедшие и завершённые визиты сохранятся.</p>
      <p class="form-error" id="bookingSeriesCancelError" hidden></p>
      <button class="primary danger-primary" type="submit">Отменить выбранные записи</button>
    </form>`;
  $('#bookingSheet').hidden = false;
  document.body.classList.add('booking-sheet-open');
  $('#bookingSeriesCancelForm').dataset.cancellationRevision = String(++bookingSeriesCancellationRevision);
  $('#bookingSeriesCancelForm').addEventListener('submit', cancelBookingSeries);
  applyWriteAvailability();
}

async function cancelBookingSeries(event) {
  event.preventDefault();
  if (!requireWrites()) return;
  const form = event.currentTarget;
  const revision = bookingSeriesCancellationRevision;
  if (form !== $('#bookingSeriesCancelForm') || $('#bookingSheet').hidden
    || form.dataset.cancellationRevision !== String(revision) || form.dataset.cancellationPending) return;
  const userId = currentUser.id;
  const generation = sessionGeneration;
  const organizationId = activeClientOrganizationId;
  const id = form.dataset.bookingId;
  const seriesId = allBookings.find(item => item.id === id)?.series_id;
  const scope = form.elements.cancelBookingSeriesScope?.value || 'one';
  const button = event.submitter;
  const unconfirmedMessage = 'Не удалось подтвердить результат. Проверьте актуальные данные перед повтором.';
  const contextIsCurrent = () => sessionIsCurrent(userId, generation) && activeClientOrganizationId === organizationId;
  const formIsCurrent = () => contextIsCurrent() && bookingSeriesCancellationRevision === revision
    && form === $('#bookingSeriesCancelForm') && !$('#bookingSheet').hidden;
  let closedRevision = null;
  const completionIsCurrent = () => contextIsCurrent() && closedRevision !== null
    && bookingSeriesCancellationRevision === closedRevision
    && form === $('#bookingSeriesCancelForm') && $('#bookingSheet').hidden;
  form.dataset.cancellationPending = 'true';
  button.disabled = true;
  button.textContent = 'Отменяем…';
  try {
    const { data, error } = await db.rpc('manage_minuta_booking_series', {
      p_booking: id,
      p_action: 'cancel',
      p_scope: scope,
      p_date: null,
      p_time: null
    });
    if (!formIsCurrent()) return;
    if (error) {
      // Only exact server rejections justify specific guidance. A fulfilled
      // network error, like a rejected Promise, does not prove rollback.
      const rejectionMessages = {
        '42501:authentication_required':'Войдите в аккаунт снова и обновите журнал.',
        '42501:booking_access_denied':'У вас нет доступа к отмене этой записи.',
        '22023:invalid_series_action':'Параметры отмены устарели. Откройте форму заново.',
        'P0001:booking_not_found':'Запись не найдена. Обновите журнал.',
        'P0001:booking_not_in_series':'Эта запись не входит в серию. Обновите журнал.',
        'P0001:series_booking_not_actionable':'Эту запись уже нельзя отменить. Обновите журнал.',
        'P0001:series_has_no_actionable_bookings':'В выбранной части серии нет записей, доступных для отмены. Обновите журнал.',
        'P0001:series_slot_unavailable':'Не удалось завершить отмену из-за конфликта данных. Обновите журнал.',
        '55000:redeemed_benefit_cannot_cancel':'В серии есть запись с использованным сертификатом или абонементом. Сначала проверьте списание.'
      };
      const message = error.code === 'PGRST202'
        ? 'Управление сериями пока недоступно. Обновите страницу или обратитесь в поддержку.'
        : rejectionMessages[`${error.code}:${error.message}`] || unconfirmedMessage;
      showFormError('#bookingSeriesCancelError', message);
      return;
    }
    // v79 returns the requested series/action/scope and one occurrence per
    // affected booking. Never turn an empty or partial envelope into success.
    const affected = data?.affected;
    const confirmed = typeof seriesId === 'string' && seriesId.length > 0
      && data?.series_id === seriesId && data.action === 'cancel' && data.scope === scope
      && Number.isSafeInteger(data.affected_count) && data.affected_count > 0 && data.affected_count <= 24
      && Array.isArray(affected) && affected.length === data.affected_count
      && affected.every(entry => entry && typeof entry.booking_id === 'string'
        && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(entry.booking_id)
        && Number.isSafeInteger(entry.occurrence) && entry.occurrence > 0 && entry.occurrence <= 24)
      && new Set(affected.map(entry => entry.booking_id)).size === affected.length
      && new Set(affected.map(entry => entry.occurrence)).size === affected.length
      && (scope !== 'one' || (affected.length === 1 && affected[0].booking_id === id));
    if (!confirmed) {
      showFormError('#bookingSeriesCancelError', unconfirmedMessage);
      return;
    }
    affected.forEach(entry => notifyTelegramClient(entry.booking_id, 'cancelled'));
    closeBookingSheet();
    closedRevision = bookingSeriesCancellationRevision;
    await refreshAfterWrite();
    if (completionIsCurrent()) notify(`Отменено: ${seriesBookingCountLabel(Number(data?.affected_count || affected.length))}`);
  } catch {
    if (completionIsCurrent()) notify('Записи отменены. Не удалось обновить журнал — обновите его перед следующим действием.');
    else if (formIsCurrent()) showFormError('#bookingSeriesCancelError', unconfirmedMessage);
  } finally {
    if (formIsCurrent()) {
      delete form.dataset.cancellationPending;
      button.disabled = false;
      button.textContent = 'Отменить выбранные записи';
    }
  }
}

async function saveBookingBlockNote(event) {
  event.preventDefault();
  if (!requireWrites()) return;
  const form = event.currentTarget;
  const contextIsCurrent = captureBookingMetadataContext();
  const isCurrent = () => contextIsCurrent() && form === $('#bookingBlockNoteForm') && !$('#bookingSheet').hidden;
  if (!isCurrent() || form.dataset.metadataPending) return;
  const id = form.dataset.bookingId;
  const note = $('#bookingBlockNote')?.value.trim() || '';
  const button = event.submitter;
  form.dataset.metadataPending = 'true';
  button.disabled = true;
  button.textContent = 'Сохраняем…';
  try {
    const remoteSaved = await saveBookingNote(id, note, { isCurrent });
    if (!isCurrent()) return;
    const state = $('.booking-note-state');
    if (state) state.textContent = note ? 'Добавлена' : 'Добавить';
    notify(remoteSaved
      ? (note ? 'Заметка сохранена' : 'Заметка удалена')
      : 'Заметка сохранена на этом устройстве');
  } catch {
    if (isCurrent()) notify('Не удалось подтвердить сохранение заметки. Проверьте запись перед повтором.');
  } finally {
    if (isCurrent()) {
      delete form.dataset.metadataPending;
      button.disabled = false;
      button.textContent = 'Сохранить заметку';
    }
  }
}

async function saveBookingSheetNote(event) {
  event.preventDefault();
  if (!requireWrites()) return;
  const contextIsCurrent = captureBookingMetadataContext();
  const form = event.currentTarget;
  const phone = normalizePhone(event.currentTarget.dataset.clientPhone);
  const isCurrent = () => contextIsCurrent() && form.isConnected && normalizePhone(form.dataset.clientPhone) === phone && !$('#bookingSheet').hidden;
  const note = $('#bookingSheetClientNote').value.trim();
  const button = event.submitter;
  button.disabled = true;
  button.textContent = 'Сохраняем…';
  try {
    const saved = await saveClientNoteValue(phone, note, { isCurrent });
    if (!isCurrent()) return;
    const noteState = $('.booking-note-state');
    if (noteState) noteState.textContent = note ? 'Добавлена' : 'Добавить';
    notify(saved ? 'Заметка сохранена' : 'Заметка сохранена на этом устройстве · отправим после восстановления связи');
  } catch {
    if (isCurrent()) notify('Не удалось сохранить заметку. Не закрывайте страницу и повторите сохранение.');
  } finally {
    if (isCurrent()) { button.disabled = false; button.textContent = 'Сохранить заметку'; }
  }
}

function serviceOptions(selectedId, activeOnly = false) {
  const services = activeOnly ? ownServices.filter(item => item.active) : ownServices;
  return services.map(item => `<option value="${item.id}" ${item.id === selectedId ? 'selected' : ''}>${escapeHtml(serviceName(item.name))} · ${Number(item.duration_minutes) === 1 ? `${money(item.price_rub)}/мин · обычно ${serviceDefaultDuration(item.id)} мин` : `${item.duration_minutes} мин · ${money(item.price_rub)}`}</option>`).join('');
}

function normalizePerMinuteDuration(value, fallback = PER_MINUTE_BOOKING_MIN) {
  const parsed = Math.round(Number(value));
  const safe = Number.isFinite(parsed) ? parsed : fallback;
  return Math.max(PER_MINUTE_BOOKING_MIN, Math.min(PER_MINUTE_BOOKING_MAX, safe));
}

function selectedNewBookingService() {
  return ownServices.find(item => item.id === $('#newBookingService')?.value && item.active) || null;
}

function newBookingDurationMinutes() {
  if (newBookingMode === 'block') return Number($('#newBookingBlockDuration')?.value || 60);
  if (newBookingRepeatVisit) return Math.max(1, Number(newBookingRepeatVisit.duration_minutes || 0));
  const service = selectedNewBookingService();
  if (!service) return 0;
  return Number(service.duration_minutes) === 1
    ? normalizePerMinuteDuration($('#newBookingDuration')?.value)
    : Math.max(1, Number(service.duration_minutes || 60));
}

function updateNewBookingDurationControl({ reset = false } = {}) {
  const holder = $('#newBookingDurationField');
  const input = $('#newBookingDuration');
  const summary = $('#newBookingDurationSummary');
  const service = selectedNewBookingService();
  const perMinute = newBookingMode === 'client' && Number(service?.duration_minutes) === 1;
  if (!holder || !input || !summary) return;
  holder.hidden = !perMinute;
  if (!perMinute) {
    updateNewBookingHistoricalPayment({ resetAmount:reset });
    return;
  }
  if (reset) input.value = String(serviceDefaultDuration(service.id));
  const duration = normalizePerMinuteDuration(input.value);
  input.value = String(duration);
  const total = Math.max(0, Math.round(duration * Number(service.price_rub || 0)));
  const start = newBookingTime || newBookingPreferredTime;
  const end = start ? ` · ${start}–${timeFromMinutes(minutesFromTime(start) + duration)}` : '';
  summary.textContent = `${duration} мин · ${money(total)}${end}`;
  updateNewBookingHistoricalPayment({ resetAmount:reset });
}

function updateServiceDefaultDurationField(selectSelector, holderSelector, inputSelector) {
  const select = $(selectSelector);
  const holder = $(holderSelector);
  const input = $(inputSelector);
  if (!select || !holder || !input) return;
  const perMinute = Number(select.value) === 1;
  holder.hidden = !perMinute;
  input.required = perMinute;
  if (perMinute) input.value = String(normalizePerMinuteDuration(input.value, 60));
}

function bindServiceDefaultDurationPresets(holderSelector, inputSelector) {
  $$(holderSelector).forEach(button => button.addEventListener('click', () => {
    const input = $(inputSelector);
    const duration = button.dataset.serviceDefaultDuration ?? button.dataset.editServiceDefaultDuration;
    if (input) input.value = String(normalizePerMinuteDuration(duration, 60));
  }));
}

function updateEditServiceVisibilityHint() {
  const input = $('#editServiceActive');
  const hint = input?.closest('.service-visibility-option')?.querySelector('small');
  if (!input || !hint) return;
  hint.textContent = input.checked ? 'Клиенты смогут выбрать эту услугу' : 'Услуга будет скрыта от клиентов';
}

async function applyPerMinuteBookingTerms(bookingIds, service, durationMinutes) {
  const duration = normalizePerMinuteDuration(durationMinutes);
  if (Number(service?.duration_minutes) !== 1 || duration === 1 || !bookingIds.length) return { ok:true };
  const totalPrice = Math.max(0, Math.round(duration * Number(service.price_rub || 0)));
  for (const bookingId of bookingIds) {
    const { data, error } = await db.from('bookings').update({
      duration_minutes:duration,
      original_price_rub:Number(service.price_rub || 0),
      total_price_rub:totalPrice
    }).eq('id', bookingId).eq('performer_id', currentUser.id).select('id,duration_minutes,total_price_rub');
    if (error) return { ok:false, error };
    if (!Array.isArray(data) || data.length !== 1 || data[0].id !== bookingId || Number(data[0].duration_minutes) !== duration || Number(data[0].total_price_rub) !== totalPrice) return { ok:false, error:{ message:'duration_update_unconfirmed' } };
    if (sessionItemsRemoteAvailable) {
      const { error:sessionError } = await db.from('booking_session_items').update({ duration_minutes:duration, price_rub:totalPrice })
        .eq('booking_id', bookingId).eq('performer_id', currentUser.id).eq('item_kind', 'primary');
      if (sessionError && !/booking_session_items|schema cache|does not exist/i.test(String(sessionError.message || ''))) return { ok:false, error:sessionError };
    }
  }
  return { ok:true };
}

async function rollbackCreatedBookings(bookingIds) {
  const results = await Promise.all(bookingIds.map(async id => {
    try {
      const { data, error } = await db.rpc('provider_delete_booking', { p_booking:id });
      return !error && ['deleted', 'not_found'].includes(data) ? null : id;
    } catch { return id; }
  }));
  return { ok:results.every(id => id === null), unresolvedIds:results.filter(Boolean) };
}

function blockDurationOptions(selectedId, activeOnly = false) {
  const selected = ownServices.find(item => item.id === selectedId);
  const source = activeOnly ? ownServices.filter(item => item.active) : ownServices;
  const byDuration = new Map();
  source.forEach(item => {
    const duration = Number(item.duration_minutes || 60);
    if (!byDuration.has(duration)) byDuration.set(duration, item);
  });
  if (selected) byDuration.set(Number(selected.duration_minutes || 60), selected);
  return [...byDuration.entries()].sort(([a], [b]) => a - b).map(([duration, item]) => `<option value="${item.id}" ${item.id === selectedId ? 'selected' : ''}>${duration} минут</option>`).join('');
}

function durationOptions(selected) {
  const durations = [...new Set([1, 5, 10, 20, 30, 40, 60, 90, 120, 180, Number(selected)])].filter(value => value >= 1 && value <= 480).sort((a, b) => a - b);
  return durations.map(value => `<option value="${value}" ${value === Number(selected) ? 'selected' : ''}>${value === 1 ? '1 мин (цена за минуту)' : `${value} мин`}</option>`).join('');
}

function servicePublicCardEditorMarkup(prefix, details = {}) {
  const highlights = Array.isArray(details.highlights) ? details.highlights.slice(0, 3) : [];
  while (highlights.length < 3) highlights.push('');
  const hasPhoto = Boolean(details.photo_storage_path);
  return `<section class="service-public-card-editor" aria-labelledby="${prefix}ServicePublicCardTitle">
    <div><strong id="${prefix}ServicePublicCardTitle">Карточка для клиента</strong><small>Покажем «Подробнее» только когда здесь есть содержание.</small></div>
    <figure class="service-photo-preview" id="${prefix}ServicePhotoPreview" ${hasPhoto ? '' : 'hidden'}><img id="${prefix}ServicePhotoPreviewImage" alt="Предпросмотр фото услуги"></figure>
    <label>Фото услуги<input id="${prefix}ServicePhoto" type="file" accept="image/jpeg,image/png,image/webp"><small>Одно фото до 12 МБ. Перед загрузкой уменьшим и сохраним в WebP.</small></label>
    ${hasPhoto ? `<label class="service-photo-remove"><input id="${prefix}ServicePhotoRemove" type="checkbox"><span>Удалить текущее фото</span></label>` : ''}
    <label>Короткое описание<textarea id="${prefix}ServiceShortDescription" rows="3" maxlength="360" placeholder="Что входит в услугу и для кого она">${escapeHtml(details.short_description || '')}</textarea></label>
    <div class="service-highlight-fields"><span>До трёх особенностей</span>${highlights.map(value => `<input data-${prefix}-service-highlight maxlength="120" value="${escapeHtml(value)}" placeholder="Особенность услуги">`).join('')}</div>
    <details ${details.important_note ? 'open' : ''}><summary>Важно — только если есть ограничения</summary><label>Что клиенту нужно знать<textarea id="${prefix}ServiceImportantNote" rows="3" maxlength="500">${escapeHtml(details.important_note || '')}</textarea></label></details>
  </section>`;
}

function bindServicePublicCardEditor(prefix, details = {}) {
  const input = $(`#${prefix}ServicePhoto`);
  const preview = $(`#${prefix}ServicePhotoPreview`);
  const image = $(`#${prefix}ServicePhotoPreviewImage`);
  if (input) input.onchange = () => {
    const file = input.files?.[0];
    if (!file || !preview || !image) return;
    if (image.dataset.objectUrl) URL.revokeObjectURL(image.dataset.objectUrl);
    image.dataset.objectUrl = URL.createObjectURL(file);
    image.src = image.dataset.objectUrl;
    preview.hidden = false;
    const remove = $(`#${prefix}ServicePhotoRemove`);
    if (remove) remove.checked = false;
  };
  const removePhoto = $(`#${prefix}ServicePhotoRemove`);
  if (removePhoto) removePhoto.onchange = event => {
    if (!preview) return;
    preview.hidden = event.currentTarget.checked;
    if (!event.currentTarget.checked && image?.src) preview.hidden = false;
  };
  if (details.photo_storage_path && image) {
    void db.storage.from(SERVICE_IMAGE_BUCKET).createSignedUrl(details.photo_storage_path, 900).then(({ data }) => {
      if (data?.signedUrl && image.isConnected) { image.src = data.signedUrl; preview.hidden = false; }
    });
  }
}

function readServicePublicCardFields(prefix) {
  return {
    shortDescription:$(`#${prefix}ServiceShortDescription`)?.value.trim() || '',
    highlights:$$(`[data-${prefix}-service-highlight]`).map(input => input.value.trim()).filter(Boolean),
    importantNote:$(`#${prefix}ServiceImportantNote`)?.value.trim() || '',
    file:$(`#${prefix}ServicePhoto`)?.files?.[0] || null,
    removePhoto:$(`#${prefix}ServicePhotoRemove`)?.checked === true
  };
}

function resetServicePublicCardPhotoPreview(prefix) {
  const preview = $(`#${prefix}ServicePhotoPreview`);
  const image = $(`#${prefix}ServicePhotoPreviewImage`);
  if (image?.dataset.objectUrl) URL.revokeObjectURL(image.dataset.objectUrl);
  if (image) { image.removeAttribute('src'); delete image.dataset.objectUrl; }
  if (preview) preview.hidden = true;
}

async function prepareServiceImage(file) {
  if (!['image/jpeg','image/png','image/webp'].includes(file?.type) || file.size > SERVICE_IMAGE_INPUT_LIMIT) throw new Error('service_image_invalid');
  const image = await decodePortfolioImage(file);
  const scale = Math.min(1, SERVICE_IMAGE_MAX_EDGE / Math.max(image.width, image.height));
  const width = Math.max(1, Math.round(image.width * scale));
  const height = Math.max(1, Math.round(image.height * scale));
  const canvas = document.createElement('canvas');
  canvas.width = width; canvas.height = height;
  const context = canvas.getContext('2d', { alpha:false });
  context.fillStyle = '#fff'; context.fillRect(0, 0, width, height); context.drawImage(image, 0, 0, width, height); image.close?.();
  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', .82));
  if (!blob || blob.size > SERVICE_IMAGE_OUTPUT_LIMIT) throw new Error('service_image_too_large');
  return { blob,width,height };
}

async function persistServiceWithPublicCard({ serviceId,name,duration,price,active,prefix,existing = {} }) {
  const fields = readServicePublicCardFields(prefix);
  if (fields.highlights.length > 3) throw new Error('service_details_invalid');
  let photoPath = fields.removePhoto ? '' : (existing.photo_storage_path || '');
  let photoWidth = fields.removePhoto ? null : (existing.photo_width || null);
  let photoHeight = fields.removePhoto ? null : (existing.photo_height || null);
  let uploadedPath = '';
  if (fields.file) {
    const prepared = await prepareServiceImage(fields.file);
    uploadedPath = `${currentUser.id}/services/${serviceId}/${createPortfolioPhotoId()}.webp`;
    const { error } = await db.storage.from(SERVICE_IMAGE_BUCKET).upload(uploadedPath, prepared.blob, { contentType:'image/webp',cacheControl:'31536000',upsert:false });
    if (error) throw error;
    photoPath = uploadedPath; photoWidth = prepared.width; photoHeight = prepared.height;
  }
  const result = await db.rpc('save_minuta_service_v159', {
    p_service:serviceId,p_name:name,p_duration_minutes:duration,p_price_rub:Math.round(price),p_active:active,
    p_short_description:fields.shortDescription,p_highlights:fields.highlights,p_important_note:fields.importantNote,
    p_photo_storage_path:photoPath,p_photo_alt:photoPath ? `Фото услуги «${name}»` : '',p_photo_width:photoWidth,p_photo_height:photoHeight
  });
  if (result.error) {
    const [detailsCheck,serviceCheck] = await Promise.all([
      db.rpc('get_minuta_service_public_details_v159', { p_service:serviceId }),
      db.from('services').select('name,duration_minutes,price_rub,active').eq('id',serviceId).eq('performer_id',currentUser.id).maybeSingle()
    ]);
    const reconciled = detailsCheck.data?.[0] || {};
    const detailSaved = (reconciled.short_description || '') === fields.shortDescription
      && JSON.stringify(reconciled.highlights || []) === JSON.stringify(fields.highlights)
      && (reconciled.important_note || '') === fields.importantNote
      && (reconciled.photo_storage_path || '') === photoPath;
    const serviceSaved = !serviceCheck.error && serviceCheck.data?.name === name
      && Number(serviceCheck.data?.duration_minutes) === duration && Number(serviceCheck.data?.price_rub) === Math.round(price)
      && serviceCheck.data?.active === active;
    if (!detailSaved || !serviceSaved) {
      // Delete a rejected upload only after the server has confirmed that it was not linked.
      if (uploadedPath && !detailsCheck.error && (reconciled.photo_storage_path || '') !== uploadedPath) await db.storage.from(SERVICE_IMAGE_BUCKET).remove([uploadedPath]);
      throw result.error;
    }
    result.data = { saved:true,retired_path:existing.photo_storage_path && existing.photo_storage_path !== photoPath ? existing.photo_storage_path : '' };
  }
  const retiredPath = result.data?.retired_path || '';
  if (retiredPath && retiredPath !== photoPath) await db.storage.from(SERVICE_IMAGE_BUCKET).remove([retiredPath]);
  return true;
}

function openServiceEditor(id) {
  const item = ownServices.find(service => service.id === id);
  if (!item) return;
  if (!servicePublicDetailsReady) {
    notify('Карточка услуги не загрузилась. Обновите данные и повторите.');
    return;
  }
  const details = servicePublicDetails.get(id) || {};
  $('#bookingSheet').classList.remove('booking-sheet-wide');
  $('#bookingSheetContent').innerHTML = `<small class="booking-sheet-kicker">Редактирование услуги</small><h2 id="bookingSheetTitle">Настройте услугу</h2>
    <form class="booking-editor-form service-edit-form" id="serviceEditForm" data-service-id="${item.id}">
      <label>Название услуги<input id="editServiceName" maxlength="120" value="${escapeHtml(item.name)}" required></label>
      ${serviceScheduleNameSettingMarkup({ prefix:'edit', fullName:item.name, serviceId:item.id })}
      <div class="service-edit-row"><label>Длительность<select id="editServiceDuration" required>${durationOptions(item.duration_minutes)}</select></label><label>Цена, ₽<input id="editServicePrice" type="number" min="0" max="1000000" step="1" value="${item.price_rub}" required></label></div>
      <div class="service-default-duration" id="editServiceDefaultDurationField" ${Number(item.duration_minutes) === 1 ? '' : 'hidden'}><div><label for="editServiceDefaultDuration">Обычная длительность, минут</label><small>Автоматически подставляется при новой записи.</small></div><input id="editServiceDefaultDuration" type="number" inputmode="numeric" min="1" max="480" step="1" value="${serviceDefaultDuration(item.id)}"><div class="service-default-duration-presets"><button type="button" data-edit-service-default-duration="30">30</button><button type="button" data-edit-service-default-duration="45">45</button><button type="button" data-edit-service-default-duration="60">60</button><button type="button" data-edit-service-default-duration="90">90</button></div></div>
      ${servicePublicCardEditorMarkup('edit', details)}
      <label class="service-visibility-option"><input id="editServiceActive" type="checkbox" ${item.active ? 'checked' : ''}><span><strong>Показывать в онлайн-записи</strong><small>${item.active ? 'Клиенты могут выбрать эту услугу' : 'Сейчас услуга скрыта от клиентов'}</small></span></label>
      <p class="form-error" id="serviceEditError" hidden></p>
      <div class="service-edit-actions"><button class="secondary-button" type="button" data-close-booking-sheet>Отмена</button><button class="primary" type="submit">Сохранить изменения</button></div>
    </form>`;
  $('#bookingSheet').hidden = false;
  document.body.classList.add('booking-sheet-open');
  $('#serviceEditForm').addEventListener('submit', saveServiceChanges);
  $('#editServiceDuration').addEventListener('change', () => updateServiceDefaultDurationField('#editServiceDuration', '#editServiceDefaultDurationField', '#editServiceDefaultDuration'));
  $('#editServiceActive').addEventListener('change', updateEditServiceVisibilityHint);
  bindServiceScheduleNameSetting({ prefix:'edit', nameSelector:'#editServiceName' });
  bindServiceDefaultDurationPresets('[data-edit-service-default-duration]', '#editServiceDefaultDuration');
  bindServicePublicCardEditor('edit', details);
  setTimeout(() => $('#editServiceName')?.focus(), 0);
}

async function saveServiceChanges(event) {
  event.preventDefault();
  if (!requireWrites()) return;
  clearFormError('#serviceEditError');
  const id = event.currentTarget.dataset.serviceId;
  const name = $('#editServiceName').value.trim();
  const duration = Number($('#editServiceDuration').value);
  const defaultDuration = normalizePerMinuteDuration($('#editServiceDefaultDuration')?.value, serviceDefaultDuration(id));
  const price = Number($('#editServicePrice').value);
  const active = $('#editServiceActive').checked;
  const scheduleNameEnabled = $('#editServiceScheduleNameEnabled')?.checked === true;
  const scheduleName = $('#editServiceScheduleName')?.value.trim() || '';
  if (name.length < 2 || !Number.isFinite(duration) || duration < 1 || duration > 480 || !Number.isFinite(price) || price < 0) {
    showFormError('#serviceEditError', 'Проверьте название, длительность и цену.');
    return;
  }
  if (scheduleNameEnabled && scheduleName.length < 2) {
    showFormError('#serviceEditError', 'Укажите короткое название для расписания.');
    return;
  }
  const button = event.submitter;
  button.disabled = true;
  button.textContent = 'Сохраняем…';
  try {
    await persistServiceWithPublicCard({ serviceId:id,name,duration,price,active,prefix:'edit',existing:servicePublicDetails.get(id) || {} });
  } catch {
    button.disabled = false;
    button.textContent = 'Сохранить изменения';
    showFormError('#serviceEditError', 'Не удалось сохранить услугу и карточку. Проверьте фото и попробуйте ещё раз.');
    return;
  }
  if (duration === 1) await saveServiceDefaultDuration(id, defaultDuration);
  const scheduleNameSynced = await saveServiceScheduleName(id, scheduleNameEnabled, scheduleName);
  closeBookingSheet();
  await refreshAfterWrite();
  notify(scheduleNameSynced ? 'Услуга обновлена' : 'Услуга обновлена · короткое название синхронизируется');
}

async function loadBookingEditSlots(id, preserveCurrent = false) {
  const form = $('#bookingEditForm');
  const revision = bookingEditorRevision;
  if (!form || form.dataset.bookingId !== id || form.dataset.editorRevision !== String(revision)) return;
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  const organizationId = activeClientOrganizationId;
  const item = allBookings.find(booking => booking.id === id);
  const service = $('#editBookingService')?.value;
  const date = $('#editBookingDate')?.value;
  const holder = $('#editBookingTimes');
  if (!item || !date || !holder || (!isScheduleBlock(item) && !service)) return;
  const scope = form.elements.editBookingSeriesScope?.value || 'one';
  const request = String(Number(form.dataset.slotsRevision || 0) + 1);
  form.dataset.slotsRevision = request;
  const isCurrent = () => sessionIsCurrent(userId, generation) && activeClientOrganizationId === organizationId
    && bookingEditorRevision === revision && form === $('#bookingEditForm') && !$('#bookingSheet').hidden
    && holder === $('#editBookingTimes') && form.dataset.slotsRevision === request
    && $('#editBookingService')?.value === service && $('#editBookingDate')?.value === date
    && (form.elements.editBookingSeriesScope?.value || 'one') === scope;
  const movesSeveral = Boolean(item.series_id && scope !== 'one');
  if (!preserveCurrent) {
    bookingEditTime = '';
    bookingEditHour = '';
  }
  bookingEditSlots = [];
  holder.innerHTML = '<span>Ищем свободное время…</span>';
  try {
    const duration = isScheduleBlock(item)
      ? Math.max(1, Number($('#editBookingBlockDuration')?.value || item.duration_minutes || 60))
      : Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60));
    const { data, error } = isScheduleBlock(item)
      ? await db.rpc('get_provider_block_slots_v141', {
        p_organization:item.organization_id,
        p_location:item.location_id,
        p_date:date,
        p_duration:duration,
        p_ignore_booking:item.id
      })
      : await getProviderAvailableSlots({ p_service:service, p_start:date, p_end:date, p_ignore_booking:item.id });
    if (!isCurrent()) return;
    if (error) throw error;
    const currentTime = String(item.booking_time).slice(0, 5);
    const times = (data || []).map(slot => String(slot.booking_time).slice(0, 5)).filter(time => !bookingMoveTimeIsPast(date, time));
    if (movesSeveral && !times.includes(currentTime) && !bookingMoveTimeIsPast(date, currentTime)) times.unshift(currentTime);
    if (!times.length) {
      bookingEditTime = '';
      bookingEditHour = '';
      updateBookingMovePreview();
      holder.innerHTML = '<span>На эту дату свободного времени нет</span>';
      return;
    }
    if (preserveCurrent && service === item.service_id && date === item.booking_date && times.includes(currentTime)) bookingEditTime = currentTime;
    if (!times.includes(bookingEditTime)) bookingEditTime = '';
    bookingEditSlots = times;
    bookingEditHour = String(bookingEditTime || bookingEditHour || times[0]).slice(0, 2);
    if (holder.dataset) holder.dataset.movesSeveral = String(movesSeveral);
    renderBookingEditTimePicker();
  } catch (caught) {
    if (isCurrent()) {
      bookingEditTime = '';
      bookingEditHour = '';
      bookingEditSlots = [];
      const missingUpdate = isScheduleBlock(item) && /get_provider_block_slots_v141|schema cache|could not find|does not exist/i.test(String(caught?.message || ''));
      holder.innerHTML = `<span>${missingUpdate ? 'Обновление безопасного переноса перерывов ещё не установлено.' : 'Не удалось загрузить свободное время. Выберите дату ещё раз.'}</span>`;
      updateBookingMovePreview();
    }
  }
}

function renderBookingEditTimePicker({ focusExact = false } = {}) {
  const holder = $('#editBookingTimes');
  if (!holder || !bookingEditSlots.length) return;
  const blockEditor = $('#bookingEditForm')?.dataset.bookingKind === 'block';
  const hours = [...new Set(bookingEditSlots.map(time => time.slice(0, 2)))];
  if (!hours.includes(bookingEditHour)) bookingEditHour = hours[0];
  const hourSlots = bookingEditSlots.filter(time => time.startsWith(`${bookingEditHour}:`));
  const quickSlots = bookingQuickTimeSlots(hourSlots);
  const seriesHint = holder.dataset?.movesSeveral === 'true'
    ? '<small class="booking-series-slot-hint">Все окна серии будут проверены вместе при сохранении.</small>'
    : '';
  holder.innerHTML = `${seriesHint}${hours.length > 1 ? `<div class="booking-time-guide"><strong>Час</strong><span>${hours.length} доступно</span></div>
    <div class="booking-time-hours">${hours.map(hour => `<button type="button" class="${hour === bookingEditHour ? 'active' : ''}" aria-pressed="${hour === bookingEditHour}" aria-label="Час ${hour}:00" data-edit-booking-hour="${hour}">${hour}:00</button>`).join('')}</div>` : ''}
    <div class="booking-time-guide"><strong>${blockEditor ? 'Уточнить минуты' : 'Новое время'}</strong><span id="editBookingExactStatus">${bookingEditTime ? `${blockEditor ? 'Необязательно · ' : ''}выбрано ${bookingEditTime}` : `${quickSlots.length} вариантов`}</span></div>
    <div class="booking-time-slots">${quickSlots.map(time => `<button type="button" class="${time === bookingEditTime ? 'active' : ''}" aria-pressed="${time === bookingEditTime}" data-edit-booking-time="${time}">${time}</button>`).join('')}</div>
    ${bookingExactTimeMarkup('edit', hourSlots, bookingEditTime)}`;
  updateBookingMovePreview();
  if (focusExact) holder.querySelector('[data-edit-booking-time]')?.focus();
}

function bookingQuickTimeSlots(slots) {
  const available = [...new Set((slots || []).filter(time => /^\d{2}:\d{2}$/.test(String(time))))].sort();
  const quick = available.filter(time => Number(time.slice(3, 5)) % 5 === 0);
  return quick.length ? quick : available.slice(0, 12);
}

function bookingNearbyTimeSlots(slots, selectedTime = '', referenceTime = selectedTime) {
  const available = newBookingGridSlots(slots);
  if (!available.length) return [];
  const value = available.includes(selectedTime) ? selectedTime : '';
  const minuteValue = time => minutesFromTime(time);
  const closestTo = (items, target) => [...items].sort((left, right) => {
    const distance = Math.abs(minuteValue(left) - target) - Math.abs(minuteValue(right) - target);
    return distance || left.localeCompare(right);
  })[0] || '';
  const chosen = [];
  const reference = /^\d{2}:\d{2}$/.test(String(referenceTime || '')) ? String(referenceTime) : value;
  if (reference) {
    const selectedMinutes = minuteValue(reference);
    const before = available.filter(time => minuteValue(time) < selectedMinutes);
    const after = available.filter(time => minuteValue(time) > selectedMinutes);
    const previous = closestTo(before, selectedMinutes - NEW_BOOKING_GRID_MINUTES);
    const next = closestTo(after, selectedMinutes + NEW_BOOKING_GRID_MINUTES);
    if (previous) chosen.push(previous);
    if (value) chosen.push(value);
    if (next) chosen.push(next);
    for (const time of [...available].sort((left, right) => {
      const distance = Math.abs(minuteValue(left) - selectedMinutes) - Math.abs(minuteValue(right) - selectedMinutes);
      return distance || left.localeCompare(right);
    })) {
      if (chosen.length >= 3) break;
      if (!chosen.includes(time)) chosen.push(time);
    }
  } else {
    const first = available[0];
    chosen.push(first);
    const start = minuteValue(first);
    for (const target of [start + NEW_BOOKING_GRID_MINUTES, start + (NEW_BOOKING_GRID_MINUTES * 2)]) {
      const next = closestTo(available.filter(time => !chosen.includes(time) && minuteValue(time) >= target), target)
        || available.find(time => !chosen.includes(time));
      if (next) chosen.push(next);
    }
  }
  return chosen.slice(0, 3).sort((left, right) => left.localeCompare(right));
}

function bookingRemainingTimeSlots(slots, nearbySlots, selectedTime = '') {
  const nearby = new Set(nearbySlots || []);
  return newBookingGridSlots(slots)
    .filter(time => time === selectedTime || !nearby.has(time));
}

function bookingRemainingTimeMarkup(slots, nearbySlots, selectedTime = '') {
  const remaining = bookingRemainingTimeSlots(slots, nearbySlots, selectedTime);
  if (!remaining.length) return '';
  const scrollTime = remaining.includes(selectedTime)
    ? selectedTime
    : remaining.find(time => time >= selectedTime) || remaining.at(-1);
  return `<details class="booking-more-times" data-scroll-time="${scrollTime}">
    <summary><span>Показать остальные</span><small>Шаг 30 мин · ещё ${remaining.length}</small></summary>
    <div class="booking-time-slots booking-time-slots-all">${remaining.map(time => `<button type="button" class="${time === selectedTime ? 'active' : ''}" aria-pressed="${time === selectedTime}" data-new-booking-time="${time}">${time}</button>`).join('')}</div>
  </details>`;
}

function activateBookingRemainingTimeScroll(holder) {
  const details = holder?.querySelector('.booking-more-times');
  if (!details?.dataset.scrollTime) return;
  details.addEventListener('toggle', () => {
    if (!details.open) return;
    requestAnimationFrame(() => {
      const list = details.querySelector('.booking-time-slots-all');
      const target = list?.querySelector(`[data-new-booking-time="${details.dataset.scrollTime}"]`);
      if (!list || !target) return;
      if (list.scrollHeight > list.clientHeight) target.style.gridColumnStart = '1';
      const targetTop = target.getBoundingClientRect().top - list.getBoundingClientRect().top + list.scrollTop;
      list.scrollTop = Math.max(0, targetTop);

      const panel = details.closest('.booking-sheet-panel');
      if (!panel) return;
      const submitBar = panel.querySelector('.booking-sheet-submit-bar');
      const panelRect = panel.getBoundingClientRect();
      const detailsRect = details.getBoundingClientRect();
      const submitIsSticky = submitBar && getComputedStyle(submitBar).position === 'sticky';
      const revealGap = 14;
      const visibleTop = panelRect.top + revealGap;
      const visibleBottom = (submitIsSticky
        ? Math.min(panelRect.bottom, submitBar.getBoundingClientRect().top)
        : panelRect.bottom) - revealGap;
      const availableHeight = Math.max(0, visibleBottom - visibleTop);
      const scrollDelta = detailsRect.height <= availableHeight
        ? Math.max(0, detailsRect.bottom - visibleBottom)
        : Math.max(0, detailsRect.top - visibleTop);
      if (scrollDelta > 1) {
        panel.scrollTop = Math.min(panel.scrollHeight - panel.clientHeight, panel.scrollTop + scrollDelta);
      }
    });
  });
}

function bookingExactTimeMarkup(kind, slots, selectedTime = '') {
  const available = [...new Set((slots || []).filter(time => /^\d{2}:\d{2}$/.test(String(time))))].sort();
  const quick = bookingQuickTimeSlots(available);
  const exact = available.filter(time => !quick.includes(time));
  if (!exact.length) return '';
  const isEdit = kind === 'edit';
  const inputId = isEdit ? 'editBookingExactTime' : 'newBookingExactTime';
  const statusId = isEdit ? 'editBookingExactTimeHint' : 'newBookingExactTimeHint';
  const value = available.includes(selectedTime) ? selectedTime : exact[0];
  const open = selectedTime && !quick.includes(selectedTime);
  return `<details class="booking-exact-time"${open ? ' open' : ''}>
    <summary><span>Указать точную минуту</span><small>Ещё ${exact.length} ${exact.length === 1 ? 'вариант' : exact.length < 5 ? 'варианта' : 'вариантов'}</small></summary>
    <div class="booking-exact-time-controls"><label for="${inputId}"><span>Часы и минуты</span><input id="${inputId}" type="time" step="60" min="${available[0]}" max="${available.at(-1)}" value="${value}" aria-describedby="${statusId}"></label><button type="button" data-apply-${isEdit ? 'edit' : 'new'}-booking-exact-time>Выбрать</button></div>
    <small class="booking-exact-time-hint" id="${statusId}" role="status">Показываются только свободные минуты выбранного часа.</small>
  </details>`;
}

function sessionServiceOptions(selectedId = '', allowCustom = false) {
  const custom = allowCustom ? `<option value="" ${selectedId ? '' : 'selected'}>Произвольная услуга</option>` : '';
  return `${custom}${ownServices.map(service => {
    const duration = Math.max(1, Math.round(Number(service.duration_minutes) || 0));
    const price = Math.max(0, Math.round(Number(service.price_rub) || 0));
    const details = duration === 1 ? `${money(price)}/мин` : `${duration} мин · ${money(price)}`;
    return `<option value="${service.id}" ${service.id === selectedId ? 'selected' : ''}>${escapeHtml(serviceName(service.name))} · ${details}</option>`;
  }).join('')}`;
}

function sessionConflict(item, items) {
  const start = minutesFromTime(item.booking_time);
  const duration = bookingSessionDuration(items);
  const end = start + duration;
  const conflict = allBookings
    .filter(other => other.id !== item.id && other.status !== 'cancelled' && other.booking_date === item.booking_date)
    .map(other => ({ item:other, start:minutesFromTime(other.booking_time), end:minutesFromTime(other.booking_time) + Number(other.duration_minutes || other.services?.duration_minutes || 60) }))
    .filter(other => start < other.end && end > other.start)
    .sort((a, b) => a.start - b.start)[0];
  if (!conflict) return null;
  return { time:String(conflict.item.booking_time).slice(0, 5), extra:Math.max(0, duration - Number(item.duration_minutes || 0)) };
}

function sessionComposerItemMarkup(entry, index) {
  const addon = entry.kind === 'addon';
  const service = ownServices.find(item => item.id === entry.service_id);
  const minutePrice = Number(service?.duration_minutes) === 1 ? Number(service.price_rub) : null;
  const price = minutePrice !== null ? minutePrice : entry.price_rub;
  return `<article class="session-composer-item" data-session-item="${index}"><div class="session-composer-item-head"><strong>${addon ? `Дополнительная услуга ${index}` : 'Основная услуга'}</strong>${addon ? `<button type="button" data-remove-session-item="${index}" aria-label="Удалить дополнительную услугу">${uiIcon('trash')}</button>` : ''}</div><label>${addon ? 'Источник' : 'Услуга из каталога'}<select data-session-service ${addon ? '' : 'required'}>${sessionServiceOptions(entry.service_id, addon)}</select></label>${addon ? `<label>Название<input data-session-title maxlength="120" value="${escapeHtml(entry.title)}" required></label>` : `<input data-session-title type="hidden" value="${escapeHtml(entry.title)}">`}<div class="session-composer-fields"><label>Длительность, мин<input data-session-duration type="number" min="${addon ? 0 : 5}" max="480" step="1" value="${entry.duration_minutes}" required></label><label>Стоимость, ₽<input data-session-price type="number" min="0" max="1000000" step="1" value="${price}" required></label></div>${addon ? `<label class="session-duration-toggle"><input data-session-extends type="checkbox" ${entry.extends_duration ? 'checked' : ''}><span><strong>Увеличивает продолжительность сеанса</strong><small>Если выключено, услуга добавится только к стоимости.</small></span></label>` : ''}</article>`;
}

function updateSessionServiceLabels() {
  $$('[data-session-service]').forEach(select => {
    let label = select.parentElement.querySelector('.session-service-name');
    if (!label) { label = document.createElement('span'); label.className = 'session-service-name'; select.after(label); }
    label.textContent = ownServices.find(service => service.id === select.value)?.name || 'Произвольная услуга';
  });
}

function readSessionComposerDraft() {
  return $$('.session-composer-item').map((card, index) => {
    const serviceId = card.querySelector('[data-session-service]').value;
    const service = ownServices.find(item => item.id === serviceId);
    const duration = Math.round(Number(card.querySelector('[data-session-duration]').value) || 0);
    const enteredPrice = Math.max(0, Math.round(Number(card.querySelector('[data-session-price]').value) || 0));
    const price = Number(service?.duration_minutes) === 1 ? Math.max(0, Math.round(duration * enteredPrice)) : enteredPrice;
    return {
      kind:index === 0 ? 'primary' : 'addon',
      service_id:serviceId,
      title:card.querySelector('[data-session-title]').value.trim(),
      duration_minutes:duration,
      price_rub:price,
      extends_duration:index === 0 || Boolean(card.querySelector('[data-session-extends]')?.checked)
    };
  });
}

function updateSessionComposerSummary(id) {
  const item = allBookings.find(booking => booking.id === id);
  if (!item) return;
  sessionComposerDraft = readSessionComposerDraft();
  const total = sessionComposerDraft.reduce((sum, entry) => sum + entry.price_rub, 0);
  const duration = bookingSessionDuration(sessionComposerDraft);
  $('#sessionComposerTotal').textContent = money(total);
  $('#sessionComposerDuration').textContent = `${duration} мин`;
  const conflict = sessionConflict(item, sessionComposerDraft);
  const warning = $('#sessionComposerWarning');
  const button = $('#sessionComposerSave');
  warning.hidden = !conflict;
  if (conflict) warning.textContent = `${conflict.extra ? `Дополнительные ${conflict.extra} минут` : `Сеанс длительностью ${duration} минут`} пересекаются со следующей записью в ${conflict.time}.`;
  button.disabled = Boolean(conflict) || duration < 5 || sessionComposerDraft.some(entry => entry.title.length < 2);
}

function renderSessionComposer(id) {
  const item = allBookings.find(booking => booking.id === id);
  if (!item) return;
  $('#bookingSheetContent').innerHTML = `<div class="booking-editor-heading"><button class="booking-editor-back" type="button" data-back-booking="${item.id}">${uiIcon('arrow-left')}<span>К записи</span></button><small class="booking-sheet-kicker">Только для этой записи</small></div><h2 id="bookingSheetTitle">Состав сеанса</h2><p class="session-composer-lead">Каталог услуг не изменится. Здесь настраивается только этот визит.</p><form class="session-composer" id="sessionComposerForm" data-booking-id="${item.id}"><div id="sessionComposerItems">${sessionComposerDraft.map(sessionComposerItemMarkup).join('')}</div><button class="session-add-button" type="button" data-add-session-item>${uiIcon('plus')}<span>Дополнительная услуга</span></button><p class="session-composer-warning" id="sessionComposerWarning" role="alert" hidden></p><div class="session-composer-summary"><span><small>Продолжительность</small><strong id="sessionComposerDuration">0 мин</strong></span><span><small>Итого</small><strong id="sessionComposerTotal">0 ₽</strong></span></div><p class="form-error" id="sessionComposerError" hidden></p><button class="primary" id="sessionComposerSave" type="submit">Сохранить состав</button></form>`;
  $('#sessionComposerForm').addEventListener('submit', saveBookingSession);
  updateSessionServiceLabels();
  $('#sessionComposerForm').addEventListener('change', updateSessionServiceLabels);
  updateSessionComposerSummary(id);
}

function openSessionComposer(id) {
  const item = allBookings.find(booking => booking.id === id);
  if (!item || isScheduleBlock(item)) return;
  sessionComposerDraft = bookingSession(item).map(entry => ({ ...entry }));
  $('#bookingSheet').classList.remove('booking-sheet-wide');
  renderSessionComposer(id);
}

async function saveBookingSession(event) {
  event.preventDefault();
  if (!requireWrites()) return;
  const item = allBookings.find(booking => booking.id === event.currentTarget.dataset.bookingId);
  if (!item) return;
  clearFormError('#sessionComposerError');
  sessionComposerDraft = readSessionComposerDraft();
  const conflict = sessionConflict(item, sessionComposerDraft);
  if (conflict) { updateSessionComposerSummary(item.id); return; }
  const totalPrice = sessionComposerDraft.reduce((sum, entry) => sum + entry.price_rub, 0);
  const totalDuration = bookingSessionDuration(sessionComposerDraft);
  if (totalDuration < 5 || totalDuration > 480 || totalPrice > 10000000 || sessionComposerDraft.some(entry => entry.title.length < 2)) {
    showFormError('#sessionComposerError', 'Проверьте названия, длительность и стоимость услуг.');
    return;
  }
  const button = event.submitter;
  button.disabled = true;
  button.textContent = 'Сохраняем…';
  let remoteSaved = false;
  if (sessionItemsRemoteAvailable) {
    const { error } = await db.rpc('save_booking_session', { p_booking:item.id, p_items:sessionComposerDraft });
    if (error?.message?.includes('session_overlap:')) {
      const time = error.message.split('session_overlap:')[1]?.slice(0, 5) || 'следующей записью';
      showFormError('#sessionComposerError', `Сеанс пересекается со следующей записью в ${time}.`);
      button.disabled = false;
      button.textContent = 'Сохранить состав';
      return;
    }
    if (error && !/save_booking_session|schema cache|could not find/i.test(error.message || '')) {
      button.disabled = false;
      button.textContent = 'Сохранить состав';
      showFormError('#sessionComposerError', 'Не удалось проверить состав сеанса. Изменения не сохранены.');
      return;
    }
    remoteSaved = !error;
    if (error) sessionItemsRemoteAvailable = false;
  }
  if (!remoteSaved) {
    let { error } = await db.from('bookings').update({ service_id:sessionComposerDraft[0].service_id, duration_minutes:totalDuration, total_price_rub:totalPrice }).eq('id', item.id).eq('performer_id', currentUser.id);
    if (error) ({ error } = await db.from('bookings').update({ service_id:sessionComposerDraft[0].service_id, duration_minutes:totalDuration }).eq('id', item.id).eq('performer_id', currentUser.id));
    if (error) {
      button.disabled = false;
      button.textContent = 'Сохранить состав';
      showFormError('#sessionComposerError', 'Не удалось сохранить состав сеанса.');
      return;
    }
  }
  bookingSessionItems.set(item.id, sessionComposerDraft.map((entry, index) => ({ ...entry, item_kind:entry.kind, position:index + 1 })));
  writeLocalSessionItems();
  button.textContent = 'Сохранить состав';
  await refreshAfterWrite();
  notify(remoteSaved ? 'Состав сеанса сохранён' : 'Состав сохранён на этом устройстве');
  openBookingSheet(item.id);
}

function providerRescheduleRpcMissing(error) {
  const reason = `${error?.code || ''} ${error?.message || ''} ${error?.details || ''} ${error?.hint || ''}`;
  return /PGRST202|42883/.test(reason)
    || (/reschedule_minuta_provider_booking_v143/i.test(reason) && /not find|does not exist|schema cache|unknown function/i.test(reason));
}

function providerRescheduleErrorMessage(error) {
  const known = {
    '40001:provider_booking_changed':'Запись уже изменилась в другой вкладке. Откройте её заново и выберите время по актуальному расписанию.',
    '23P01:provider_booking_slot_unavailable':'Новое время занято или недоступно. Выберите другое окно.',
    '23P01:booking_outside_active_shift':'Новое время находится вне рабочей смены. Выберите другое окно.',
    'P0001:resource_unavailable':'Для этого времени нет свободного ресурса. Выберите другое окно.',
    'P0001:booking_buffer_conflict':'Новое время слишком близко к соседней записи. Выберите другое окно.',
    '42501:authentication_required':'Войдите в аккаунт снова и обновите журнал.',
    '42501:provider_booking_access_denied':'У вас нет доступа к переносу этой записи.',
    'P0001:provider_booking_not_found':'Запись не найдена. Обновите журнал.',
    'P0001:provider_booking_not_actionable':'Эту запись уже нельзя перенести. Обновите журнал.',
    '55000:provider_booking_series_requires_scope':'Для серии выберите, какие записи нужно перенести.',
    '55000:provider_booking_block_requires_block_rpc':'Откройте перерыв заново и повторите перенос.',
    '22023:invalid_provider_reschedule_target':'Выберите корректные дату и время переноса.'
  };
  if (error?.code === 'MINUTA_BOOKING_CHANGED') {
    return 'Запись уже изменилась или недоступна. Вернитесь к записи и проверьте актуальные данные перед переносом.';
  }
  return known[`${error?.code}:${error?.message}`] || '';
}

async function updateBookingAtExpectedStateLegacy(item, changes, userId) {
  let query = db.from('bookings').update(changes).eq('id', item.id).eq('performer_id', userId)
    .eq('service_id', item.service_id).eq('booking_date', item.booking_date).eq('booking_time', item.booking_time);
  if (item.duration_minutes != null) query = query.eq('duration_minutes', item.duration_minutes);
  if (item.status) query = query.eq('status', item.status);
  const { data, error } = await query.select('id,service_id,performer_id,booking_date,booking_time,duration_minutes,status,client_name');
  if (error) return { error };
  const row = Array.isArray(data) && data.length === 1 ? data[0] : null;
  const matches = row?.id === item.id && row?.performer_id === userId
    && Object.entries(changes).every(([key, value]) => key === 'booking_time'
      ? String(row[key]).slice(0, 5) === String(value).slice(0, 5) : String(row[key]) === String(value));
  return matches ? { data:row, error:null } : { error:{ code:'MINUTA_BOOKING_CHANGED', message:'booking_changed_or_unconfirmed' } };
}

async function updateBookingAtExpectedState(item, changes, userId) {
  const targetDate = String(changes?.booking_date || item.booking_date || '');
  const targetTime = String(changes?.booking_time || item.booking_time || '');
  const result = await db.rpc('reschedule_minuta_provider_booking_v143', {
    p_booking:item.id,
    p_date:targetDate,
    p_time:targetTime,
    p_expected_date:item.booking_date,
    p_expected_time:item.booking_time
  });
  if (result.error && providerRescheduleRpcMissing(result.error)) {
    return updateBookingAtExpectedStateLegacy(item, changes, userId);
  }
  if (result.error) return { error:result.error };
  const row = result.data;
  const confirmed = row?.booking_id === item.id && row?.performer_id === userId
    && row?.service_id === item.service_id
    && String(row?.booking_date) === targetDate
    && String(row?.booking_time).slice(0, 5) === targetTime.slice(0, 5)
    && Number(row?.duration_minutes) === Number(item.duration_minutes)
    && String(row?.status) === String(item.status)
    && row?.notifications_suppressed === false;
  return confirmed
    ? { data:{ ...row, id:row.booking_id }, error:null }
    : { error:{ code:'MINUTA_BOOKING_UNCONFIRMED', message:'provider_reschedule_unconfirmed' } };
}

function bookingMoveTimeIsPast(date, time) {
  const today = businessTodayIso();
  if (date !== today) return date < today;
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone:'Europe/Samara', hour:'2-digit', minute:'2-digit', second:'2-digit', hourCycle:'h23' }).formatToParts(new Date());
  const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${time}:00` <= `${values.hour}:${values.minute}:${values.second}`;
}

function bookingDateLabel(dateIso, { year = false } = {}) {
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(dateIso || '')) ? new Date(`${dateIso}T12:00:00`) : null;
  if (!date || Number.isNaN(date.getTime())) return String(dateIso || '');
  return date.toLocaleDateString('ru-RU', { day:'numeric', month:'long', ...(year ? { year:'numeric' } : {}) });
}

function updateBookingMovePreview() {
  const selected = $('#editBookingSelection');
  if (selected) selected.innerHTML = bookingEditTime
    ? `<span>Будет</span><strong>${escapeHtml(bookingDateLabel($('#editBookingDate')?.value || ''))}, ${escapeHtml(bookingEditTime)}</strong>`
    : '<span>Будет</span><strong>Выберите новое время</strong>';
  $$('[data-edit-booking-time]').forEach(button => {
    const active = button.dataset.editBookingTime === bookingEditTime;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  $$('[data-edit-booking-hour]').forEach(button => {
    const active = button.dataset.editBookingHour === bookingEditHour;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  const submit = $('#bookingEditForm button[type="submit"]');
  if (submit && !$('#bookingEditForm')?.dataset.editorPending) submit.disabled = !bookingEditTime;
}

function blockDurationChoices(selected = 60) {
  return [...new Set([15,30,45,60,90,120,Number(selected)])].filter(value => value >= 1 && value <= 480)
    .sort((a,b) => a-b).map(value => `<option value="${value}" ${value === Number(selected) ? 'selected' : ''}>${value} мин</option>`).join('');
}

function activeProviderBlockContext(preferredLocationId = '') {
  const organization = organizationController?.getActiveOrganization?.() || null;
  const locations = (Array.isArray(organization?.locations) ? organization.locations : [])
    .filter(location => location?.id && location.active !== false);
  const location = locations.find(item => String(item.id) === String(preferredLocationId || ''))
    || locations.find(item => item.is_primary) || locations[0] || null;
  return { organizationId:String(organization?.id || ''), locationId:String(location?.id || ''), locations };
}

function providerBlockLocationOptions(locations, selectedId = '') {
  return locations.map(location => `<option value="${escapeHtml(location.id)}" ${String(location.id) === String(selectedId) ? 'selected' : ''}>${escapeHtml(location.name || 'Филиал')}</option>`).join('');
}

function openBookingEditor(id, preset = {}) {
  const item = allBookings.find(booking => booking.id === id);
  if (!item) return;
  $('#bookingSheet').dataset.bookingId = String(item.id || '');
  $('#bookingSheet').dataset.assistantContext = 'booking-editor';
  const block = isScheduleBlock(item);
  const presetDate = providerAssistantIsoDate(preset.date) || item.booking_date;
  bookingEditTime = /^([01]\d|2[0-3]):[0-5]\d$/.test(String(preset.time || '')) ? String(preset.time) : String(item.booking_time).slice(0, 5);
  bookingEditSlots = [];
  bookingEditHour = bookingEditTime.slice(0, 2);
  $('#bookingSheet').classList.remove('booking-sheet-wide');
  applyClientHighlightClasses($('#bookingSheet'), block ? '' : item.client_phone, 'booking-sheet-');
  $('#bookingSheetContent').innerHTML = `<div class="booking-editor-heading"><button class="booking-editor-back" type="button" data-back-booking="${item.id}">${uiIcon('arrow-left')}<span>К записи</span></button>
    <small class="booking-sheet-kicker">${block ? 'Занятое время' : 'Расписание'}</small></div><h2 id="bookingSheetTitle">${block ? 'Перенести перерыв' : 'Перенести запись'}</h2>
    <form class="booking-editor-form booking-edit-form-compact" id="bookingEditForm" data-booking-id="${item.id}" data-booking-kind="${block ? 'block' : 'client'}" data-expected-booking-date="${escapeHtml(item.booking_date)}" data-expected-booking-time="${escapeHtml(String(item.booking_time).slice(0,5))}" data-expected-series-id="${escapeHtml(item.series_id || '')}">
      <div class="booking-move-summary"><div><span>Было</span><strong>${escapeHtml(bookingDateLabel(item.booking_date))}, ${escapeHtml(String(item.booking_time).slice(0,5))}</strong></div><b aria-hidden="true">→</b><div class="booking-move-selection" id="editBookingSelection" role="status" aria-live="polite"><span>Будет</span><strong>Выберите новое время</strong></div></div>
      <p class="booking-move-context">${escapeHtml(block ? item.client_name || 'Перерыв' : item.services?.name || ownServices.find(service => service.id === item.service_id)?.name || 'Запись')} · ${Number(item.duration_minutes) || 60} мин</p>
      <input id="editBookingService" type="hidden" value="${escapeHtml(item.service_id)}">
      ${block ? `<label>Длительность<select id="editBookingBlockDuration">${blockDurationChoices(item.duration_minutes)}</select></label>` : ''}
      <label>Новая дата<input id="editBookingDate" type="date" min="${businessTodayIso()}" value="${presetDate}" required></label>
      <div class="booking-edit-slot-group" role="group" aria-labelledby="editBookingTimesLabel"><span class="sr-only" id="editBookingTimesLabel">Свободное время</span><div class="booking-editor-times booking-time-picker" id="editBookingTimes"><span>Ищем свободное время…</span></div></div>
      ${block ? '' : bookingSeriesScopeMarkup(item, 'editBookingSeriesScope', 'Какие записи перенести')}
      <p class="form-error" id="bookingEditError" hidden></p>
      ${block ? `<details class="booking-move-advanced"><summary>Дополнительно</summary>
        <label>Название<input id="editBookingBlockTitle" maxlength="80" value="${escapeHtml(item.client_name || 'Перерыв')}" required></label>
        <label>Заметка к перерыву<textarea id="editBookingNote" maxlength="1000" rows="2">${escapeHtml(bookingDisplayNote(item))}</textarea></label>
        ${bookingColorPicker('editBookingColor', bookingColor(item))}
      </details>` : ''}
      <div class="booking-sheet-submit-bar"><button class="primary" type="submit" disabled>${block ? 'Перенести перерыв' : 'Перенести запись'}</button></div>
    </form>`;
  $('#bookingSheet').hidden = false;
  document.body.classList.add('booking-sheet-open');
  $('#bookingEditForm').dataset.editorRevision = String(++bookingEditorRevision);
  $('#editBookingService').addEventListener('change', () => loadBookingEditSlots(id));
  $('#editBookingDate').addEventListener('change', () => loadBookingEditSlots(id));
  $('#editBookingBlockDuration')?.addEventListener('change', () => loadBookingEditSlots(id));
  $$('[name="editBookingSeriesScope"]').forEach(control => control.addEventListener('change', () => loadBookingEditSlots(id, true)));
  $('#bookingEditForm').addEventListener('submit', saveBookingChanges);
  loadBookingEditSlots(id, block);
  updateBookingMovePreview();
}

async function saveBookingChanges(event) {
  event.preventDefault();
  if (!requireWrites()) return;
  const form = event.currentTarget;
  const revision = bookingEditorRevision;
  if (form !== $('#bookingEditForm') || $('#bookingSheet').hidden
    || form.dataset.editorRevision !== String(revision) || form.dataset.editorPending) return;
  const userId = currentUser.id;
  const generation = sessionGeneration;
  const organizationId = activeClientOrganizationId;
  const isCurrent = () => sessionIsCurrent(userId, generation) && activeClientOrganizationId === organizationId
    && bookingEditorRevision === revision && form === $('#bookingEditForm') && !$('#bookingSheet').hidden;
  const id = form.dataset.bookingId;
  const item = allBookings.find(booking => booking.id === id);
  const seriesId = form.dataset.expectedSeriesId || item?.series_id;
  const block = isScheduleBlock(item);
  const service = ownServices.find(entry => entry.id === $('#editBookingService').value);
  const date = $('#editBookingDate').value;
  const seriesScope = form.elements.editBookingSeriesScope?.value || 'one';
  const color = block ? ($('[name="editBookingColor"]:checked')?.value || bookingColor(item)) : bookingColor(item);
  const note = block ? ($('#editBookingNote')?.value.trim() || '') : bookingDisplayNote(item);
  const blockTitle = block ? ($('#editBookingBlockTitle')?.value.trim() || '') : '';
  if (!item || (!block && !service) || !date || !bookingEditTime || (block && blockTitle.length < 2)) {
    showFormError('#bookingEditError', block ? 'Выберите длительность, дату и свободное время.' : 'Выберите услугу, дату и свободное время.');
    return;
  }
  if (bookingMoveTimeIsPast(date, bookingEditTime)) { showFormError('#bookingEditError', 'Это время уже прошло. Выберите новое время.'); return; }
  const button = event.submitter || form.querySelector('button[type="submit"]');
  if (!button) {
    showFormError('#bookingEditError', 'Не удалось запустить перенос. Закройте форму и попробуйте ещё раз.');
    return;
  }
  form.dataset.editorPending = 'true';
  button.disabled = true;
  button.textContent = 'Сохраняем…';
  const changes = { service_id:item.service_id, duration_minutes:block ? Number($('#editBookingBlockDuration')?.value || item.duration_minutes) : item.duration_minutes, booking_date: date, booking_time: `${bookingEditTime}:00` };
  if (block) changes.client_name = blockTitle;
  let primaryConfirmed = false;
  const unconfirmedMessage = 'Не удалось подтвердить результат. Проверьте актуальную запись перед повтором.';
  try {
    let error = null;
    let affected = [{ booking_id:id }];
    if (item.series_id && !block) {
      const result = await db.rpc('manage_minuta_booking_series_v123', {
        p_booking: id,
        p_action: 'reschedule',
        p_scope: seriesScope,
        p_date: date,
        p_time: changes.booking_time,
        p_expected_date: form.dataset.expectedBookingDate,
        p_expected_time: `${form.dataset.expectedBookingTime}:00`
      });
      if (!isCurrent()) return;
      error = result.error;
      if (!error) {
        const data = result.data;
        const entries = data?.affected;
        const confirmed = data?.series_id === seriesId && data?.action === 'reschedule' && data?.scope === seriesScope
          && Number.isSafeInteger(data?.affected_count) && data.affected_count > 0 && data.affected_count <= 24
          && Array.isArray(entries) && entries.length === data.affected_count
          && entries.every(entry => entry && typeof entry.booking_id === 'string'
            && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(entry.booking_id)
            && Number.isSafeInteger(entry.occurrence) && entry.occurrence > 0 && entry.occurrence <= 24)
          && new Set(entries.map(entry => entry.booking_id)).size === entries.length
          && new Set(entries.map(entry => entry.occurrence)).size === entries.length
          && (seriesScope !== 'one' || (entries.length === 1 && entries[0].booking_id === id));
        if (!confirmed) throw new Error('unconfirmed_series_reschedule');
        affected = entries;
      }
    } else if (block) {
      const result = await db.rpc('update_provider_block_v141', {
        p_booking:id,
        p_date:date,
        p_time:changes.booking_time,
        p_duration:changes.duration_minutes,
        p_expected_date:form.dataset.expectedBookingDate,
        p_expected_time:`${form.dataset.expectedBookingTime}:00`,
        p_expected_duration:Number(item.duration_minutes || 60),
        p_title:blockTitle,
        p_note:note
      });
      error = result.error;
      if (!error) {
        const data = result.data;
        const confirmed = data?.booking_id === id
          && String(data?.booking_date) === date
          && String(data?.booking_time).slice(0, 5) === bookingEditTime
          && Number(data?.duration_minutes) === changes.duration_minutes
          && data?.notifications_suppressed === true;
        if (!confirmed) throw new Error('unconfirmed_block_update');
      }
    } else {
      ({ error } = await updateBookingAtExpectedState(item, changes, userId));
    }
    if (!isCurrent()) return;
    if (error) {
      const seriesErrors = {
        'P0001:series_slot_unavailable':'Одно из новых времён занято. Проверьте журнал и выберите другое время.',
        '22023:series_reschedule_out_of_range':'После переноса часть серии окажется в прошлом или слишком далеко. Выберите другую дату.',
        '22023:series_reschedule_target_required':'Выберите дату и время переноса.',
        '22023:invalid_series_action':'Параметры переноса устарели. Откройте форму заново.',
        '42501:authentication_required':'Войдите в аккаунт снова и обновите журнал.',
        '42501:booking_access_denied':'У вас нет доступа к переносу этой записи.',
        'P0001:booking_not_found':'Запись не найдена. Обновите журнал.',
        'P0001:booking_not_in_series':'Эта запись не входит в серию. Обновите журнал.',
        'P0001:series_booking_not_actionable':'Эту запись уже нельзя перенести. Обновите журнал.',
        'P0001:series_has_no_actionable_bookings':'В выбранной части серии нет записей, доступных для переноса. Обновите журнал.',
        '40001:series_anchor_changed':'Запись уже изменилась в другой вкладке. Откройте её заново и выберите время по актуальному расписанию.',
        '22023:expected_series_anchor_required':'Форма переноса устарела. Откройте запись заново.',
        '22023:invalid_expected_series_anchor':'Исходные дата и время неполны. Откройте запись заново.'
      };
      const blockErrors = {
        '40001:block_changed':'Перерыв уже изменён в другой вкладке. Откройте его заново.',
        '23P01:block_slot_unavailable':'Новое время занято или не подходит по длительности. Выберите другое окно.',
        '42501:block_access_denied':'У вас нет доступа к этому перерыву.',
        'P0001:block_not_found':'Перерыв не найден. Обновите журнал.'
      };
      const message = block ? blockErrors[`${error.code}:${error.message}`]
        : seriesId ? seriesErrors[`${error.code}:${error.message}`]
        : providerRescheduleErrorMessage(error);
      showFormError('#bookingEditError', message || unconfirmedMessage);
      if (message) await loadBookingEditSlots(id);
      return;
    }
    primaryConfirmed = true;
    if (!block) affected.forEach(entry => notifyTelegramClient(entry.booking_id, 'rescheduled'));
    const colorRemoteSaved = block ? await saveBookingColor(id, color, { rerender:false, isCurrent }) : true;
    if (!isCurrent()) return;
    let noteRemoteSaved = true;
    if (block) {
      // The v141 move RPC writes the title and note atomically with the slot.
      noteRemoteSaved = true;
      if (!isCurrent()) return;
    }
    selectScheduleDate(date);
    const refreshed = await refreshAfterWrite();
    if (!isCurrent()) return;
    if (refreshed === false) {
      showFormError('#bookingEditError', 'Основное изменение сохранено, но журнал не обновлён. Проверьте запись перед следующим действием.');
      return;
    }
    const affectedCount = affected.length;
    notify(!colorRemoteSaved
      ? 'Запись обновлена, но цвет или заметку не удалось полностью сохранить. Проверьте запись.'
      : noteRemoteSaved
      ? (block ? 'Перерыв обновлён' : affectedCount > 1 ? `Перенесено: ${seriesBookingCountLabel(affectedCount)}` : 'Запись обновлена')
      : (block ? 'Перерыв обновлён. Заметка сохранена на этом устройстве' : 'Запись обновлена, но заметку сохранить не удалось'));
    openBookingSheet(id);
  } catch {
    if (isCurrent()) showFormError('#bookingEditError', primaryConfirmed
      ? 'Основное изменение сохранено, но обновление не завершено. Проверьте запись перед следующим действием.'
      : unconfirmedMessage);
  } finally {
    if (isCurrent()) {
      delete form.dataset.editorPending;
      button.disabled = !bookingEditTime;
      button.textContent = block ? 'Перенести перерыв' : 'Перенести запись';
    }
  }
}

function offlineCandidateSlots(serviceId, dateIso, requestedDuration = 0) {
  const service = ownServices.find(item => item.id === serviceId && item.active);
  const date = parseLocalIsoDate(dateIso);
  if (!service || !date || dateIso < businessTodayIso()) return [];
  const weekday = ((date.getDay() + 6) % 7) + 1;
  const schedule = scheduleRows.find(row => Number(row.weekday) === weekday);
  if (schedule?.enabled === false) return [];
  const duration = Math.max(1, Number(requestedDuration || service.duration_minutes || 60));
  const start = minutesFromTime(schedule?.start_time || '10:00');
  const end = minutesFromTime(schedule?.end_time || '20:00');
  const now = new Date();
  const earliest = dateIso === businessTodayIso() ? (now.getHours() * 60) + now.getMinutes() : start;
  const slots = [];
  const firstSlot = Math.ceil(start / NEW_BOOKING_GRID_MINUTES) * NEW_BOOKING_GRID_MINUTES;
  for (let minute = firstSlot; minute + duration <= end; minute += NEW_BOOKING_GRID_MINUTES) {
    if (minute < earliest) continue;
    const issue = bookingPlacementIssue({ id:'offline-candidate', duration_minutes:duration }, dateIso, minute);
    const queuedConflict = offlineBookingQueue.some(item => {
      if (item.id === editingOfflineBookingId) return false;
      if (item.date !== dateIso) return false;
      const queuedStart = minutesFromTime(item.time);
      const queuedService = ownServices.find(entry => entry.id === item.serviceId);
      const queuedEnd = queuedStart + Math.max(1, Number(item.durationMinutes || queuedService?.duration_minutes || 60));
      return minute < queuedEnd && minute + duration > queuedStart;
    });
    if (!issue && !queuedConflict) slots.push(timeFromMinutes(minute));
  }
  return slots;
}

function newBookingOutsideScheduleLabel(dateIso) {
  const date = parseLocalIsoDate(dateIso);
  if (!date) return 'В рабочем графике нет свободного окна.';
  const weekday = ((date.getDay() + 6) % 7) + 1;
  const schedule = scheduleRows.find(row => Number(row.weekday) === weekday);
  if (schedule?.enabled === false) return 'По рабочему графику на эту дату установлен выходной.';
  if (daysOff.some(entry => entry.off_date === dateIso && entry.all_day)) return 'Эта дата закрыта в исключениях рабочего графика.';
  return 'Свободных окон по рабочему графику не осталось.';
}

function renderNewBookingOutsideSchedulePrompt({ historical = false, preferredTime = '' } = {}) {
  const holder = $('#newBookingTimes');
  const date = $('#newBookingDate')?.value;
  if (!holder || !date) return;
  const preferredPast = !historical && date === businessTodayIso() && preferredTime && bookingMoveTimeIsPast(date, preferredTime);
  const title = preferredPast
    ? `${preferredTime} уже прошло.`
    : date === businessTodayIso() && !historical
      ? 'На сегодня будущих окон не осталось.'
      : newBookingOutsideScheduleLabel(date);
  const hint = historical
    ? 'Укажите фактическое время визита вручную.'
    : preferredPast && newBookingMode === 'client'
      ? 'Откройте нужное прошедшее время прямо в расписании.'
      : 'Выберите другую дату с будущим свободным окном.';
  holder.innerHTML = `<div class="booking-outside-schedule-prompt"><span aria-hidden="true">!</span><div><strong>${escapeHtml(title)}</strong><small>${escapeHtml(hint)}</small></div><button class="secondary-button" id="newBookingChooseAnotherDate" type="button">Выбрать другую дату</button></div>`;
  $('#newBookingChooseAnotherDate')?.addEventListener('click', () => {
    const input = $('#newBookingDate');
    input?.focus();
    input?.showPicker?.();
  });
}

function renderHistoricalTimeEntry() {
  const holder = $('#newBookingTimes');
  const date = $('#newBookingDate')?.value || '';
  if (!holder || !date) return;
  const duration = newBookingDurationMinutes();
  const value = /^([01]\d|2[0-3]):[0-5]\d$/.test(newBookingPreferredTime) ? newBookingPreferredTime : newBookingTime;
  const time = /^([01]\d|2[0-3]):[0-5]\d$/.test(value) ? value : '';
  let warning = '';
  if (time && duration) {
    const start = minutesFromTime(time);
    const overlap = bookingPlacementIssue({ id:'new-historical-booking-candidate', duration_minutes:duration }, date, start, { allowPast:true, ignoreSchedule:true });
    const scheduleIssue = bookingPlacementIssue({ id:'new-historical-booking-candidate', duration_minutes:duration }, date, start, { allowPast:true });
    if (overlap) warning = `<div class="booking-time-warning is-error"><strong>Это время пересекается с другой записью.</strong><br>Укажите фактическое время без пересечения.</div>`;
    else if (scheduleIssue) warning = `<div class="booking-time-warning booking-time-outside"><strong>Время вне рабочего графика</strong><br>Если визит действительно состоялся, его можно сохранить.</div>`;
  }
  holder.innerHTML = `<label class="booking-historical-time" for="newBookingHistoricalTime"><span>Время визита</span><input id="newBookingHistoricalTime" type="time" step="300" value="${escapeHtml(time)}" required></label>${warning}<small class="booking-historical-time-hint">Система проверит возможное пересечение перед сохранением.</small>`;
  const input = $('#newBookingHistoricalTime');
  input?.addEventListener('input', () => {
    newBookingTime = String(input.value || '').slice(0, 5);
    newBookingPreferredTime = newBookingTime;
    clearFormError('#newBookingError');
    updateNewBookingSubmitCaption();
  });
  input?.addEventListener('change', () => {
    newBookingTime = String(input.value || '').slice(0, 5);
    newBookingPreferredTime = newBookingTime;
    saveNewBookingDraft();
    renderHistoricalTimeEntry();
  });
}

async function loadNewBookingSlots() {
  const service = $('#newBookingService')?.value;
  const date = $('#newBookingDate')?.value;
  const holder = $('#newBookingTimes');
  if (!date || !holder || (newBookingMode !== 'block' && !service)) return;
  const requestId = ++newBookingSlotsRequestId;
  const preferredTime = newBookingPreferredTime;
  const duration = newBookingDurationMinutes();
  newBookingTime = '';
  newBookingSlots = [];
  newBookingHour = '';
  const historical = newBookingHistoricalMode || date < businessTodayIso();
  if (historical) {
    newBookingHistoricalMode = true;
    newBookingTime = preferredTime || '';
    if (!navigator.onLine) {
      holder.innerHTML = '<div class="booking-time-warning"><strong>Для записи в прошлом нужен интернет.</strong><br>Сервер проверит права мастера и отсутствие пересечений.</div>';
    } else {
      renderHistoricalTimeEntry();
    }
    updateNewBookingConnectivity();
    updateNewBookingDurationControl();
    clearFormError('#newBookingError');
    return;
  }
  if (!navigator.onLine) {
    newBookingSlots = offlineCandidateSlots(service, date, duration);
    // An offline booking is a request that the server will validate after the
    // connection returns. Keep an explicitly selected timeline/draft time even
    // when the cached snapshot cannot offer it as a confirmed free slot.
    newBookingTime = preferredTime || '';
    newBookingHour = String(newBookingTime || newBookingSlots[0] || '').slice(0, 2);
    if (newBookingSlots.length) renderNewBookingTimePicker({ offline:true });
    else if (newBookingTime) holder.innerHTML = `<div class="booking-time-warning"><strong>${escapeHtml(newBookingTime)} сохранится как отложенный запрос.</strong><br>После подключения сервер проверит время: свободное окно будет создано, а при конфликте запись останется в очереди с кнопкой «Изменить».</div>`;
    else holder.innerHTML = '<div class="booking-time-warning">По последней сохранённой копии свободных вариантов нет. Откройте нужное время из расписания или подключитесь к интернету, чтобы обновить свободные окна.</div>';
    clearFormError('#newBookingError');
    updateNewBookingSubmitCaption();
    return;
  }
  if (!bookingCreationReady && !writesAllowed) {
    holder.innerHTML = '<div class="booking-time-warning new-booking-readiness-note"><strong>Проверяем записи и свободное время…</strong><br>Форма уже открыта. Создание станет доступно автоматически после безопасной сверки.</div>';
    updateNewBookingConnectivity();
    synchronizeProvider();
    return;
  }
  holder.innerHTML = '<span>Ищем свободное время…</span>';
  const mode = newBookingMode;
  const locationId = $('#newBookingLocation')?.value || '';
  const requestIsCurrent = () => requestId === newBookingSlotsRequestId
    && $('#newBookingService')?.value === service
    && $('#newBookingDate')?.value === date
    && ($('#newBookingLocation')?.value || '') === locationId
    && newBookingMode === mode
    && newBookingDurationMinutes() === duration;
  let data, error;
  if (newBookingMode === 'block') {
    const context = activeProviderBlockContext($('#newBookingLocation')?.value || '');
    if (!context.organizationId || !context.locationId) {
      holder.innerHTML = '<div class="booking-time-warning">Не найден активный филиал. Настройте его в разделе «Организация».</div>';
      updateNewBookingSubmitCaption();
      return;
    }
    ({ data, error } = await db.rpc('get_provider_block_slots_v141', {
      p_organization:context.organizationId,
      p_location:context.locationId,
      p_date:date,
      p_duration:duration,
      p_ignore_booking:null
    }));
  } else {
    const [availability] = await Promise.all([
      getProviderAvailableSlots({ p_service:service, p_start:date, p_end:date }),
      bookingPolicy.booking_buffer_enabled
        ? loadAutomaticBookingBreaks(date, currentUser?.id, sessionGeneration).catch(() => ({ ok:false }))
        : Promise.resolve({ ok:true })
    ]);
    ({ data, error } = availability);
  }
  if (!requestIsCurrent()) return;
  if (error) {
    const missingUpdate = newBookingMode === 'block' && /get_provider_block_slots_v141|schema cache|could not find|does not exist/i.test(String(error.message || ''));
    holder.innerHTML = `<div class="booking-time-warning">${missingUpdate ? 'Обновление безопасного занятия времени ещё не установлено. Обновите страницу через несколько минут.' : 'Не удалось проверить рабочий график. Обновите данные и повторите попытку.'}</div>`;
    return;
  }
  if (!data?.length) {
    renderNewBookingOutsideSchedulePrompt({ preferredTime });
    return;
  }
  newBookingSlots = newBookingGridSlots(data.map(slot => String(slot.booking_time).slice(0, 5))).filter(time => !bookingMoveTimeIsPast(date, time) && !bookingPlacementIssue({ id:'new-booking-candidate', duration_minutes:duration },
    date,
    minutesFromTime(time),
    { respectAutomaticBreakReleases:true }
  ));
  if (!newBookingSlots.length) {
    renderNewBookingOutsideSchedulePrompt({ preferredTime });
    return;
  }
  newBookingTime = preferredTime && newBookingSlots.includes(preferredTime) ? preferredTime : '';
  newBookingHour = String(newBookingTime || preferredTime || newBookingSlots[0]).slice(0, 2);
  if (!newBookingSlots.some(time => time.startsWith(`${newBookingHour}:`))) newBookingHour = newBookingSlots[0].slice(0, 2);
  renderNewBookingTimePicker();
  updateNewBookingDurationControl();
  updateNewBookingSubmitCaption();
  clearFormError('#newBookingError');
}

function newBookingPreferredUnavailableMarkup() {
  const preferredTime = newBookingPreferredTime;
  if (!preferredTime || newBookingSlots.includes(preferredTime)) return '';
  const date = $('#newBookingDate')?.value || '';
  const preferredPast = date === businessTodayIso() && bookingMoveTimeIsPast(date, preferredTime);
  const duration = newBookingDurationMinutes();
  const candidate = { id:'new-booking-preferred-candidate', duration_minutes:duration };
  const startMinute = minutesFromTime(preferredTime);
  const hardIssue = preferredPast ? '' : bookingPlacementIssue(candidate, date, startMinute, { ignoreAutomaticBuffer:true });
  const bufferIssue = preferredPast || hardIssue ? '' : bookingPlacementIssue(candidate, date, startMinute, { respectAutomaticBreakReleases:true });
  const copy = preferredPast
    ? `<strong>${escapeHtml(preferredTime)} уже прошло.</strong><br>${newBookingMode === 'client' ? 'Откройте нужное прошедшее время прямо в расписании.' : 'Для «Занять время» выберите будущее окно или другую дату.'}`
    : hardIssue
      ? `<strong>Услуга на ${duration} мин не помещается в ${escapeHtml(preferredTime)}.</strong><br>${escapeHtml(hardIssue)}.`
      : bufferIssue
        ? `<strong>${escapeHtml(preferredTime)} закрыто неосвобождённым автоматическим перерывом.</strong><br>${escapeHtml(bufferIssue)}. Освободите этот перерыв в расписании или выберите другое окно.`
      : `Ранее выбранное время ${escapeHtml(preferredTime)} сейчас недоступно. Выберите другое.`;
  return `<div class="booking-time-warning">${copy}</div>`;
}

function renderNewBookingTimePicker({ offline = false, historical = false } = {}) {
  const holder = $('#newBookingTimes');
  if (!holder || !newBookingSlots.length) return;
  const perMinuteService = newBookingMode === 'client'
    && Number(selectedNewBookingService()?.duration_minutes) === 1;
  if (perMinuteService && !historical) {
    const preferredUnavailable = newBookingPreferredUnavailableMarkup();
    const duration = newBookingDurationMinutes();
    const minutePrice = Math.max(0, Number(selectedNewBookingService()?.price_rub) || 0);
    const totalPrice = Math.round(minutePrice * duration);
    const startParts = String(newBookingTime || '').split(':').map(Number);
    const endMinutes = startParts.length === 2 && startParts.every(Number.isFinite)
      ? startParts[0] * 60 + startParts[1] + duration
      : null;
    const endTime = endMinutes === null
      ? ''
      : `${String(Math.floor(endMinutes / 60) % 24).padStart(2, '0')}:${String(endMinutes % 60).padStart(2, '0')}`;
    const selectionSummary = newBookingTime
      ? `<div class="booking-time-selection-summary"><div><strong>Запись: ${newBookingTime}–${endTime}</strong><span>${duration} мин × ${new Intl.NumberFormat('ru-RU').format(minutePrice)} ₽</span></div><div><span>Итого</span><strong>${new Intl.NumberFormat('ru-RU').format(totalPrice)} ₽</strong></div></div>`
      : '';
    const nearbySlots = bookingNearbyTimeSlots(newBookingSlots, newBookingTime, newBookingPreferredTime);
    holder.innerHTML = `${offline ? `<div class="booking-time-warning">${newBookingPreferredTime || newBookingTime || 'Выбранное время'} сохранится как отложенный запрос. Сервер проверит его после подключения.</div>` : ''}${preferredUnavailable}
      <div class="booking-time-guide"><strong>Ближайшие окна</strong><span>${newBookingTime ? `Выбрано ${newBookingTime}` : 'Свободное время рядом'}</span></div>
      <div class="booking-time-slots booking-time-slots-nearby">${nearbySlots.map(time => `<button type="button" class="${time === newBookingTime ? 'active' : ''}" aria-pressed="${time === newBookingTime}" data-new-booking-time="${time}">${time}</button>`).join('')}</div>
      ${bookingRemainingTimeMarkup(newBookingSlots, nearbySlots, newBookingTime)}${selectionSummary}`;
    activateBookingRemainingTimeScroll(holder);
    return;
  }
  const nearbySlots = bookingNearbyTimeSlots(newBookingSlots, newBookingTime, newBookingPreferredTime);
  const preferredUnavailable = newBookingPreferredUnavailableMarkup();
  holder.innerHTML = `${offline ? '<div class="booking-time-warning">Предварительные варианты из последней сохранённой копии. После подключения система обязательно проверит выбранное время на сервере.</div>' : ''}${preferredUnavailable}
    <div class="booking-time-guide"><strong>Ближайшие окна</strong><span>${newBookingTime ? `Выбрано ${newBookingTime}` : 'Шаг записи — 30 минут'}</span></div>
    <div class="booking-time-slots booking-time-slots-nearby">${nearbySlots.map(time => `<button type="button" class="${time === newBookingTime ? 'active' : ''}" aria-pressed="${time === newBookingTime}" data-new-booking-time="${time}">${time}</button>`).join('')}</div>
    ${bookingRemainingTimeMarkup(newBookingSlots, nearbySlots, newBookingTime)}`;
  activateBookingRemainingTimeScroll(holder);
}

function newBookingHistoricalCalculatedAmount() {
  const service = selectedNewBookingService();
  if (!service) return 0;
  const unitPrice = Math.max(0, Number(service.price_rub || 0));
  const total = Number(service.duration_minutes) === 1 ? unitPrice * newBookingDurationMinutes() : unitPrice;
  return Math.min(1000000, Math.max(0, Math.round(total)));
}

function updateNewBookingHistoricalPayment({ resetAmount = false } = {}) {
  const panel = $('#newBookingHistoricalPayment');
  const method = $('#newBookingHistoricalPaymentMethod');
  const amount = $('#newBookingHistoricalAmount');
  const hint = $('#newBookingHistoricalPaymentHint');
  if (!panel || !method || !amount) return;
  const visible = newBookingMode === 'client' && newBookingHistoricalMode;
  panel.hidden = !visible;
  if (!visible) return;
  const unpaid = method.value === 'unpaid';
  const calculated = newBookingHistoricalCalculatedAmount();
  if (unpaid) {
    if (!amount.disabled && amount.value !== '') amount.dataset.paidAmount = amount.value;
    amount.value = '0';
    amount.disabled = true;
  } else {
    amount.disabled = false;
    if (resetAmount || amount.dataset.userEdited !== 'true' || Number(amount.value) === 0) {
      amount.value = String(Number(amount.dataset.paidAmount || calculated));
      delete amount.dataset.userEdited;
    }
    amount.dataset.paidAmount = amount.value;
  }
  if (hint) hint.textContent = unpaid
    ? 'Визит попадёт в посещения, а сумма — в подтверждённый долг.'
    : `В полученные деньги попадёт ${money(Number(amount.value || 0))}.`;
  updateNewBookingSubmitCaption();
}

function updateNewBookingSubmitCaption() {
  const submit = $('#newBookingSubmit');
  if (!submit) return;
  const historicalState = $('#newBookingForm')?.dataset.historicalCreateState;
  if (historicalState) {
    submit.disabled = true;
    submit.textContent = historicalState === 'pending' ? 'Создаём…' : historicalState === 'created' ? 'Запись уже создана' : 'Результат не подтверждён';
    submit.title = historicalState === 'pending' ? 'Дождитесь результата создания' : 'Проверьте расписание перед созданием новой записи';
    return;
  }
  const occurrenceCount = Math.max(1, Number($('#newBookingOccurrences')?.value || 1));
  const intervalField = $('#newBookingIntervalField');
  if (intervalField) intervalField.hidden = occurrenceCount <= 1;
  const recurrenceHint = $('#newBookingRecurrenceHint');
  if (recurrenceHint) recurrenceHint.hidden = occurrenceCount <= 1;
  const recurrence = $('#newBookingRecurrence');
  if (recurrence) recurrence.classList.toggle('is-single', occurrenceCount <= 1);
  const historicalOffline = newBookingHistoricalMode && !navigator.onLine;
  const historicalMethod = $('#newBookingHistoricalPaymentMethod')?.value || 'cash';
  const historicalAmountValue = $('#newBookingHistoricalAmount')?.value ?? '';
  const historicalAmount = historicalAmountValue === '' ? Number.NaN : Math.round(Number(historicalAmountValue));
  const historicalAmountValid = Number.isInteger(historicalAmount) && historicalAmount >= 0 && historicalAmount <= 1000000;
  const historicalCaption = 'Сохранить';
  const creationAllowed = navigator.onLine
    ? Boolean(currentUser && (writesAllowed || bookingCreationReady))
    : canQueueOfflineBooking();
  submit.textContent = editingOfflineBookingId ? 'Сохранить исправление' : newBookingHistoricalMode ? historicalCaption : !navigator.onLine && newBookingMode === 'client' ? 'Сохранить до подключения' : newBookingMode === 'block' ? 'Занять время' : occurrenceCount > 1 ? `Создать серию из ${occurrenceCount}` : 'Создать запись';
  submit.disabled = !newBookingTime || !creationAllowed;
  if (newBookingHistoricalMode && historicalMethod !== 'unpaid' && !historicalAmountValid) submit.disabled = true;
  if (historicalOffline) submit.disabled = true;
  submit.title = historicalOffline
    ? 'Запись в прошлом создаётся только при подключении к интернету'
    : !creationAllowed
      ? (navigator.onLine ? 'Дождитесь безопасной сверки записей и расписания' : offlineBookingStatusText())
      : submit.disabled ? 'Сначала выберите время в расписании' : '';
}

function updateNewBookingConnectivity() {
  if (!$('#newBookingForm')) return;
  const offline = !navigator.onLine;
  const bookingDate = $('#newBookingDate')?.value || '';
  const today = businessTodayIso();
  const historical = bookingDate < today || (bookingDate === today && newBookingHistoricalMode);
  newBookingHistoricalMode = historical;
  const creationAllowed = offline ? canQueueOfflineBooking() : Boolean(currentUser && (writesAllowed || bookingCreationReady));
  const readiness = $('#newBookingReadiness');
  if (readiness) {
    readiness.hidden = creationAllowed && !offline;
    readiness.dataset.state = creationAllowed ? (offline ? 'offline' : 'ready') : 'checking';
    readiness.textContent = creationAllowed
      ? 'Офлайн: запрос сохранится на устройстве, а сервер проверит свободное время после подключения.'
      : offline
        ? offlineBookingStatusText()
        : 'Проверяем записи и свободное время. Создание станет доступно автоматически.';
  }
  const modeToggle = $('#newBookingModeToggle');
  if (modeToggle) modeToggle.hidden = historical;
  const blockButton = $('[data-new-booking-mode="block"]');
  if (blockButton) {
    blockButton.disabled = offline || historical;
    blockButton.title = historical ? 'В прошлом можно добавить только фактический визит клиента' : offline ? 'Блокировку времени можно создать после подключения' : '';
  }
  const occurrences = $('#newBookingOccurrences');
  const interval = $('#newBookingInterval');
  if (offline || historical) {
    if (newBookingMode === 'block') setNewBookingMode('client');
    if (occurrences) occurrences.value = '1';
  }
  if (occurrences) occurrences.disabled = offline || historical;
  if (interval) interval.disabled = offline || historical;
  const recurrence = $('#newBookingRecurrence');
  if (recurrence) {
    recurrence.hidden = newBookingMode === 'block' || historical;
    recurrence.classList.toggle('is-offline-disabled', offline && !historical);
  }
  const subtitle = $('#newBookingDateTimeSubtitle');
  const timeCaption = $('#newBookingTimeCaption');
  if (subtitle) subtitle.textContent = historical ? 'Укажите фактические дату и время визита' : 'Выберите удобное свободное окно';
  if (timeCaption) timeCaption.textContent = historical ? 'Фактическое время' : 'Свободное время';
  updateNewBookingHistoricalPayment();
  updateNewBookingSubmitCaption();
}

let newBookingClientSuggestionMap = new Map();
let newBookingClientSuggestionTimer = null;
let newBookingAutoFilledPhone = '';
let newBookingAutoFilledName = '';
let newBookingClientBaseTitle = 'Новая запись';
let newBookingClientBaseSubtitle = 'Имя, номер целиком или последние 4 цифры';

function newBookingClientPhoneLabel(phone, fallback = '') {
  const digits = normalizePhone(phone);
  if (digits.length === 11 && digits.startsWith('7')) return `+7 (${digits.slice(1,4)}) ${digits.slice(4,7)}-${digits.slice(7,9)}-${digits.slice(9)}`;
  return fallback || (digits ? `+${digits}` : 'Без телефона');
}

function newBookingContactPickerSupported() {
  return Boolean(navigator.contacts?.select && navigator.contacts?.getProperties);
}

function newBookingRecentCallsSupported() {
  try {
    const bridge = globalThis.PrimeTimeAndroidCalls;
    return Boolean(bridge?.openRecentCalls && bridge?.isAvailable?.());
  } catch {
    return false;
  }
}

function refreshNewBookingRecentCalls() {
  const button = $('#newBookingRecentCalls');
  if (button) button.hidden = !newBookingRecentCallsSupported();
}

function chooseNewBookingRecentCall() {
  if (!$('#newBookingForm') || !newBookingRecentCallsSupported()) return;
  try {
    globalThis.PrimeTimeAndroidCalls.openRecentCalls();
  } catch {
    notify('Не удалось открыть недавние звонки');
  }
}

function receiveNewBookingRecentCall(rawPhone) {
  const form = $('#newBookingForm');
  const phoneInput = $('#newBookingPhone');
  const phone = normalizePhone(rawPhone);
  if (!form || !phoneInput || !phone) return false;
  phoneInput.value = newBookingClientPhoneLabel(phone, String(rawPhone || '').slice(0, 24));
  newBookingAutoFilledName = '';
  newBookingAutoFilledPhone = '';
  handleNewBookingPhoneInput();
  const fields = $('#newBookingClientFields');
  if (fields && !fields.dataset.clientLookupState) {
    fields.dataset.clientLookupState = 'recent-call';
    $('#newBookingSectionSubtitle').textContent = 'Номер из недавнего звонка — укажите имя';
    $('#newBookingName')?.focus?.();
  }
  saveNewBookingDraft();
  return true;
}

globalThis.PrimeTimeReceiveRecentCall = receiveNewBookingRecentCall;
globalThis.addEventListener?.('primetime-native-ready', refreshNewBookingRecentCalls);

async function refreshNewBookingContactPicker() {
  const button = $('#newBookingContactPicker');
  if (!button || !newBookingContactPickerSupported()) return;
  try {
    const properties = await navigator.contacts.getProperties();
    if (button === $('#newBookingContactPicker')) button.hidden = !properties?.includes('name') || !properties?.includes('tel');
  } catch {
    if (button === $('#newBookingContactPicker')) button.hidden = true;
  }
}

async function chooseNewBookingContact() {
  const form = $('#newBookingForm');
  const button = $('#newBookingContactPicker');
  if (!form || !button || !newBookingContactPickerSupported()) return;
  button.disabled = true;
  try {
    const contacts = await navigator.contacts.select(['name','tel'], { multiple:false });
    if (form !== $('#newBookingForm') || !contacts?.length) return;
    const contact = contacts[0];
    const name = String(contact?.name?.[0] || '').trim().slice(0, 80);
    const rawPhone = (Array.isArray(contact?.tel) ? contact.tel : []).find(value => normalizePhone(value)) || '';
    if (!name || !normalizePhone(rawPhone)) {
      notify('В контакте нужны имя и российский номер телефона');
      return;
    }
    $('#newBookingName').value = name;
    $('#newBookingPhone').value = newBookingClientPhoneLabel(rawPhone, String(rawPhone).slice(0, 24));
    newBookingAutoFilledName = '';
    newBookingAutoFilledPhone = '';
    handleNewBookingPhoneInput();
    scheduleNewBookingClientSuggestions(name);
    saveNewBookingDraft();
  } catch (error) {
    if (form === $('#newBookingForm') && error?.name !== 'AbortError') notify(error?.message || 'Не удалось открыть телефонную книгу');
  } finally {
    if (button === $('#newBookingContactPicker')) button.disabled = false;
  }
}

function newBookingClientCandidates(query) {
  const value = String(query || '').trim();
  const textQuery = value.toLocaleLowerCase('ru-RU');
  const phoneQuery = value.replace(/\D/g, '');
  const phoneSearchQueries = new Set();
  if (phoneQuery.length >= 4) {
    phoneSearchQueries.add(phoneQuery);
    if (phoneQuery.startsWith('8')) phoneSearchQueries.add(`7${phoneQuery.slice(1)}`);
    if ((phoneQuery.startsWith('7') || phoneQuery.startsWith('8')) && phoneQuery.length > 4) phoneSearchQueries.add(phoneQuery.slice(1));
  }
  const nameQuery = /[^\d\s()+-]/u.test(value) && textQuery.length >= 2 ? textQuery : '';
  if (!nameQuery && !phoneSearchQueries.size) return [];
  const clients = buildClients();
  const exactPhone = normalizePhone(value);
  const exactClient = exactPhone ? clients.find(client => client.phone === exactPhone) : null;
  if (exactClient) {
    const variants = [];
    const names = new Set();
    const addVariant = rawName => {
      const name = String(rawName || '').trim();
      const key = name.toLocaleLowerCase('ru-RU');
      if (!name || names.has(key)) return;
      names.add(key);
      variants.push({
        phone:exactClient.phone,
        displayPhone:newBookingClientPhoneLabel(exactClient.phone, exactClient.displayPhone),
        name,
        note:String(clientNotes.get(exactClient.phone) || exactClient.imported?.note || '').trim()
      });
    };
    addVariant(exactClient.name);
    [...exactClient.bookings].reverse().forEach(booking => addVariant(booking.client_name));
    addVariant(exactClient.imported?.name);
    return variants.slice(0, 8);
  }
  const rankedClients = clients.map((client, recentIndex) => {
    const clientName = client.name.toLocaleLowerCase('ru-RU');
    let score = Number.POSITIVE_INFINITY;
    if (nameQuery) {
      if (clientName === nameQuery) score = 0;
      else if (clientName.startsWith(nameQuery)) score = 10;
      else if (clientName.includes(nameQuery)) score = 20;
    }
    const clientPhone = String(client.phone || '').replace(/\D/g, '');
    const searchablePhones = new Set([clientPhone]);
    if (clientPhone.length === 11 && clientPhone.startsWith('7')) searchablePhones.add(clientPhone.slice(1));
    phoneSearchQueries.forEach(searchQuery => {
      searchablePhones.forEach(searchablePhone => {
        if (searchablePhone === searchQuery) score = Math.min(score, 0);
        else if (searchablePhone.endsWith(searchQuery)) score = Math.min(score, 4);
        else if (searchablePhone.startsWith(searchQuery)) score = Math.min(score, 8);
        else if (searchablePhone.includes(searchQuery)) score = Math.min(score, 12);
      });
    });
    return { client, recentIndex, score };
  }).filter(item => Number.isFinite(item.score)).sort((left, right) => left.score - right.score || left.recentIndex - right.recentIndex);
  return rankedClients.slice(0, 8).map(({ client }) => ({
    phone:client.phone,
    displayPhone:newBookingClientPhoneLabel(client.phone, client.displayPhone),
    name:client.name,
    note:String(clientNotes.get(client.phone) || client.imported?.note || '').trim()
  }));
}

function hideNewBookingClientSuggestions() {
  const panel = $('#newBookingClientSuggestions');
  if (panel) panel.hidden = true;
}

function renderNewBookingClientSuggestions(query) {
  const panel = $('#newBookingClientSuggestions');
  if (!panel) return;
  const clients = newBookingClientCandidates(query);
  newBookingClientSuggestionMap = new Map(clients.map((client, index) => [String(index), client]));
  if (!clients.length) { panel.hidden = true; panel.innerHTML = ''; return; }
  panel.innerHTML = clients.map((client, index) => `<button type="button" role="option" data-new-booking-client="${index}"><span><strong>${escapeHtml(client.name)}</strong><small>${escapeHtml(client.displayPhone)}</small></span><span aria-hidden="true">Выбрать</span></button>`).join('');
  panel.hidden = false;
}

function scheduleNewBookingClientSuggestions(query) {
  clearTimeout(newBookingClientSuggestionTimer);
  newBookingClientSuggestionTimer = setTimeout(() => renderNewBookingClientSuggestions(query), 60);
}

function restoreNewBookingClientLookupStatus() {
  const fields = $('#newBookingClientFields');
  if (!fields?.dataset.clientLookupState || newBookingMode !== 'client') return;
  delete fields.dataset.clientLookupState;
  $('#newBookingSheetTitle').textContent = newBookingClientBaseTitle;
  $('#newBookingSectionSubtitle').textContent = newBookingClientBaseSubtitle;
}

function applyNewBookingClient(client, { automatic = false } = {}) {
  if (!client) return;
  const nameInput = $('#newBookingName');
  const currentName = nameInput.value.trim();
  const canReplaceName = !currentName || currentName === newBookingAutoFilledName;
  if (automatic && !canReplaceName) return false;
  nameInput.value = client.name;
  $('#newBookingPhone').value = client.displayPhone;
  nameInput.required = true;
  $('#newBookingPhone').required = true;
  newBookingAutoFilledPhone = client.phone;
  newBookingAutoFilledName = client.name;
  const note = $('#newBookingNote');
  if (note && !note.value.trim() && client.note) note.value = client.note;
  $('#newBookingSheetTitle').textContent = 'Повторная запись';
  $('#newBookingSectionSubtitle').textContent = 'Клиент найден в базе';
  $('#newBookingClientFields').dataset.clientLookupState = 'found';
  hideNewBookingClientSuggestions();
  saveNewBookingDraft();
  return true;
}

function selectNewBookingClient(key) {
  applyNewBookingClient(newBookingClientSuggestionMap.get(String(key)));
}

function handleNewBookingPhoneInput() {
  const phoneInput = $('#newBookingPhone');
  const nameInput = $('#newBookingName');
  const phone = normalizePhone(phoneInput.value);
  if (newBookingAutoFilledPhone && phone !== newBookingAutoFilledPhone) {
    if (nameInput.value.trim() === newBookingAutoFilledName) nameInput.value = '';
    newBookingAutoFilledPhone = '';
    newBookingAutoFilledName = '';
    restoreNewBookingClientLookupStatus();
  }
  if (!phone) { restoreNewBookingClientLookupStatus(); scheduleNewBookingClientSuggestions(phoneInput.value); return; }
  const exactClients = newBookingClientCandidates(phoneInput.value).filter(client => client.phone === phone);
  if (exactClients.length === 1 && applyNewBookingClient(exactClients[0], { automatic:true })) return;
  renderNewBookingClientSuggestions(phoneInput.value);
  const fields = $('#newBookingClientFields');
  if (exactClients.length > 1) {
    fields.dataset.clientLookupState = 'multiple';
    $('#newBookingSectionSubtitle').textContent = 'Найдено несколько имён — выберите клиента';
  } else if (exactClients.length === 1) {
    fields.dataset.clientLookupState = 'manual-name';
    $('#newBookingSectionSubtitle').textContent = 'Клиент найден — введённое имя сохранено';
  } else {
    restoreNewBookingClientLookupStatus();
  }
}

function updateNewBookingHeading() {
  const title = $('#newBookingSheetTitle');
  if (!title) return;
  if (newBookingMode === 'block') {
    title.textContent = newBookingPreferredTime
      ? `Занять время · ${bookingDateLabel($('#newBookingDate')?.value || '')}, ${newBookingPreferredTime}`
      : 'Занять время';
    return;
  }
  if ($('#newBookingClientFields')?.dataset.clientLookupState === 'found') {
    title.textContent = 'Повторная запись';
    return;
  }
  title.textContent = newBookingPreferredTime
    ? `Новая запись · ${bookingDateLabel($('#newBookingDate')?.value || '')}, ${newBookingPreferredTime}`
    : 'Новая запись';
}

function setNewBookingMode(mode) {
  const nextMode = !newBookingRepeatVisit && mode === 'block' ? 'block' : 'client';
  const previousMode = newBookingMode;
  if (previousMode === 'client') {
    newBookingModeState.client.serviceId = $('#newBookingService')?.value || newBookingModeState.client.serviceId;
    newBookingModeState.client.durationMinutes = newBookingDurationMinutes() || newBookingModeState.client.durationMinutes;
  } else {
    newBookingModeState.block.durationMinutes = Number($('#newBookingBlockDuration')?.value || newBookingModeState.block.durationMinutes || 60);
  }
  newBookingMode = nextMode;
  $$('[data-new-booking-mode]').forEach(button => {
    const active = button.dataset.newBookingMode === newBookingMode;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
  });
  const block = newBookingMode === 'block';
  if ($('#newBookingForm')) $('#newBookingForm').dataset.mode = newBookingMode;
  if (block) {
    newBookingHistoricalMode = false;
    newBookingClientBaseTitle = 'Новая запись';
    newBookingAutoFilledPhone = '';
    newBookingAutoFilledName = '';
    hideNewBookingClientSuggestions();
  }
  $('#newBookingClientFields').hidden = block;
  $('#newBookingBlockFields').hidden = !block;
  $('#newBookingName').required = !block;
  $('#newBookingPhone').required = !block;
  $('#newBookingBlockTitle').required = false;
  $('#newBookingClientNoteField').hidden = block;
  $('#newBookingBlockNoteField').hidden = !block;
  const locationField = $('#newBookingLocationField');
  if (locationField) locationField.hidden = !block || activeProviderBlockContext($('#newBookingLocation')?.value || '').locations.length <= 1;
  $('#newBookingAdvancedSummary').textContent = block ? 'Заметка и цвет' : newBookingRepeatVisit ? 'Заметка клиента и цвет' : 'Заметка, цвет и серия';
  const recurrence = $('#newBookingRecurrence');
  if (recurrence) recurrence.hidden = block || Boolean(newBookingRepeatVisit);
  updateNewBookingHeading();
  $('#newBookingSectionTitle').textContent = block ? 'Перерыв' : 'Клиент и услуга';
  $('#newBookingSectionSubtitle').textContent = block ? 'Название, длительность и время' : newBookingClientBaseSubtitle;
  $('#newBookingSectionSubtitle').classList.toggle('sr-only', block);
  $('#newBookingServiceCaption').textContent = 'Услуга';
  const serviceSelect = $('#newBookingService');
  const selectedService = newBookingModeState.client.serviceId || serviceSelect.value;
  serviceSelect.innerHTML = serviceOptions(selectedService, true) || '<option value="">Нет активных услуг</option>';
  serviceSelect.closest('label').hidden = block || Boolean(newBookingRepeatVisit);
  serviceSelect.required = !block;
  serviceSelect.disabled = Boolean(newBookingRepeatVisit);
  if (!block && selectedService) serviceSelect.value = selectedService;
  if ($('#newBookingBlockDurationField')) $('#newBookingBlockDurationField').hidden = !block;
  if ($('#newBookingBlockDuration')) $('#newBookingBlockDuration').value = String(newBookingModeState.block.durationMinutes || 60);
  const clientUnavailable = $('#newBookingClientServiceUnavailable');
  if (clientUnavailable) clientUnavailable.hidden = block || ownServices.some(item => item.active);
  updateNewBookingDurationControl();
  updateNewBookingSubmitCaption();
  clearFormError('#newBookingError');
  loadNewBookingSlots();
}

function normalizeRepeatVisitPreview(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const items = Array.isArray(value.items) ? value.items.map(entry => ({
    kind:entry?.kind === 'primary' ? 'primary' : 'addon',
    service_id:String(entry?.service_id || ''),
    title:String(entry?.title || '').trim().slice(0, 120),
    duration_minutes:Math.round(Number(entry?.duration_minutes || 0)),
    price_rub:Math.round(Number(entry?.price_rub || 0)),
    extends_duration:entry?.kind === 'primary' ? true : Boolean(entry?.extends_duration)
  })) : [];
  const materials = Array.isArray(value.materials) ? value.materials.map(entry => ({
    inventory_item_id:String(entry?.inventory_item_id || ''),
    name:String(entry?.name || '').trim().slice(0, 120),
    unit:String(entry?.unit || '').trim().slice(0, 30),
    quantity:Number(entry?.quantity || 0)
  })) : [];
  const primary = items.find(entry => entry.kind === 'primary');
  const duration = Math.round(Number(value.duration_minutes || 0));
  const price = Math.round(Number(value.total_price_rub || 0));
  if (!/^[0-9a-f-]{36}$/i.test(String(value.source_booking_id || ''))
    || !/^[0-9a-f]{64}$/i.test(String(value.source_signature || ''))
    || !primary?.service_id || items.length > 20 || duration < 1 || duration > 480
    || price < 0 || price > 10000000
    || items.some(entry => !entry.title || entry.duration_minutes < 0 || entry.duration_minutes > 480 || entry.price_rub < 0 || entry.price_rub > 1000000)
    || materials.some(entry => !entry.inventory_item_id || !entry.name || !(entry.quantity > 0))) return null;
  return {
    source_booking_id:String(value.source_booking_id),
    source_signature:String(value.source_signature),
    client_name:String(value.client_name || '').trim().slice(0, 80),
    client_phone:String(value.client_phone || '').trim().slice(0, 40),
    primary_service_id:primary.service_id,
    duration_minutes:duration,
    total_price_rub:price,
    comment:String(value.comment || '').trim().slice(0, 1000),
    items,
    materials
  };
}

function repeatVisitPreviewMarkup(repeat) {
  if (!repeat) return '';
  const addonTotal = repeat.items.filter(entry => entry.kind === 'addon').reduce((sum, entry) => sum + entry.price_rub, 0);
  const services = repeat.items.map(entry => `<div class="repeat-visit-row"><span><strong>${escapeHtml(entry.title)}</strong><small>${entry.kind === 'primary' ? 'Основная услуга' : entry.extends_duration ? `Дополнительно · +${entry.duration_minutes} мин` : 'Дополнительно · без увеличения времени'}</small></span><b>${money(entry.price_rub)}</b></div>`).join('');
  const materials = repeat.materials.length
    ? repeat.materials.map(entry => `<li><span>${escapeHtml(entry.name)}</span><b>${escapeHtml(new Intl.NumberFormat('ru-RU', { maximumFractionDigits:3 }).format(entry.quantity))} ${escapeHtml(entry.unit)}</b></li>`).join('')
    : '<li class="repeat-visit-empty">Для услуг не заданы нормы расхода</li>';
  return `<section class="repeat-visit-preview" id="repeatVisitPreview" aria-labelledby="repeatVisitPreviewTitle">
    <div class="repeat-visit-heading"><div><small>Копия исходного визита</small><strong id="repeatVisitPreviewTitle">${repeat.items.length} ${repeat.items.length === 1 ? 'услуга' : repeat.items.length < 5 ? 'услуги' : 'услуг'} · ${repeat.duration_minutes} мин</strong></div><span>Проверим ещё раз при создании</span></div>
    <div class="repeat-visit-services">${services}</div>
    <details class="repeat-visit-materials" ${repeat.materials.length ? 'open' : ''}><summary>Материалы <small>${repeat.materials.length ? `${repeat.materials.length} поз.` : 'нет норм'}</small></summary><ul>${materials}</ul><p>Количество сохранено из исходного визита; остаток проверится при завершении новой записи.</p></details>
    <div class="repeat-visit-fields"><label>Итоговая цена, ₽<input id="repeatVisitTotalPrice" type="number" inputmode="numeric" min="${addonTotal}" max="${Math.min(10000000, addonTotal + 1000000)}" step="1" value="${repeat.total_price_rub}" required></label><label>Комментарий к визиту<textarea id="repeatVisitComment" maxlength="1000" rows="3" placeholder="Комментарий из исходного визита">${escapeHtml(repeat.comment)}</textarea></label></div>
  </section>`;
}

function openNewBookingSheet(preferredTime = '', preset = {}) {
  if (bookingUsesDemoData()) { notify('Демо-записи доступны только для просмотра'); return; }
  delete $('#bookingSheet').dataset.bookingId;
  $('#bookingSheet').dataset.assistantContext = 'new-booking';
  const services = ownServices.filter(item => item.active);
  newBookingRepeatVisit = normalizeRepeatVisitPreview(preset.repeatVisit);
  const draft = preset.clientName ? null : readNewBookingDraft();
  const blockContext = activeProviderBlockContext(draft?.locationId || '');
  const selectedService = services.find(item => item.id === (preset.serviceId || draft?.serviceId)) || services[0];
  const defaultDate = /^\d{4}-\d{2}-\d{2}$/.test(String(selectedDate || '')) ? selectedDate : businessTodayIso();
  const presetDate = /^\d{4}-\d{2}-\d{2}$/.test(String(preset.date || '')) ? preset.date : '';
  const date = presetDate || defaultDate;
  const initialDuration = normalizePerMinuteDuration(preset.durationMinutes || draft?.durationMinutes || serviceDefaultDuration(selectedService?.id), 60);
  const initialHistoricalPaymentMethod = normalizedOutcomePaymentMethod(draft?.historicalPaymentMethod || bookingPolicy.auto_complete_payment_method || 'cash');
  const initialHistoricalAmount = Math.min(1000000, Math.max(0, Math.round(Number(draft?.historicalAmount ?? (Number(selectedService?.duration_minutes) === 1
    ? Number(selectedService?.price_rub || 0) * initialDuration
    : Number(selectedService?.price_rub || 0))))));
  newBookingModeState = {
    client:{ serviceId:selectedService?.id || draft?.serviceId || '', durationMinutes:initialDuration },
    block:{ durationMinutes:Number(draft?.blockDurationMinutes || (draft?.mode === 'block' ? draft?.durationMinutes : 60) || 60) }
  };
  newBookingTime = '';
  newBookingSlots = [];
  newBookingHour = '';
  newBookingPreferredTime = /^\d{2}:\d{2}$/.test(String(preferredTime || '')) ? String(preferredTime) : '';
  const requestedHistorical = Boolean(preset.historical);
  newBookingHistoricalMode = date < businessTodayIso() || (date === businessTodayIso() && requestedHistorical);
  newBookingMode = preset.mode === 'block' || !services.length ? 'block' : 'client';
  newBookingAutoFilledPhone = '';
  newBookingAutoFilledName = '';
  newBookingClientBaseTitle = preset.offlineEdit ? 'Исправить запись' : preset.clientName ? 'Повторная запись' : 'Новая запись';
  newBookingClientBaseSubtitle = preset.offlineEdit ? 'Измените данные и снова отправьте на проверку' : preset.clientName ? 'Клиент и услуга уже выбраны' : 'Имя, номер целиком или последние 4 цифры';
  $('#bookingSheet').classList.add('booking-sheet-wide', 'new-booking-sheet');
  applyClientHighlightClasses($('#bookingSheet'), '', 'booking-sheet-');
  $('#bookingSheetContent').innerHTML = `<small class="booking-sheet-kicker sr-only">${preset.offlineEdit ? 'Отложенная запись' : preset.clientName ? 'Повторный визит' : 'Расписание'}</small><h2 id="bookingSheetTitle"><span id="newBookingSheetTitle">${preset.offlineEdit ? 'Исправить запись' : preset.clientName ? 'Повторная запись' : `Новая запись${newBookingPreferredTime ? ` · ${escapeHtml(bookingDateLabel(date))}, ${escapeHtml(newBookingPreferredTime)}` : ''}`}</span></h2>
    <form class="booking-editor-form new-booking-form" id="newBookingForm">
      <p class="new-booking-readiness" id="newBookingReadiness" role="status" aria-live="polite" hidden></p>
      <div class="new-booking-mode-toggle" id="newBookingModeToggle" role="group" aria-label="Тип записи"><button class="active" type="button" data-new-booking-mode="client" aria-pressed="true">Клиент</button><button type="button" data-new-booking-mode="block" aria-pressed="false">Занять время</button></div>
      <div class="new-booking-layout">
        <section class="new-booking-section"><div class="new-booking-section-title"><div><strong id="newBookingSectionTitle">Клиент и услуга</strong><small id="newBookingSectionSubtitle">Имя, номер целиком или последние 4 цифры</small></div></div>
          <div class="new-booking-client-lookup" id="newBookingClientFields"><div class="booking-client-fields" id="newBookingClientEntry"><label class="new-booking-name-field"><span class="sr-only">Имя клиента</span><input id="newBookingName" maxlength="80" autocomplete="off" aria-autocomplete="list" aria-controls="newBookingClientSuggestions" placeholder="Например, Анна" required></label><label>Телефон<span class="new-booking-phone-control"><input id="newBookingPhone" type="tel" inputmode="tel" autocomplete="off" aria-autocomplete="list" aria-controls="newBookingClientSuggestions" placeholder="+7 (___) ___-__-__" required><span class="new-booking-phone-actions"><button id="newBookingContactPicker" type="button" aria-label="Выбрать из телефонной книги" title="Выбрать из телефонной книги" hidden>${uiIcon('users')}</button><button id="newBookingRecentCalls" type="button" aria-label="Выбрать из недавних входящих звонков" title="Недавние входящие" hidden>${uiIcon('clock')}<span>Звонки</span></button></span></span></label></div><div class="new-booking-client-suggestions" id="newBookingClientSuggestions" role="listbox" aria-label="Найденные клиенты" hidden></div></div>
          <details class="new-booking-block-fields new-booking-block-title" id="newBookingBlockFields" hidden><summary><span id="newBookingBlockTitleSummary">Добавить название</span></summary><label><span class="sr-only">Название перерыва</span><input id="newBookingBlockTitle" maxlength="80" placeholder="Например, обед или личное дело"></label></details>
          <label class="new-booking-service-field"><span class="sr-only" id="newBookingServiceCaption">Услуга</span><select id="newBookingService" required>${serviceOptions(selectedService?.id || '', true)}</select></label>
          <p class="booking-time-warning" id="newBookingClientServiceUnavailable" ${services.length ? 'hidden' : ''}>Для записи клиента сначала добавьте активную услугу. Занять время можно уже сейчас.</p>
          ${repeatVisitPreviewMarkup(newBookingRepeatVisit)}
          <label id="newBookingBlockDurationField" hidden>Длительность<select id="newBookingBlockDuration">${blockDurationChoices(60)}</select></label>
          <div class="new-booking-minute-duration" id="newBookingDurationField" hidden>
            <div class="new-booking-minute-heading"><label for="newBookingDuration">Длительность, минут</label><strong id="newBookingDurationSummary" role="status" aria-live="polite"></strong></div>
            <div class="new-booking-minute-input"><button type="button" data-new-booking-duration-step="-1" aria-label="Уменьшить длительность на минуту">−</button><input id="newBookingDuration" type="number" inputmode="numeric" min="${PER_MINUTE_BOOKING_MIN}" max="${PER_MINUTE_BOOKING_MAX}" step="1" value="${initialDuration}" aria-describedby="newBookingDurationSummary" required><button type="button" data-new-booking-duration-step="1" aria-label="Увеличить длительность на минуту">+</button></div>
            <div class="new-booking-minute-presets" aria-label="Быстрый выбор длительности">${[15,30,45,60].map(value => `<button type="button" data-new-booking-duration="${value}">${value} мин</button>`).join('')}</div>
            <small>Можно указать любое точное время от 1 до 480 минут.</small>
          </div>
          <details class="new-booking-advanced" id="newBookingAdvanced"><summary><span>Дополнительно</span><small class="sr-only" id="newBookingAdvancedSummary">Заметка, цвет и серия</small></summary><div class="new-booking-advanced-content">
            <label id="newBookingClientNoteField"><span class="sr-only">Заметка</span><textarea id="newBookingNote" maxlength="1000" rows="3" placeholder="Пожелания или важная информация — необязательно"></textarea></label>
            <label id="newBookingBlockNoteField" hidden><span class="sr-only">Заметка</span><textarea id="newBookingBlockNote" maxlength="1000" rows="2" placeholder="Например, обед или личное дело"></textarea></label>
            ${compactBookingColorPicker('newBookingColor', BOOKING_COLOR_DEFAULT, '')}
            <section class="new-booking-recurrence" id="newBookingRecurrence">
              <div><strong>Повторение</strong><small id="newBookingRecurrenceHint" hidden>Все окна должны быть свободны, а последний визит — не дальше двух лет.</small></div>
              <label>Количество<select id="newBookingOccurrences"><option value="1">Одна запись</option><option value="2">2 визита</option><option value="3">3 визита</option><option value="4">4 визита</option><option value="6">6 визитов</option><option value="8">8 визитов</option><option value="10">10 визитов</option><option value="12">12 визитов</option><option value="16">16 визитов</option><option value="20">20 визитов</option><option value="24">24 визита</option></select></label>
              <label id="newBookingIntervalField" hidden>Повторять<select id="newBookingInterval"><option value="1">Каждую неделю</option><option value="2">Раз в 2 недели</option><option value="3">Раз в 3 недели</option><option value="4">Раз в 4 недели</option><option value="6">Раз в 6 недель</option><option value="8">Раз в 8 недель</option><option value="12">Раз в 12 недель</option></select></label>
            </section>
          </div></details>
        </section>
        <section class="new-booking-section new-booking-date-time-section" id="newBookingDateTimeSection"><div class="new-booking-section-title"><div><strong>Когда</strong><small class="sr-only" id="newBookingDateTimeSubtitle">${newBookingPreferredTime ? 'Время выбрано в расписании' : 'Выберите свободное окно'}</small></div></div>
          <div class="new-booking-date-time-editor" id="newBookingDateTimeEditor">
            <label id="newBookingLocationField" ${blockContext.locations.length > 1 ? '' : 'hidden'}>Филиал<select id="newBookingLocation">${providerBlockLocationOptions(blockContext.locations, blockContext.locationId)}</select></label>
            <label class="new-booking-date-field"><span class="sr-only">Дата</span><input id="newBookingDate" type="date" value="${date}" required></label>
            <div role="group" aria-labelledby="newBookingTimeCaption"><span class="sr-only" id="newBookingTimeCaption">Свободное время</span><div class="booking-editor-times booking-time-picker" id="newBookingTimes"><span>Ищем свободное время…</span></div></div>
            <section class="new-booking-historical-payment" id="newBookingHistoricalPayment" ${newBookingHistoricalMode ? '' : 'hidden'}>
              <div class="new-booking-historical-payment-title"><strong>Оплата за визит</strong></div>
              <div class="new-booking-historical-payment-fields"><label>Способ оплаты<select id="newBookingHistoricalPaymentMethod"><option value="cash" ${initialHistoricalPaymentMethod === 'cash' ? 'selected' : ''}>Наличные</option><option value="transfer" ${initialHistoricalPaymentMethod === 'transfer' ? 'selected' : ''}>Перевод</option><option value="card" ${initialHistoricalPaymentMethod === 'card' ? 'selected' : ''}>Карта</option><option value="unpaid" ${initialHistoricalPaymentMethod === 'unpaid' ? 'selected' : ''}>Не оплачено</option></select></label><label>Получено, ₽<input id="newBookingHistoricalAmount" type="number" inputmode="numeric" min="0" max="1000000" step="1" value="${initialHistoricalPaymentMethod === 'unpaid' ? 0 : initialHistoricalAmount}" ${initialHistoricalPaymentMethod === 'unpaid' ? 'disabled' : ''} required></label></div>
              <small id="newBookingHistoricalPaymentHint"></small>
            </section>
          </div>
        </section>
      </div>
      <div class="booking-sheet-submit-bar"><p class="form-error" id="newBookingError" role="alert" aria-live="assertive" hidden></p><button class="primary new-booking-submit" id="newBookingSubmit" type="submit">Создать запись</button></div>
    </form>`;
  $('#bookingSheet').hidden = false;
  document.body.classList.add('booking-sheet-open');
  $('#newBookingName').value = String(preset.clientName || draft?.name || '');
  $('#newBookingPhone').value = String(preset.clientPhone || draft?.phone || '');
  $('#newBookingNote').value = String(preset.note || draft?.note || (preset.clientPhone ? clientNotes.get(normalizePhone(preset.clientPhone)) : '') || '');
  const blockTitleDetails = $('#newBookingBlockFields');
  const blockTitleInput = $('#newBookingBlockTitle');
  const blockTitleSummary = $('#newBookingBlockTitleSummary');
  const savedBlockTitle = String(draft?.blockTitle || '').trim();
  blockTitleInput.value = savedBlockTitle === 'Перерыв' ? '' : savedBlockTitle;
  blockTitleDetails.open = Boolean(blockTitleInput.value.trim());
  const updateBlockTitleDisclosure = () => {
    const value = blockTitleInput.value.trim();
    blockTitleSummary.textContent = blockTitleDetails.open ? 'Название перерыва' : value ? `Название: ${value}` : 'Добавить название';
    blockTitleDetails.classList.toggle('has-value', Boolean(value));
  };
  blockTitleInput.addEventListener('input', updateBlockTitleDisclosure);
  blockTitleDetails.addEventListener('toggle', updateBlockTitleDisclosure);
  updateBlockTitleDisclosure();
  $('#newBookingBlockNote').value = String(draft?.blockNote || '');
  $('#newBookingBlockDuration').value = String([15,30,45,60,90,120].includes(Number(newBookingModeState.block.durationMinutes)) ? Number(newBookingModeState.block.durationMinutes) : 60);
  $('#newBookingBlockDuration').addEventListener('change', () => { saveNewBookingDraft(); loadNewBookingSlots(); });
  $('#newBookingLocation')?.addEventListener('change', () => { newBookingTime = ''; saveNewBookingDraft(); loadNewBookingSlots(); });
  $('#newBookingForm').dataset.blockRequestId = /^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(String(draft?.blockRequestId || '')) ? draft.blockRequestId : createOfflineBookingId();
  $('#newBookingOccurrences').value = String(draft?.occurrences || '1');
  $('#newBookingInterval').value = String(draft?.interval || '1');
  const draftColor = $(`[name="newBookingColor"][value="${CSS.escape(String(preset.color || draft?.color || BOOKING_COLOR_DEFAULT))}"]`);
  if (draftColor) draftColor.checked = true;
  if (newBookingRepeatVisit) {
    $('#newBookingModeToggle').hidden = true;
    $('#newBookingService').disabled = true;
    $('#newBookingService').closest('label').hidden = true;
    $('#newBookingRecurrence').hidden = true;
    $('#newBookingAdvancedSummary').textContent = 'Заметка клиента и цвет';
  }
  $('#newBookingContactPicker')?.addEventListener('click', chooseNewBookingContact);
  $('#newBookingRecentCalls')?.addEventListener('click', chooseNewBookingRecentCall);
  refreshNewBookingContactPicker();
  refreshNewBookingRecentCalls();
  $$('[data-new-booking-mode]').forEach(button => button.addEventListener('click', () => { setNewBookingMode(button.dataset.newBookingMode); saveNewBookingDraft(); }));
  $('#newBookingService').addEventListener('change', () => { newBookingTime = ''; updateNewBookingDurationControl({ reset:true }); saveNewBookingDraft(); loadNewBookingSlots(); });
  $('#newBookingDuration').addEventListener('input', () => updateNewBookingDurationControl());
  $('#newBookingDuration').addEventListener('change', () => { updateNewBookingDurationControl(); saveNewBookingDraft(); loadNewBookingSlots(); });
  $$('[data-new-booking-duration]').forEach(button => button.addEventListener('click', () => {
    $('#newBookingDuration').value = button.dataset.newBookingDuration;
    updateNewBookingDurationControl();
    saveNewBookingDraft();
    loadNewBookingSlots();
  }));
  $$('[data-new-booking-duration-step]').forEach(button => button.addEventListener('click', () => {
    $('#newBookingDuration').value = String(normalizePerMinuteDuration(Number($('#newBookingDuration').value || 1) + Number(button.dataset.newBookingDurationStep || 0)));
    updateNewBookingDurationControl();
    saveNewBookingDraft();
    loadNewBookingSlots();
  }));
  $('#newBookingDate').addEventListener('change', () => { newBookingTime = ''; newBookingPreferredTime = ''; newBookingHistoricalMode = $('#newBookingDate').value < businessTodayIso(); updateNewBookingHeading(); saveNewBookingDraft(); updateNewBookingConnectivity(); loadNewBookingSlots(); });
  $('#newBookingHistoricalPaymentMethod').addEventListener('change', () => { updateNewBookingHistoricalPayment(); saveNewBookingDraft(); });
  $('#newBookingHistoricalAmount').addEventListener('input', event => {
    event.currentTarget.dataset.userEdited = 'true';
    event.currentTarget.dataset.paidAmount = event.currentTarget.value;
    updateNewBookingSubmitCaption();
    saveNewBookingDraft();
  });
  $('#newBookingOccurrences').addEventListener('change', () => { updateNewBookingSubmitCaption(); saveNewBookingDraft(); });
  $('#newBookingForm').addEventListener('submit', createNewBooking);
  $('#newBookingForm').addEventListener('input', saveNewBookingDraft);
  $('#newBookingForm').addEventListener('change', saveNewBookingDraft);
  const newBookingNameInput = $('#newBookingName');
  const newBookingPhoneInput = $('#newBookingPhone');
  newBookingNameInput.addEventListener('input', () => {
    if (newBookingNameInput.value.trim() !== newBookingAutoFilledName) {
      newBookingAutoFilledPhone = '';
      newBookingAutoFilledName = '';
      const phone = normalizePhone(newBookingPhoneInput.value);
      const knownPhone = phone && newBookingClientCandidates(newBookingPhoneInput.value).some(client => client.phone === phone);
      if (knownPhone) {
        $('#newBookingClientFields').dataset.clientLookupState = 'manual-name';
        $('#newBookingSectionSubtitle').textContent = 'Клиент найден — введённое имя сохранено';
      } else {
        restoreNewBookingClientLookupStatus();
      }
    }
    scheduleNewBookingClientSuggestions(newBookingNameInput.value);
  });
  newBookingPhoneInput.addEventListener('input', handleNewBookingPhoneInput);
  [newBookingNameInput, newBookingPhoneInput].forEach(input => {
    input.addEventListener('focus', () => scheduleNewBookingClientSuggestions(input.value));
    input.addEventListener('keydown', event => {
      if (event.key === 'Escape') hideNewBookingClientSuggestions();
      if (event.key === 'ArrowDown') { const first = $('#newBookingClientSuggestions button'); if (first) { event.preventDefault(); first.focus(); } }
    });
    input.addEventListener('blur', () => setTimeout(() => {
      if (document.activeElement !== newBookingNameInput && document.activeElement !== newBookingPhoneInput) hideNewBookingClientSuggestions();
    }, 120));
  });
  $('#newBookingClientSuggestions').addEventListener('pointerdown', event => event.preventDefault());
  $('#newBookingClientSuggestions').addEventListener('click', event => {
    const button = event.target.closest('[data-new-booking-client]');
    if (button) selectNewBookingClient(button.dataset.newBookingClient);
  });
  setNewBookingMode(newBookingMode);
  updateNewBookingDurationControl();
  updateNewBookingConnectivity();
  if (preset.clientName) {
    $('#newBookingSheetTitle').textContent = preset.offlineEdit ? 'Исправить запись' : 'Повторная запись';
    $('#newBookingSectionSubtitle').textContent = preset.offlineEdit ? 'Измените данные и снова отправьте на проверку' : 'Клиент и услуга уже выбраны';
  }
  setTimeout(() => {
    const target = preset.clientName
      ? (newBookingPreferredTime ? $('#newBookingService') : $('#newBookingDate'))
      : $('#newBookingName');
    target?.focus();
  }, 0);
}

async function openRepeatBookingFromSheet(id) {
  if (!requireBookingWrites()) return;
  const item = allBookings.find(booking => booking.id === id);
  if (!item || isScheduleBlock(item)) return;
  if (!navigator.onLine) {
    notify('Для полного повтора нужно подключение: перед созданием проверим услуги, материалы и цену.');
    return;
  }
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  const organizationId = activeClientOrganizationId;
  await loadOwnServices({ silent:true });
  if (!sessionIsCurrent(userId, generation) || activeClientOrganizationId !== organizationId) return;
  const { data, error } = await db.rpc('get_provider_repeat_visit_v164', { p_booking:id });
  if (!sessionIsCurrent(userId, generation) || activeClientOrganizationId !== organizationId) return;
  if (error) {
    const reason = String(error.message || '');
    notify(reason.includes('repeat_service_unavailable')
      ? 'Одна из услуг исходного визита отключена. Обновите состав и повторите.'
      : reason.includes('repeat_material_unavailable')
        ? 'Один из материалов исходного визита больше недоступен. Обновите нормы расхода.'
        : /get_provider_repeat_visit_v164|schema cache|could not find/i.test(reason)
          ? 'Полный повтор визита ещё не установлен на сервере.'
          : 'Не удалось заново проверить исходный визит. Обновите журнал и повторите.');
    return;
  }
  const repeatVisit = normalizeRepeatVisitPreview(data);
  if (!repeatVisit) {
    notify('Сервер вернул неполный состав визита. Запись не создавалась.');
    return;
  }
  if (!ownServices.some(service => service.id === repeatVisit.primary_service_id && service.active)) {
    notify('Основная услуга исходного визита больше недоступна. Обновите состав и повторите.');
    return;
  }
  openNewBookingSheet('', {
    clientName:repeatVisit.client_name || item.client_name,
    clientPhone:repeatVisit.client_phone || item.client_phone,
    serviceId:repeatVisit.primary_service_id,
    durationMinutes:repeatVisit.duration_minutes,
    repeatVisit
  });
}

function bookingIdFromRpcResult(value) {
  if (Array.isArray(value)) return bookingIdFromRpcResult(value[0]);
  if (value && typeof value === 'object') return String(value.booking_id || value.id || '');
  const candidate = String(value || '');
  return /^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(candidate) ? candidate : '';
}

function bookingCodeFromRpcResult(value) {
  if (Array.isArray(value)) return bookingCodeFromRpcResult(value[0]);
  if (value && typeof value === 'object') return String(value.booking_code || '');
  return /^MIN-[0-9A-F]{8,12}$/i.test(String(value || '')) ? String(value) : '';
}

function createdBookingMatches(item, { id = '', bookingCode = '', service, date, time, phone }) {
  return Boolean(item)
    && item.status !== 'cancelled'
    && (!id || item.id === id)
    && (!bookingCode || item.booking_code === bookingCode)
    && (!service || item.service_id === service)
    && item.booking_date === date
    && String(item.booking_time).slice(0, 5) === time
    && normalizePhone(item.client_phone) === normalizePhone(phone);
}

function findCreatedBooking(criteria) {
  return [...allBookings].reverse().find(item => createdBookingMatches(item, criteria)) || null;
}

async function loadCreatedBookingDirect(criteria) {
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  if (!userId || !navigator.onLine) return null;
  let query = db.from('bookings')
    .select('id,organization_id,location_id,booking_code,request_id,service_id,series_id,series_occurrence,client_name,client_phone,booking_date,booking_time,duration_minutes,original_price_rub,total_price_rub,status,created_at,reschedule_count,deposit_amount_rub,payment_status,payment_url,booking_source,created_by_user_id,created_by_role,services(name,price_rub,duration_minutes)')
    .eq('performer_id', userId)
    .eq('booking_date', criteria.date)
    .eq('booking_time', `${criteria.time}:00`)
    .order('created_at', { ascending:false })
    .limit(5);
  query = criteria.id
    ? query.eq('id', criteria.id)
    : criteria.bookingCode
      ? query.eq('booking_code', criteria.bookingCode)
      : query.eq('service_id', criteria.service);
  const { data, error } = await query;
  if (error || !sessionIsCurrent(userId, generation)) return null;
  const item = (data || []).find(candidate => createdBookingMatches(candidate, criteria));
  if (!item) return null;
  const index = allBookings.findIndex(candidate => candidate.id === item.id);
  if (index >= 0) allBookings[index] = item;
  else allBookings = [...allBookings, item].sort((a, b) => `${a.booking_date}${a.booking_time}${a.id}`.localeCompare(`${b.booking_date}${b.booking_time}${b.id}`));
  renderBookingData();
  void saveProviderCache('bookings', allBookings, userId);
  return item;
}

async function ensureCreatedBookingVisible(criteria) {
  let created = findCreatedBooking(criteria);
  if (created) return created;
  for (let attempt = 0; attempt < 2; attempt += 1) {
    if (attempt) await new Promise(resolve => setTimeout(resolve, 250));
    created = await loadCreatedBookingDirect(criteria);
    if (created) return created;
  }
  return null;
}

async function createNewBooking(event) {
  event.preventDefault();
  const submittedForm = event.currentTarget || $('#newBookingForm');
  if (submittedForm?.dataset.historicalCreateState) return;
  if (submittedForm?.dataset.creationUncertain) {
    showFormError('#newBookingError', 'Проверьте созданные записи в журнале. Для следующей записи откройте новую форму.');
    return;
  }
  if (!requireBookingWrites()) return;
  const userId = currentUser.id;
  const generation = sessionGeneration;
  const repeatVisit = newBookingRepeatVisit;
  const block = newBookingMode === 'block';
  const name = block ? ($('#newBookingBlockTitle').value.trim() || 'Перерыв') : $('#newBookingName').value.trim();
  const phone = block ? SCHEDULE_BLOCK_PHONE : $('#newBookingPhone').value.trim();
  const service = $('#newBookingService').value;
  const serviceModel = ownServices.find(item => item.id === service && item.active);
  const durationMinutes = newBookingDurationMinutes();
  const date = $('#newBookingDate').value;
  const color = $('[name="newBookingColor"]:checked')?.value || BOOKING_COLOR_DEFAULT;
  const occurrenceCount = block ? 1 : Math.max(1, Number($('#newBookingOccurrences')?.value || 1));
  const intervalWeeks = Math.max(1, Number($('#newBookingInterval')?.value || 1));
  const selectedButtonTime = $('[data-new-booking-time].active')?.dataset.newBookingTime || '';
  newBookingTime = newBookingTime || selectedButtonTime;
  const historical = newBookingHistoricalMode || date < businessTodayIso() || (date === businessTodayIso() && newBookingTime && new Date(`${date}T${newBookingTime}:00`) < new Date());
  const historicalPaymentMethod = ['cash','transfer','card','unpaid'].includes($('#newBookingHistoricalPaymentMethod')?.value)
    ? $('#newBookingHistoricalPaymentMethod').value
    : 'cash';
  const historicalAmountValue = $('#newBookingHistoricalAmount')?.value ?? '';
  const historicalAmount = historicalPaymentMethod === 'unpaid' ? 0 : historicalAmountValue === '' ? Number.NaN : Math.round(Number(historicalAmountValue));
  const repeatTotalPrice = repeatVisit ? Math.round(Number($('#repeatVisitTotalPrice')?.value)) : 0;
  const repeatComment = repeatVisit ? String($('#repeatVisitComment')?.value || '').trim() : '';
  const repeatAddonTotal = repeatVisit ? repeatVisit.items.filter(entry => entry.kind === 'addon').reduce((sum, entry) => sum + entry.price_rub, 0) : 0;
  if (historical && (submittedForm !== $('#newBookingForm') || $('#bookingSheet').hidden)) return;
  const validationError = name.length < 2
    ? (block ? 'Укажите название перерыва.' : 'Укажите имя клиента.')
    : (!block && normalizePhone(phone).length < 10)
      ? 'Укажите полный номер телефона.'
      : (!block && !service)
        ? 'Выберите услугу.'
        : !durationMinutes
          ? 'Укажите длительность записи.'
        : !date
          ? 'Выберите дату.'
          : !newBookingTime
            ? 'Выберите время записи.'
            : !historical && !isNewBookingGridTime(newBookingTime)
              ? 'Выберите начало получасового интервала.'
            : historical && (!Number.isInteger(historicalAmount) || historicalAmount < 0 || historicalAmount > 1000000)
              ? 'Укажите полученную сумму от 0 до 1 000 000 ₽.'
            : repeatVisit && (!Number.isInteger(repeatTotalPrice) || repeatTotalPrice < repeatAddonTotal || repeatTotalPrice > Math.min(10000000, repeatAddonTotal + 1000000))
              ? `Укажите итоговую цену от ${money(repeatAddonTotal)} до ${money(Math.min(10000000, repeatAddonTotal + 1000000))}.`
            : '';
  if (validationError) {
    showFormError('#newBookingError', validationError);
    return;
  }
  if (historical && block) {
    showFormError('#newBookingError', 'В прошлом можно добавить только фактический визит клиента, но не блокировку времени.');
    return;
  }
  if (historical && occurrenceCount > 1) {
    showFormError('#newBookingError', 'В прошлом записи добавляются по одной, чтобы не создать лишние визиты.');
    return;
  }
  if (historical && !navigator.onLine) {
    showFormError('#newBookingError', 'Для записи в прошлом нужен интернет: сервер должен проверить права и пересечения.');
    return;
  }
  const serverConfirmedCurrentSlot = !historical && !block && newBookingSlots.includes(newBookingTime);
  const placementIssue = serverConfirmedCurrentSlot ? '' : bookingPlacementIssue(
    { id:'new-booking-validation', duration_minutes:durationMinutes, client_phone:phone },
    date,
    minutesFromTime(newBookingTime),
    historical ? { allowPast:true, ignoreSchedule:true } : { respectAutomaticBreakReleases:true }
  );
  if (placementIssue) {
    showFormError('#newBookingError', `${placementIssue}. Выберите другое время или длительность.`);
    await loadNewBookingSlots();
    return;
  }
  if (occurrenceCount > 1) {
    const lastOccurrence = parseLocalIsoDate(date);
    const seriesLimit = parseLocalIsoDate(businessTodayIso());
    lastOccurrence.setDate(lastOccurrence.getDate() + ((occurrenceCount - 1) * intervalWeeks * 7));
    seriesLimit.setDate(seriesLimit.getDate() + 730);
    if (lastOccurrence > seriesLimit) {
      showFormError('#newBookingError', 'Уменьшите количество или интервал: последний визит должен быть не дальше двух лет.');
      return;
    }
  }
  const button = event.submitter || $('#newBookingSubmit');
  if (!button) return;
  button.disabled = true;
  button.textContent = editingOfflineBookingId ? 'Сохраняем…' : block ? 'Занимаем…' : 'Создаём…';
  const note = block ? ($('#newBookingBlockNote')?.value.trim() || '') : $('#newBookingNote').value.trim();
  const unresolvedProviderAttempt = readProviderBookingAttempt(userId);
  if (unresolvedProviderAttempt && (editingOfflineBookingId || !navigator.onLine || historical || occurrenceCount > 1 || block)) {
    button.disabled = false;
    updateNewBookingSubmitCaption();
    showFormError('#newBookingError', unresolvedProviderAttempt.legacyUncertain
      ? 'Предыдущий ответ сервера не подтверждён. Сначала подключитесь и проверьте журнал: автоматически повторять старый запрос небезопасно.'
      : 'Сначала подключитесь и завершите восстановление предыдущей записи с теми же данными. После этого откройте новую форму.');
    return;
  }
  if (editingOfflineBookingId) {
    const queued = await queueOfflineBooking({ clientName:name, clientPhone:phone, serviceId:service, serviceName:serviceModel?.name, durationMinutes, date, time:newBookingTime, note, color });
    button.disabled = false;
    updateNewBookingSubmitCaption();
    if (!queued.ok) {
      showFormError('#newBookingError', queued.duplicate ? 'Такая запись уже есть в очереди. Выберите другое время или удалите лишнюю карточку.' : 'Не удалось надёжно сохранить исправление. Данные остались в форме — попробуйте ещё раз.');
      return;
    }
    clearNewBookingDraft(userId);
    closeBookingSheet();
    renderOfflineBookingQueue();
    notify(navigator.onLine ? 'Исправление сохранено · проверяем запись на сервере' : 'Исправление сохранено на устройстве · проверим после подключения');
    if (navigator.onLine) {
      await synchronizeProvider();
      if (bookingCreationReady) await flushOfflineBookings();
    }
    return;
  }
  if (!navigator.onLine) {
    if (block || occurrenceCount > 1) {
      button.disabled = false;
      updateNewBookingSubmitCaption();
      showFormError('#newBookingError', block ? 'Без интернета можно отложить только запись клиента, но не блокировку времени.' : 'Без интернета можно отложить одну запись. Серии создаются после подключения.');
      return;
    }
    const queued = await queueOfflineBooking({ clientName:name, clientPhone:phone, serviceId:service, serviceName:serviceModel?.name, durationMinutes, date, time:newBookingTime, note, color });
    button.disabled = false;
    updateNewBookingSubmitCaption();
    if (!queued.ok) {
      showFormError('#newBookingError', 'Не удалось надёжно сохранить запись на устройстве. Не закрывайте форму и попробуйте ещё раз.');
      return;
    }
    clearNewBookingDraft(userId);
    closeBookingSheet();
    renderOfflineBookingQueue();
    recordConnectionEvent('offline', `Запись на ${date} ${newBookingTime} сохранена до подключения`);
    notify(queued.duplicate ? 'Такая запись уже ожидает подключения' : 'Запись сохранена на устройстве · при подключении проверим время и создадим её');
    return;
  }
  if (historical) {
    const form = $('#newBookingForm');
    const formRevision = bookingEditorRevision;
    const contextIsCurrent = captureBookingMetadataContext();
    const formIsCurrent = () => contextIsCurrent() && bookingEditorRevision === formRevision
      && form === $('#newBookingForm') && !$('#bookingSheet').hidden;
    if (!formIsCurrent() || (event.currentTarget && event.currentTarget !== form)) return;
    let closedIsCurrent = null;
    let createdId = '';
    const organizationId = organizationController?.getActiveOrganization?.()?.id || '';
    if (!organizationId) {
      button.disabled = false;
      updateNewBookingSubmitCaption();
      showFormError('#newBookingError', 'Не удалось определить организацию. Обновите страницу и попробуйте ещё раз.');
      return;
    }
    form.dataset.historicalCreateState = 'pending';
    try {
      const { data, error } = await db.rpc('create_minuta_historical_booking', {
        p_organization:organizationId,
        p_service:service,
        p_date:date,
        p_time:`${newBookingTime}:00`,
        p_duration_minutes:durationMinutes,
        p_client_name:name,
        p_client_phone:phone,
        p_payment_method:historicalPaymentMethod,
        p_amount_rub:historicalAmount
      });
      if (!formIsCurrent()) return;
      if (error) {
        // Exact v98 SQL refusals abort this invocation. Transport text and
        // malformed acknowledgements do not prove that no row was committed.
        const refusals = {
          '42501':['authentication_required', 'organization_access_denied', 'historical_booking_denied'],
          '22023':['invalid_historical_booking', 'invalid_client_data', 'invalid_historical_time', 'service_unavailable',
            'invalid_service_terms', 'historical_duration_required', 'fixed_service_duration_mismatch',
            'invalid_historical_price', 'invalid_historical_payment', 'invalid_location_timezone', 'invalid_historical_duration', 'historical_time_required'],
          'P0001':['booking_location_unavailable'],
          '23P01':['slot_unavailable']
        };
        if (!refusals[String(error.code || '')]?.includes(String(error.message || ''))) {
          form.dataset.historicalCreateState = 'unknown';
          showFormError('#newBookingError', 'Не удалось подтвердить создание записи в прошлом. Проверьте расписание перед повтором.');
          return;
        }
        delete form.dataset.historicalCreateState;
        button.disabled = false;
        updateNewBookingSubmitCaption();
        const reason = String(error.message || '');
        const message = /slot_unavailable|overlap|conflict|exclude/i.test(reason)
          ? 'Это время пересекается с другой записью. Выберите другое.'
          : /historical_booking_denied|service_unavailable|organization_access_denied/i.test(reason)
            ? 'Недостаточно прав для добавления этой записи.'
          : /historical_time_required/i.test(reason)
            ? 'Выбранное время ещё не прошло. Для будущей записи выберите свободное окно.'
            : /invalid_client_data/i.test(reason)
              ? 'Проверьте имя и номер телефона клиента.'
              : /invalid_historical_booking/i.test(reason)
                ? 'Проверьте выбранные услугу, дату и время.'
                : /invalid_historical_payment/i.test(reason)
                  ? 'Проверьте способ оплаты и полученную сумму.'
                : /invalid_historical_duration|invalid_historical_price|invalid_historical_terms/i.test(reason)
                  ? 'Проверьте длительность и рассчитанную стоимость записи.'
                  : /booking_location_unavailable/i.test(reason)
                    ? 'Не найден активный филиал. Настройте филиал организации и повторите попытку.'
                    : /authentication_required|jwt|session/i.test(reason)
                      ? 'Сессия завершилась. Войдите снова и повторите попытку.'
            : /create_minuta_historical_booking|schema cache|could not find/i.test(reason)
                        ? 'Сервер пока не поддерживает создание записей в прошлом. Обновите страницу или обратитесь к администратору.'
                        : 'Не удалось создать запись в прошлом. Данные сохранены в форме, попробуйте ещё раз.';
        showFormError('#newBookingError', message);
        return;
      }
      const validAcknowledgement = data && typeof data === 'object'
        && typeof data.booking_id === 'string' && typeof data.booking_code === 'string'
        && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(data.booking_id)
        && /^MIN-[0-9A-F]{10}$/.test(data.booking_code)
        && Number.isInteger(data.duration_minutes) && data.duration_minutes >= 1 && data.duration_minutes <= 480
        && Number.isInteger(data.unit_price_rub) && data.unit_price_rub >= 0 && data.unit_price_rub <= 1000000
        && Number.isInteger(data.total_price_rub) && data.total_price_rub >= 0 && data.total_price_rub <= 10000000
        && data.payment_required === false && data.notifications_suppressed === true
        && data.visit_status === 'completed' && data.payment_method === historicalPaymentMethod
        && Number.isInteger(data.amount_rub) && data.amount_rub === historicalAmount
        && Number.isInteger(data.calculated_amount_rub) && data.calculated_amount_rub === data.total_price_rub;
      if (!validAcknowledgement) {
        form.dataset.historicalCreateState = 'unknown';
        showFormError('#newBookingError', 'Сервер не вернул созданную запись. Обновите расписание и проверьте результат.');
        return;
      }
      createdId = data.booking_id;
      form.dataset.historicalCreateState = 'created';
      const normalizedPhone = normalizePhone(phone);
      if (note) {
        const noteSaved = await saveClientNoteValue(normalizedPhone, note, { isCurrent:formIsCurrent, optimistic:false });
        if (!formIsCurrent()) return;
        if (!noteSaved) {
          showFormError('#newBookingError', 'Запись в прошлом создана, но сохранение заметки не подтверждено. Проверьте запись перед повтором.');
          return;
        }
      }
      const colorSaved = await saveBookingColor(createdId, color, { rerender:false, isCurrent:formIsCurrent });
      if (!formIsCurrent()) return;
      if (!colorSaved) {
        showFormError('#newBookingError', 'Запись в прошлом создана, но сохранение цвета не подтверждено. Проверьте запись перед повтором.');
        return;
      }
      selectScheduleDate(date);
      clearNewBookingDraft(userId);
      closeBookingSheet();
      const closedRevision = bookingEditorRevision;
      closedIsCurrent = () => contextIsCurrent() && bookingEditorRevision === closedRevision && $('#bookingSheet').hidden;
      const refreshed = await refreshAfterWrite();
      if (!closedIsCurrent()) return;
      if (refreshed === false) {
        notify('Запись в прошлом создана, но обновление расписания не подтверждено. Проверьте запись перед повтором.');
        return;
      }
      focusCreatedBooking(createdId);
      notify(historicalPaymentMethod === 'unpaid'
        ? 'Прошедший визит добавлен · отмечен как неоплаченный'
        : `Прошедший визит добавлен · ${money(historicalAmount)} учтено в статистике`);
    } catch {
      if (!(closedIsCurrent ? closedIsCurrent() : formIsCurrent())) return;
      if (!createdId) form.dataset.historicalCreateState = 'unknown';
      const message = createdId
        ? 'Запись в прошлом создана, но завершение обновления не подтверждено. Проверьте запись перед повтором.'
        : 'Не удалось подтвердить создание записи в прошлом. Проверьте расписание перед повтором.';
      if (closedIsCurrent) notify(message);
      else showFormError('#newBookingError', message);
    } finally {
      if (formIsCurrent()) {
        updateNewBookingSubmitCaption();
      }
    }
    return;
  }
  if (occurrenceCount > 1) {
    const { data, error } = await db.rpc('create_minuta_recurring_bookings', {
      p_service: service,
      p_start_date: date,
      p_time: `${newBookingTime}:00`,
      p_client_name: name,
      p_client_phone: phone,
      p_occurrence_count: occurrenceCount,
      p_interval_weeks: intervalWeeks
    });
    if (!sessionIsCurrent(userId, generation)) return;
    if (error) {
      button.disabled = false;
      button.textContent = `Создать серию из ${occurrenceCount}`;
      const reason = String(error.message || '');
      const connectionError = !navigator.onLine || /failed to fetch|network|load failed|timed? out|fetch/i.test(reason);
      if (connectionError) recordConnectionEvent('error', 'Создание серии: связь прервалась');
      const message = connectionError
        ? 'Связь прервалась. Данные остались в форме — подключитесь и нажмите «Создать» ещё раз.'
      : reason.includes('series_slot_unavailable') || reason.includes('slot_unavailable') || reason.includes('booking_buffer_conflict')
        ? 'Одно из времён серии занято записью или автоматическим перерывом. Измените дату, время или интервал.'
        : reason.includes('invalid_recurring_booking')
          ? 'Проверьте количество и интервал: последний визит должен быть не дальше двух лет.'
        : /create_minuta_recurring_bookings|schema cache|could not find/i.test(reason)
          ? 'Серии записей пока не установлены. Сначала примените миграцию v79.'
          : 'Не удалось создать серию. Ни одна запись не была добавлена.';
      showFormError('#newBookingError', message);
      return;
    }
    const normalizedPhone = normalizePhone(phone);
    if (note) {
      await saveClientNoteValue(normalizedPhone, note, { isCurrent:() => sessionIsCurrent(userId, generation) });
      if (!sessionIsCurrent(userId, generation)) return;
    }
    const created = Array.isArray(data?.created) ? data.created : [];
    const createdIds = created.map(entry => entry.booking_id).filter(Boolean);
    const adjusted = await applyPerMinuteBookingTerms(createdIds, serviceModel, durationMinutes);
    if (!adjusted.ok) {
      const rollback = await rollbackCreatedBookings(createdIds);
      button.disabled = false;
      button.textContent = `Создать серию из ${occurrenceCount}`;
      if (!rollback.ok) submittedForm.dataset.creationUncertain = 'true';
      showFormError('#newBookingError', rollback.ok ? 'Для выбранной длительности одно из окон уже занято. Созданные записи удалены — выберите другое время или длительность.' : 'Не удалось подтвердить удаление всех записей серии. Проверьте журнал перед повторным созданием.');
      await loadNewBookingSlots();
      return;
    }
    await Promise.all(created.map(entry => db.rpc('set_booking_color', { p_booking:entry.booking_id, p_color:color })));
    selectScheduleDate(date);
    clearNewBookingDraft(userId);
    closeBookingSheet();
    await refreshAfterWrite();
    if (created[0]?.booking_id) focusCreatedBooking(created[0].booking_id);
    notify(`Серия из ${occurrenceCount} записей создана`);
    return;
  }
  let bookingRpcResult = null;
  let providerAttempt = null;
  let error = null;
  if (block) {
    const context = activeProviderBlockContext($('#newBookingLocation')?.value || '');
    if (!context.organizationId || !context.locationId) {
      button.disabled = false;
      updateNewBookingSubmitCaption();
      showFormError('#newBookingError', 'Не найден активный филиал. Настройте его в разделе «Организация».');
      return;
    }
    const requestId = submittedForm.dataset.blockRequestId || createOfflineBookingId();
    submittedForm.dataset.blockRequestId = requestId;
    const payload = JSON.stringify({ organization:context.organizationId, location:context.locationId, date, time:newBookingTime, durationMinutes, name, note });
    if (submittedForm.dataset.blockRequestPayload && submittedForm.dataset.blockRequestPayload !== payload) {
      button.disabled = false;
      updateNewBookingSubmitCaption();
      showFormError('#newBookingError', 'После неопределённого ответа данные изменились. Проверьте журнал и откройте новую форму, чтобы не создать лишний перерыв.');
      return;
    }
    submittedForm.dataset.blockRequestPayload = payload;
    ({ data:bookingRpcResult, error } = await db.rpc('create_provider_block_v141', {
      p_organization:context.organizationId,
      p_location:context.locationId,
      p_date:date,
      p_time:`${newBookingTime}:00`,
      p_duration:durationMinutes,
      p_request_id:requestId,
      p_title:name,
      p_note:note
    }));
    if (!sessionIsCurrent(userId, generation)) return;
    const confirmed = !error && bookingRpcResult?.booking_id === requestId
      && Number(bookingRpcResult?.duration_minutes) === durationMinutes
      && bookingRpcResult?.payment_required === false
      && bookingRpcResult?.notifications_suppressed === true;
    if (!error && !confirmed) {
      submittedForm.dataset.creationUncertain = 'true';
      button.disabled = false;
      updateNewBookingSubmitCaption();
      showFormError('#newBookingError', 'Время могло быть занято, но ответ сервера неполный. Проверьте журнал перед повтором.');
      return;
    }
  } else {
    const write = await submitProviderBookingAttempt({
      surface:repeatVisit ? 'repeat-booking' : 'new-booking', service, date, time:newBookingTime, name, phone,
      durationMinutes, note, color,
      repeatSourceId:repeatVisit?.source_booking_id || '',
      repeatSourceSignature:repeatVisit?.source_signature || '',
      repeatTotalPrice,
      repeatComment
    });
    if (!sessionIsCurrent(userId, generation)) return;
    const recoveredLegacyBooking = !write.ok && write.legacyUncertain
      ? findCreatedBooking({ service, date, time:newBookingTime, phone })
        || await ensureCreatedBookingVisible({ service, date, time:newBookingTime, phone })
      : null;
    if (!sessionIsCurrent(userId, generation)) return;
    if (!write.ok && !write.definite && !recoveredLegacyBooking) {
      button.disabled = false;
      updateNewBookingSubmitCaption();
      if (write.busy) {
        showFormError('#newBookingError', 'Запрос уже отправляется. Дождитесь ответа сервера.');
      } else if (write.storageUnavailable) {
        showFormError('#newBookingError', 'Не удалось сохранить защитный номер запроса на устройстве. Запись не отправлена или её результат не подтверждён — обновите журнал перед повтором.');
      } else if (write.conflict) {
        showFormError('#newBookingError', 'Данные изменились после неподтверждённой попытки. Верните прежние данные и повторите для безопасного восстановления либо сначала проверьте журнал.');
      } else if (write.legacyUncertain) {
        showFormError('#newBookingError', 'Старая версия сервера могла создать запись, но ответ потерян. Автоматический повтор отключён: проверьте журнал перед новой записью.');
      } else if (write.stale) {
        showFormError('#newBookingError', 'Сессия изменилась во время запроса. Обновите журнал перед повтором.');
      } else {
        recordConnectionEvent('warning', 'Создание записи: ответ не подтверждён');
        showFormError('#newBookingError', 'Ответ сервера не подтверждён. Данные сохранены: повторите без изменений — будет использован тот же защитный номер запроса.');
      }
      return;
    }
    bookingRpcResult = recoveredLegacyBooking
      ? { booking_id:recoveredLegacyBooking.id, booking_code:recoveredLegacyBooking.booking_code }
      : write.data;
    providerAttempt = write.attempt;
    error = recoveredLegacyBooking ? null : write.error || null;
  }
  if (error) {
    button.disabled = false;
    button.textContent = block ? 'Занять время' : 'Создать запись';
    const reason = String(error.message || '');
    const connectionError = !navigator.onLine || /failed to fetch|network|load failed|timed? out|fetch/i.test(reason);
    if (connectionError) recordConnectionEvent('error', 'Создание записи: связь прервалась');
    if (!connectionError) delete submittedForm.dataset.blockRequestPayload;
    const message = connectionError
      ? (block ? 'Связь прервалась. Данные сохранены в форме: повторите попытку без изменений — сервер не создаст второй перерыв.' : 'Связь прервалась: создание не подтверждено. Данные остались в форме. Подключитесь и проверьте журнал перед повторным созданием.')
      : block && /create_provider_block_v141|schema cache|could not find|does not exist/i.test(reason)
        ? 'Обновление безопасного занятия времени ещё не установлено. Обновите страницу через несколько минут.'
      : block && reason.includes('block_request_conflict')
        ? 'Параметры изменились после предыдущей попытки. Проверьте журнал и откройте новую форму.'
      : block && reason.includes('block_schedule_changed')
        ? 'Расписание изменяется в другой вкладке. Обновите журнал и повторите попытку.'
      : reason.includes('slot_unavailable') || reason.includes('booking_buffer_conflict')
      ? (reason.includes('booking_buffer_conflict') ? 'Это время попадает в перерыв до или после другой записи. Выберите другое.' : 'Это время уже занято. Выберите другое.')
      : reason.includes('repeat_source_changed')
        ? 'Исходный визит изменился. Закройте форму и снова нажмите «Повторить запись», чтобы увидеть свежий состав.'
      : reason.includes('repeat_service_unavailable')
        ? 'Одна из услуг исходного визита отключена или удалена. Обновите состав исходного визита перед повтором.'
      : reason.includes('repeat_material_unavailable')
        ? 'Один из материалов исходного визита больше недоступен. Обновите нормы расхода и повторите.'
      : reason.includes('invalid_repeat_price')
        ? 'Итоговая цена не соответствует составу визита. Проверьте сумму и повторите.'
      : /provider_repeat_appointment_v164|schema cache|could not find/i.test(reason)
        ? 'Сервер пока не поддерживает полный повтор визита. Обновите страницу или обратитесь к администратору.'
      : reason.includes('service_unavailable')
        ? 'Услуга недоступна для записи. Обновите список услуг.'
        : reason.includes('invalid_client_data')
        ? (block ? 'Не удалось занять время.' : 'Проверьте имя и номер телефона клиента.')
          : 'Не удалось создать запись. Обновите страницу и попробуйте ещё раз.';
    if (!connectionError) await loadNewBookingSlots();
    showFormError('#newBookingError', message);
    return;
  }
  const createdCriteria = {
    id:bookingIdFromRpcResult(bookingRpcResult),
    bookingCode:bookingCodeFromRpcResult(bookingRpcResult),
    service:block ? '' : service,
    date,
    time:newBookingTime,
    phone
  };
  let createdBooking = null;
  if (!block) {
    createdBooking = findCreatedBooking(createdCriteria) || await ensureCreatedBookingVisible(createdCriteria);
    if (!sessionIsCurrent(userId, generation)) return;
    if (!createdBooking) {
      button.disabled = false;
      updateNewBookingSubmitCaption();
      showFormError('#newBookingError', 'Сервер подтвердил запись, но точную строку журнала получить не удалось. Данные сохранены: повторите без изменений для безопасного восстановления.');
      return;
    }
  }
  if (!block && !repeatVisit && Number(serviceModel?.duration_minutes) === 1 && durationMinutes > 1) {
    const adjusted = await applyPerMinuteBookingTerms([createdBooking.id], serviceModel, durationMinutes);
    if (!adjusted.ok) {
      const rollback = await rollbackCreatedBookings([createdBooking.id]);
      await loadBookings({ silent:true });
      button.disabled = false;
      button.textContent = 'Создать запись';
      if (rollback.ok) clearProviderBookingAttempt(providerAttempt?.requestId || '', userId);
      else submittedForm.dataset.creationUncertain = 'true';
      showFormError('#newBookingError', rollback.ok ? 'Окно не вмещает выбранную длительность. Созданная запись удалена — выберите другое время или длительность.' : 'Не удалось подтвердить удаление записи после ошибки длительности. Проверьте журнал перед повторным созданием.');
      await loadNewBookingSlots();
      return;
    }
  }
  const normalizedPhone = normalizePhone(phone);
  if (!block && note) {
    await saveClientNoteValue(normalizedPhone, note, { isCurrent:() => sessionIsCurrent(userId, generation) });
    if (!sessionIsCurrent(userId, generation)) return;
  }
  if (createdBooking) {
    await saveBookingColor(createdBooking.id, color, { rerender:false });
    if (!sessionIsCurrent(userId, generation)) return;
  }
  if (!block && (!providerAttempt?.requestId || !clearProviderBookingAttempt(providerAttempt.requestId, userId))) {
    button.disabled = false;
    updateNewBookingSubmitCaption();
    showFormError('#newBookingError', 'Запись создана, но локальную защиту повтора не удалось завершить. Не меняйте данные и повторите ещё раз.');
    return;
  }
  selectScheduleDate(date);
  clearNewBookingDraft(userId);
  closeBookingSheet();
  await refreshAfterWrite();
  createdBooking ||= findCreatedBooking(createdCriteria);
  createdBooking ||= await ensureCreatedBookingVisible(createdCriteria);
  let clientTelegramResult = null;
  if (createdBooking) {
    if (block) await saveBookingColor(createdBooking.id, color, { rerender:false });
    if (!block) {
      clientTelegramResult = await deliverTelegramClientNotification(createdBooking.id, 'confirmation');
    }
    focusCreatedBooking(createdBooking.id);
  }
  notify(block
    ? 'Время занято'
    : clientTelegramResult?.delivered
      ? 'Новая запись создана · клиент получил подтверждение в Telegram'
      : clientTelegramResult?.reason === 'not_connected'
        ? 'Новая запись создана · клиент ещё не подключил Telegram'
        : 'Новая запись создана · подтверждение в Telegram не отправлено');
}

function closeBookingSheet() {
  const returnFocus = $('#bookingSheet').dataset.assistantContext === 'automatic-break' ? automaticBreakSheetInvoker : null;
  automaticBreakSheetInvoker = null;
  bookingSeriesCancellationRevision += 1;
  bookingEditorRevision += 1;
  editingOfflineBookingId = '';
  newBookingHistoricalMode = false;
  newBookingRepeatVisit = null;
  resetServicePublicCardPhotoPreview('edit');
  $('#bookingSheet').hidden = true;
  $('#bookingSheet').classList.remove('booking-sheet-wide', 'new-booking-sheet', 'booking-sheet-detail');
  delete $('#bookingSheet').dataset.bookingId;
  delete $('#bookingSheet').dataset.assistantContext;
  applyClientHighlightClasses($('#bookingSheet'), '', 'booking-sheet-');
  document.body.classList.remove('booking-sheet-open');
  if (returnFocus?.isConnected) requestAnimationFrame(() => returnFocus.focus({ preventScroll:true }));
}

async function openCommerceSale({ bookingId = '', clientId = '' } = {}) {
  const organization = organizationController?.getActiveOrganization?.();
  if (!organization?.id || !['owner', 'admin'].includes(organization.current_role)) {
    notify('Продажи доступны владельцу или администратору организации');
    return;
  }
  closeBookingSheet();
  await Promise.resolve(setProviderView('organization'));
  const section = $('#commercePanel');
  if (section) section.hidden = false;
  try {
    await ensureOrganizationFeature('commercePanel');
    const button = $('[data-section-target="commercePanel"]');
    if (button) scrollToProviderSection(button);
    commerceController?.startSale({ bookingId, clientId });
  } catch {
    notify('Раздел продаж не загрузился. Повторите после обновления страницы.');
  }
}

function openCommerceSaleFromBooking(id) {
  const item = bookingSourceItems().find(booking => String(booking.id) === String(id));
  if (!item) return Promise.resolve();
  return openCommerceSale({ bookingId:item.id, clientId:item.client_account_id || '' });
}

function calendarRangeTitle(view = calendarView) {
  const range = calendarRange(view);
  const start = parseLocalIsoDate(range.start);
  const end = parseLocalIsoDate(range.end);
  if (view === 'month') return start.toLocaleDateString('ru-RU', { month:'long', year:'numeric' });
  if (view === 'week') {
    const sameMonth = start.getMonth() === end.getMonth() && start.getFullYear() === end.getFullYear();
    if (sameMonth) return `${start.getDate()}–${end.toLocaleDateString('ru-RU', { day:'numeric', month:'long', year:'numeric' })}`;
    return `${start.toLocaleDateString('ru-RU', { day:'numeric', month:'short' })} — ${end.toLocaleDateString('ru-RU', { day:'numeric', month:'short', year:'numeric' })}`;
  }
  return selectedDate === businessTodayIso()
    ? 'Сегодня'
    : start.toLocaleDateString('ru-RU', { day:'numeric', month:'long', weekday:'long' });
}

function renderSelectedDateTitle(view = calendarView) {
  const holder = $('#selectedDateTitle');
  if (!holder) return;
  const defaultTitle = calendarRangeTitle(view);
  if (view !== 'day') {
    holder.textContent = defaultTitle;
    return;
  }
  const weekday = parseLocalIsoDate(selectedDate).toLocaleDateString('ru-RU', { weekday:'long' });
  const mobileTitle = weekday ? `${weekday[0].toLocaleUpperCase('ru-RU')}${weekday.slice(1)}` : defaultTitle;
  holder.replaceChildren();
  const defaultLabel = document.createElement('span');
  defaultLabel.className = 'selected-date-title-default';
  defaultLabel.textContent = defaultTitle;
  const mobileLabel = document.createElement('span');
  mobileLabel.className = 'selected-date-title-mobile';
  mobileLabel.textContent = mobileTitle;
  holder.append(defaultLabel, mobileLabel);
}

function calendarOverviewBookingMarkup(item, compact) {
  const time = String(item.booking_time || '').slice(0, 5);
  const block = isScheduleBlock(item);
  const fullTitle = block ? (item.client_name || 'Перерыв') : serviceName(item.services?.name || 'Услуга');
  const title = block ? fullTitle : serviceScheduleName(fullTitle, item.service_id);
  const client = block ? 'Занятое время' : item.client_name;
  const statusClass = bookingStatusClass(item);
  const phone = block || !displayPreferences.show_phone ? '' : String(item.client_phone || '');
  const visitText = block ? '' : bookingVisitSummaryText(item);
  const rawNote = block ? '' : bookingDisplayNote(item);
  const notePresence = bookingNotePresenceMarkup(rawNote, 'calendar-overview-note-presence');
  const badgeText = block || !displayPreferences.show_client_labels ? '' : clientBadgeText(item.client_phone);
  const badgeMarkup = block || !displayPreferences.show_client_labels ? '' : clientBadgeMarkup(item.client_phone, { limit:1, showLabels:true });
  const importedText = item.is_imported_history ? 'Импортировано, только просмотр' : '';
  const details = [fullTitle, client, time, visitText, badgeText, importedText, displayPreferences.show_notes && rawNote ? `заметка: ${rawNote}` : rawNote ? 'есть заметка' : ''].filter(Boolean).join(', ');
  const cardDetails = compact ? '' : `<span class="calendar-overview-booking-details">
    <span class="calendar-overview-client-row"><b>${escapeHtml(client)}${item.is_imported_history ? ' · Импортировано' : ''}</b>${badgeMarkup}</span>
    ${phone ? `<small class="calendar-overview-phone">${escapeHtml(phone)}</small>` : ''}
    ${visitText ? `<small class="calendar-overview-visit">${escapeHtml(visitText)}</small>` : ''}
    ${notePresence}
  </span>`;
  return `<button class="calendar-overview-booking status-${statusClass} color-${bookingColor(item)}${item.is_imported_history ? ' is-imported-history' : ''}${item.id === recentlyCreatedBookingId ? ' booking-created-highlight' : ''}" type="button" data-open-booking="${escapeHtml(item.id)}" aria-label="${escapeHtml(details)}. Открыть запись"><time>${escapeHtml(time)}</time><span class="calendar-overview-booking-copy"><strong>${escapeHtml(title)}</strong>${cardDetails}</span></button>`;
}

function calendarMonthMobileAgendaMarkup(days, byDate) {
  const groups = days.map(date => {
    const iso = localIsoDate(date);
    const items = byDate.get(iso) || [];
    if (!items.length) return '';
    const label = date.toLocaleDateString('ru-RU', { weekday:'long', day:'numeric', month:'long' });
    return `<section class="calendar-month-agenda-day"><button class="calendar-month-agenda-date" type="button" data-calendar-open-date="${iso}">${escapeHtml(label)}</button><div>${items.map(item => calendarOverviewBookingMarkup(item, false)).join('')}</div></section>`;
  }).filter(Boolean).join('');
  return groups ? `<div class="calendar-month-mobile-agenda" aria-label="Записи месяца">${groups}</div>` : '';
}

function calendarWeekTimelineBounds(days, byDate) {
  let start = Infinity;
  let end = -Infinity;
  days.forEach(date => {
    const iso = localIsoDate(date);
    const weekday = ((date.getDay() + 6) % 7) + 1;
    const schedule = scheduleRows.find(row => Number(row.weekday) === weekday);
    if (schedule && schedule.enabled !== false) {
      start = Math.min(start, Math.floor(minutesFromTime(schedule.start_time || '10:00') / 60) * 60);
      end = Math.max(end, Math.ceil(minutesFromTime(schedule.end_time || '20:00') / 60) * 60);
    }
    (byDate.get(iso) || []).forEach(item => {
      const itemStart = minutesFromTime(item.booking_time);
      const duration = Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60));
      start = Math.min(start, Math.floor(itemStart / 60) * 60);
      end = Math.max(end, Math.ceil((itemStart + duration) / 60) * 60);
    });
  });
  if (!Number.isFinite(start) || !Number.isFinite(end)) return { start:10 * 60, end:20 * 60 };
  start = Math.max(0, start);
  end = Math.min(1440, Math.max(start + 60, end));
  return { start, end };
}

function stackWeekTimelineItems(items, gap = 3) {
  let previousBottom = -Infinity;
  items.sort((left, right) => left.top - right.top || left.index - right.index).forEach(entry => {
    entry.visualTop = Math.max(entry.top, previousBottom + gap);
    previousBottom = entry.visualTop + entry.height;
  });
}

function calendarWeekTimelineMarkup(days, byDate, today) {
  const { start, end } = calendarWeekTimelineBounds(days, byDate);
  const hourHeight = 66;
  const height = ((end - start) / 60) * hourHeight;
  const labels = [];
  for (let minute = start; minute <= end; minute += 30) {
    const top = ((minute - start) / 60) * hourHeight;
    labels.push(`<span class="calendar-week-time${minute % 60 ? ' is-half' : ''}" style="top:${top}px">${timeFromMinutes(minute)}</span>`);
  }
  const headers = days.map((date, index) => {
    const iso = localIsoDate(date);
    const fullDate = date.toLocaleDateString('ru-RU', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
    return `<button class="calendar-week-date${iso === today ? ' is-today' : ''}${iso === selectedDate ? ' is-selected' : ''}" type="button" data-calendar-open-date="${iso}" style="grid-column:${index + 2}" ${iso === today ? 'aria-current="date"' : ''} aria-label="${escapeHtml(fullDate)}. Открыть день"><span>${escapeHtml(date.toLocaleDateString('ru-RU', { weekday:'short' }).replace('.', ''))}</span><strong>${date.getDate()}</strong><small>${escapeHtml(date.toLocaleDateString('ru-RU', { month:'short' }).replace('.', ''))}</small></button>`;
  }).join('');
  const columns = days.map((date, index) => {
    const iso = localIsoDate(date);
    const timelineItems = (byDate.get(iso) || []).map((item, itemIndex) => {
      const duration = Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60));
      const top = ((minutesFromTime(item.booking_time) - start) / 60) * hourHeight;
      const naturalHeight = (duration / 60) * hourHeight;
      return { item, index:itemIndex, duration, top, visualTop:top, height:duration <= 1 ? 34 : Math.max(30, naturalHeight - 4), minuteOnly:duration <= 1 };
    });
    stackWeekTimelineItems(timelineItems);
    const cards = timelineItems.map(({ item, duration, visualTop, height:cardHeight }) => {
      const startTime = String(item.booking_time || '').slice(0, 5);
      const endTime = timeFromMinutes(minutesFromTime(startTime) + duration);
      const block = isScheduleBlock(item);
      const fullTitle = block ? (item.client_name || 'Перерыв') : serviceName(item.services?.name || 'Услуга');
      const title = block ? fullTitle : serviceScheduleName(fullTitle, item.service_id);
      const client = block ? 'Занятое время' : item.client_name;
      const statusClass = bookingStatusClass(item);
      const details = `${fullTitle}, ${client}, с ${startTime} до ${endTime}`;
      return `<button class="calendar-week-booking status-${statusClass} color-${bookingColor(item)}${block ? ' is-block' : ''}${item.is_imported_history ? ' is-imported-history' : ''}${cardHeight < 54 ? ' is-compact' : ''}${item.id === recentlyCreatedBookingId ? ' booking-created-highlight' : ''}" type="button" data-open-booking="${escapeHtml(item.id)}" style="top:${visualTop + 2}px;height:${cardHeight}px" aria-label="${escapeHtml(details)}. ${item.is_imported_history ? 'Импортировано, только просмотр' : 'Открыть запись'}"><time>${escapeHtml(startTime)}–${escapeHtml(endTime)}</time><strong>${escapeHtml(title)}</strong><small>${escapeHtml(client)}${item.is_imported_history ? ' · Импортировано' : ''}</small></button>`;
    }).join('');
    const nowMarker = scheduleNowMarkerMarkup(iso, start, end, hourHeight, 'calendar-week-now-marker');
    return `<section class="calendar-week-day-stage${iso === today ? ' is-today' : ''}" style="grid-column:${index + 2}" aria-label="${escapeHtml(date.toLocaleDateString('ru-RU', { weekday:'long', day:'numeric', month:'long' }))}">${nowMarker}${cards}</section>`;
  }).join('');
  return `<div class="calendar-week-timeline" aria-label="Недельное расписание по времени"><div class="calendar-week-timeline-grid" style="--calendar-week-height:${height}px;--calendar-week-hour:${hourHeight}px;--calendar-week-half-hour:${hourHeight / 2}px"><div class="calendar-week-axis-head">Время</div>${headers}<div class="calendar-week-axis" aria-hidden="true">${labels.join('')}</div>${columns}</div></div>`;
}

function renderCalendarOverview(view) {
  const holder = $('#providerBookings');
  const range = calendarRange(view);
  const start = parseLocalIsoDate(range.start);
  const end = parseLocalIsoDate(range.end);
  const today = businessTodayIso();
  const visible = bookingSourceItems().filter(item => item.status !== 'cancelled' && item.booking_date >= range.start && item.booking_date <= range.end);
  const byDate = new Map();
  visible.forEach(item => {
    if (!byDate.has(item.booking_date)) byDate.set(item.booking_date, []);
    byDate.get(item.booking_date).push(item);
  });
  const days = [];
  for (const cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) days.push(new Date(cursor));
  const leading = view === 'month' ? (start.getDay() + 6) % 7 : 0;
  const dayCells = [
    ...Array.from({ length:leading }, () => '<div class="calendar-overview-day is-placeholder" aria-hidden="true"></div>'),
    ...days.map(date => {
      const iso = localIsoDate(date);
      const items = byDate.get(iso) || [];
      const limit = view === 'month' ? 2 : items.length;
      const hiddenCount = Math.max(0, items.length - limit);
      const fullDate = date.toLocaleDateString('ru-RU', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
      const monthCount = items.length ? `${items.length} ${items.length === 1 ? 'запись' : items.length < 5 ? 'записи' : 'записей'}` : 'Свободно';
      return `<article class="calendar-overview-day${iso === today ? ' is-today' : ''}${iso === selectedDate ? ' is-selected' : ''}" data-calendar-date="${iso}">
        <button class="calendar-overview-date" type="button" data-calendar-open-date="${iso}" ${iso === today ? 'aria-current="date"' : ''} aria-label="${escapeHtml(fullDate)}. ${view === 'month' ? `${escapeHtml(monthCount)}. ` : ''}Открыть день"><span>${view === 'week' ? escapeHtml(date.toLocaleDateString('ru-RU', { weekday:'short' }).replace('.', '')) : ''}</span><strong>${date.getDate()}</strong>${view === 'week' ? `<small>${escapeHtml(date.toLocaleDateString('ru-RU', { month:'short' }).replace('.', ''))}</small>` : `<small class="calendar-overview-count">${escapeHtml(monthCount)}</small>`}</button>
        <div class="calendar-overview-items">${items.slice(0, limit).map(item => calendarOverviewBookingMarkup(item, view === 'month')).join('')}${hiddenCount ? `<button class="calendar-overview-more" type="button" data-calendar-open-date="${iso}">+ ещё ${seriesBookingCountLabel(hiddenCount)}</button>` : ''}</div>
      </article>`;
    })
  ];
  const weekdayHeader = view === 'month' ? `<div class="calendar-overview-weekdays" aria-hidden="true">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(day => `<span>${day}</span>`).join('')}</div>` : '';
  const mobileMonthAgenda = view === 'month' ? calendarMonthMobileAgendaMarkup(days, byDate) : '';
  holder.className = `provider-bookings calendar-overview calendar-overview-${view}`;
  holder.innerHTML = view === 'week'
    ? `${calendarWeekTimelineMarkup(days, byDate, today)}<div class="calendar-overview-grid calendar-week-mobile-list" role="grid" aria-label="${escapeHtml(calendarRangeTitle(view))}">${dayCells.join('')}</div>`
    : `${weekdayHeader}<div class="calendar-overview-grid" role="grid" aria-label="${escapeHtml(calendarRangeTitle(view))}">${dayCells.join('')}</div>${mobileMonthAgenda}`;
  if (typeof updateScheduleNowMarkers === 'function') updateScheduleNowMarkers();
  renderSelectedDateTitle(view);
  const clientCount = visible.filter(item => !isScheduleBlock(item)).length;
  const blockCount = visible.length - clientCount;
  $('#selectedDateSummary').textContent = [clientCount ? `${clientCount} ${clientCount === 1 ? 'запись' : clientCount < 5 ? 'записи' : 'записей'}` : 'Записей нет', blockCount ? `${blockCount} ${blockCount === 1 ? 'перерыв' : blockCount < 5 ? 'перерыва' : 'перерывов'}` : ''].filter(Boolean).join(' · ');
}

function renderBookings() {
  if (timelineBookingDrag) finishTimelineBookingDrag();
  const holder = $('#providerBookings');
  renderBookingDataSourceNotice();
  updateBookingQueryTools();
  renderSelectedDateTitle(calendarView);
  if (bookingUsesDemoData() && reportScopedBookingsState.status !== 'ready') {
    const failed = reportScopedBookingsState.status === 'failed';
    holder.className = 'provider-bookings';
    holder.innerHTML = `<div class="empty-state"><strong>${failed ? 'Не удалось загрузить демо-записи' : 'Загружаем демо-записи'}</strong><span>${failed ? 'Вернитесь в статистику и повторите загрузку.' : 'Учебные записи появятся по соответствующим дням.'}</span></div>`;
    $('#selectedDateSummary').textContent = failed ? 'Данные недоступны' : 'Подождите немного';
    return;
  }
  if (!bookingUsesDemoData() && teamCalendarController?.isTeamMode) {
    $('#selectedDateSummary').textContent = 'Записи выбранной команды';
    if (teamCalendarController.render(holder)) return;
  }
  if (currentFilter === 'day' && calendarView !== 'day') {
    renderCalendarOverview(calendarView);
    return;
  }
  const sourceItems = filteredBookings();
  const items = applyBookingQuery(sourceItems);
  const paginated = currentFilter !== 'day' && items.length > bookingRenderLimit;
  const visibleItems = paginated ? items.slice(0, bookingRenderLimit) : items;
  const clientCount = items.filter(item => !isScheduleBlock(item)).length;
  const operationalItems = items.filter(item => !item.is_imported_history);
  const blockCount = items.filter(isScheduleBlock).length + (currentFilter === 'day' ? automaticBookingBreaks(operationalItems).length : 0);
  const daySummary = [clientCount ? `${clientCount} ${clientCount === 1 ? 'запись' : clientCount < 5 ? 'записи' : 'записей'}` : '', blockCount ? `${blockCount} ${blockCount === 1 ? 'перерыв' : blockCount < 5 ? 'перерыва' : 'перерывов'}` : ''].filter(Boolean).join(' · ');
  $('#selectedDateSummary').textContent = currentFilter === 'day'
    ? (daySummary || 'Свободный день')
    : `${currentFilter === 'upcoming' ? 'Все будущие записи' : 'История записей'}${bookingQueryIsActive() ? ` · найдено ${items.length}` : ''}`;
  if (currentFilter === 'day' && journalMode === 'timeline') renderTimeline(items);
  else {
    renderBookingList(visibleItems, bookingQueryIsActive() ? 'По заданным условиям ничего не найдено.' : 'На выбранный период всё свободно.');
    if (paginated) $('#providerBookings').insertAdjacentHTML('beforeend', `<button class="secondary-button" type="button" data-load-more-bookings>Показать ещё · осталось ${items.length - visibleItems.length}</button>`);
  }
}

function setTeamCalendarMode(active, options = {}) {
  const teamMode = active === true;
  const modeToggle = $('.journal-mode-toggle');
  const filters = $('.booking-filters');
  const createButton = $('#newBookingButton');
  if (modeToggle) modeToggle.hidden = teamMode || calendarView !== 'day';
  if (filters) filters.hidden = teamMode || calendarView !== 'day' || journalMode === 'timeline';
  if (createButton) createButton.hidden = teamMode;
  if (!teamMode) updateJournalModeButtons();
  updateBookingQueryTools();
  if (options.render !== false) renderBookings();
}

function buildClients() {
  const clients = new Map();
  const activeOrganizationId = activeClientOrganizationId;
  const belongsToActiveOrganization = booking => !activeOrganizationId
    || (Boolean(booking?.organization_id) && String(booking.organization_id) === String(activeOrganizationId));
  importedClients.forEach(imported => {
    const phone = normalizePhone(imported.phone || imported.display_phone);
    if (!phone) return;
    clients.set(phone, {
      phone,
      displayPhone:imported.display_phone || imported.phone,
      name:imported.name || 'Клиент',
      bookings:[],
      imported
    });
  });
  importedBookingHistory.forEach(booking => {
    if (!belongsToActiveOrganization(booking)) return;
    const phone = normalizePhone(booking.client_phone);
    if (!phone) return;
    const current = clients.get(phone) || { phone,displayPhone:booking.client_phone,name:booking.client_name,bookings:[] };
    current.name = booking.client_name || current.name;
    current.displayPhone = booking.client_phone || current.displayPhone;
    current.bookings.push(booking);
    clients.set(phone, current);
  });
  allBookings.forEach(booking => {
    if (isScheduleBlock(booking) || !belongsToActiveOrganization(booking)) return;
    const phone = normalizePhone(booking.client_phone);
    if (!phone) return;
    const current = clients.get(phone) || { phone, displayPhone: booking.client_phone, name: booking.client_name, bookings: [] };
    current.name = booking.client_name || current.name;
    current.displayPhone = booking.client_phone || current.displayPhone;
    current.clientAccountId = booking.client_account_id || current.clientAccountId || '';
    current.bookings.push(booking);
    clients.set(phone, current);
  });
  return [...clients.values()].sort((a, b) => {
    const aLast = a.bookings.at(-1); const bLast = b.bookings.at(-1);
    const aSort = `${aLast?.booking_date || a.imported?.last_visit_on || ''}${aLast?.booking_time || ''}`;
    const bSort = `${bLast?.booking_date || b.imported?.last_visit_on || ''}${bLast?.booking_time || ''}`;
    return bSort.localeCompare(aSort) || a.name.localeCompare(b.name, 'ru');
  });
}

function clientUpcoming(client, now = new Date()) {
  return client.bookings
    .filter(item => item.status !== 'cancelled' && new Date(`${item.booking_date}T${String(item.booking_time).slice(0, 8)}`) >= now)
    .sort((left, right) => `${left.booking_date}T${left.booking_time}`.localeCompare(`${right.booking_date}T${right.booking_time}`))[0] || null;
}

let clientDirectoryController = null;
function renderClients() {
  const clients = buildClients();
  const search = $('#clientSearch').value.trim().toLowerCase();
  if (!clientDirectoryController && window.MinutaClientDirectory && $('#clientDirectoryFilters')) {
    clientDirectoryController = window.MinutaClientDirectory.create({
      root:$('#clientDirectoryFilters'),
      refresh:() => { clientRenderLimit = CLIENT_RENDER_PAGE_SIZE; renderClients(); },
      outcome:bookingOutcome, getLabels:clientLabel, services:() => ownServices,
      nameKey:favoriteServiceNameKey, today:businessTodayIso
    });
  }
  const filtered = clientDirectoryController
    ? clientDirectoryController.apply(clients, search, `${currentUser?.id || ''}:${activeClientOrganizationId || ''}:${sessionGeneration}`)
    : clients.filter(client => `${client.name} ${client.displayPhone} ${client.phone}`.toLowerCase().includes(search));
  const visibleClients = filtered.slice(0, clientRenderLimit);
  $('#clientsCount').textContent = String(clients.length);
  if ($('#clientsBadge')) $('#clientsBadge').textContent = String(clients.length);
  if (!filtered.length) {
    $('#clientsList').innerHTML = `<div class="provider-empty compact-empty"><span class="provider-empty-icon">${uiIcon('user')}</span><strong>${clients.length ? 'Ничего не найдено' : 'Клиентов пока нет'}</strong><small>${clients.length ? 'Попробуйте изменить запрос.' : 'Они появятся после первой записи.'}</small></div>`;
    return;
  }
  $('#clientsList').innerHTML = visibleClients.map(client => {
    const upcoming = clientUpcoming(client);
    const facts = clientRelationshipFacts(client);
    const knownCount = facts.visits;
    const nextText = upcoming ? `${new Date(`${upcoming.booking_date}T12:00:00`).toLocaleDateString('ru-RU', { day:'numeric', month:'short' })}, ${String(upcoming.booking_time).slice(0,5)}` : 'Нет будущих записей';
    const hasPhoto = Boolean(clientAvatar(client.phone)?.signed_url);
    const displayPhone = newBookingClientPhoneLabel(client.phone, client.displayPhone);
    return `<button class="client-list-item ${client.phone === selectedClientPhone ? 'active' : ''}${clientHighlightClasses(client.phone)}" type="button" data-client-phone="${client.phone}"><span class="client-list-avatar-orbit${hasPhoto ? ' has-photo' : ''}${facts.level === 4 ? ' is-max-level' : ''}" data-client-level="${facts.level}" style="--client-level-progress:${facts.progress.toFixed(4)}turn" aria-hidden="true"><span class="client-list-avatar">${clientAvatarContent(client.phone, client.name)}</span><span class="client-orbit-jewel">${uiIcon('crown')}</span></span><span class="client-list-main"><span class="client-list-name-row"><strong>${escapeHtml(client.name)}</strong>${clientBadgeMarkup(client.phone)}</span><small>${escapeHtml(displayPhone)}</small><i>${escapeHtml(nextText)}</i><em class="client-list-level">${escapeHtml(facts.level ? `${facts.title} · ${facts.level} уровень` : facts.title)}</em></span><b aria-label="Завершённых визитов: ${knownCount}">${knownCount}</b></button>`;
  }).join('') + (filtered.length > visibleClients.length ? `<button class="secondary-button" type="button" data-load-more-clients>Показать ещё · осталось ${filtered.length - visibleClients.length}</button>` : '');
}

function openQuickRepeatForClient(phone = selectedClientPhone) {
  if (!requireBookingWrites()) return;
  const client = buildClients().find(item => item.phone === normalizePhone(phone));
  if (!client) {
    notify('Сначала выберите клиента');
    return;
  }
  const activeServiceIds = new Set(ownServices.filter(item => item.active).map(item => item.id));
  const previousBooking = [...client.bookings]
    .sort((a, b) => `${b.booking_date}${b.booking_time}`.localeCompare(`${a.booking_date}${a.booking_time}`))
    .find(item => activeServiceIds.has(item.service_id));
  if (!previousBooking) {
    openNewBookingSheet('', { clientName:client.name, clientPhone:client.displayPhone });
    return;
  }
  openNewBookingSheet('', {
    clientName:client.name,
    clientPhone:client.displayPhone,
    serviceId:previousBooking.service_id
  });
}

function openFavoriteServiceBooking(serviceId, phone = selectedClientPhone) {
  if (!requireBookingWrites()) return;
  const client = buildClients().find(item => item.phone === normalizePhone(phone));
  const service = ownServices.find(item => item.active && String(item.id) === String(serviceId));
  if (!client || !service) {
    notify('Эта услуга больше недоступна для записи');
    return;
  }
  openNewBookingSheet('', {
    clientName:client.name,
    clientPhone:client.displayPhone,
    serviceId:service.id
  });
}

function updateClientPreferencesPreview(phone, noteValue = clientNotes.get(phone) || '') {
  if (selectedClientPhone !== phone) return;
  const labels = clientLabel(phone);
  const preferences = [
    labels.favorite ? 'Любимый' : '',
    labels.vip ? 'VIP' : '',
    labels.attention ? 'Внимание' : '',
    noteValue ? 'Есть заметка' : ''
  ].filter(Boolean);
  $('#clientPreferencesPreview').textContent = preferences.join(' · ') || 'Метки и заметка';
}

function favoriteServiceNameKey(value) {
  return serviceName(String(value || '').trim())
    .toLocaleLowerCase('ru-RU')
    .replace(/ё/g, 'е')
    .replace(/[^a-zа-я0-9]+/giu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function clientFavoriteServiceFacts(bookings) {
  const activeServices = ownServices.filter(item => item.active);
  const servicesById = new Map(activeServices.map(item => [String(item.id), item]));
  const servicesByName = new Map();
  activeServices.forEach(service => {
    const nameKey = favoriteServiceNameKey(service.name);
    if (!nameKey) return;
    servicesByName.set(nameKey, servicesByName.has(nameKey) ? null : service);
  });
  const totals = new Map();
  bookings.forEach(item => {
    const rawName = String(item.services?.name || '').trim();
    if (!rawName) return;
    const nameKey = favoriteServiceNameKey(rawName);
    if (!nameKey || nameKey === 'услуга') return;
    const service = servicesById.get(String(item.service_id || '')) || servicesByName.get(nameKey);
    if (!service && !item.is_imported_history) return;
    const key = service ? `service:${service.id}` : `imported:${nameKey}`;
    const current = totals.get(key) || {
      id:service?.id || '',
      name:serviceName(service?.name || rawName),
      count:0,
      lastVisit:'',
      importedOnly:!service
    };
    current.count += 1;
    current.lastVisit = [current.lastVisit, `${item.booking_date || ''}${item.booking_time || ''}`].sort().at(-1);
    totals.set(key, current);
  });
  const favorites = [...totals.values()]
    .sort((left, right) => right.count - left.count || right.lastVisit.localeCompare(left.lastVisit) || left.name.localeCompare(right.name, 'ru'))
    .slice(0, 2);
  return favorites;
}

function renderClientFavoriteServices(bookings) {
  const favorites = clientFavoriteServiceFacts(bookings);
  const section = $('#clientFavoriteServices');
  $('#clientFavoriteServicesList').innerHTML = favorites.map(item => item.importedOnly
    ? `<span class="client-favorite-service is-imported" data-imported-favorite-service title="Услуга из импортированной истории ещё не связана с текущим каталогом"><span>${escapeHtml(item.name)}</span><small>из импорта</small></span>`
    : `<button type="button" data-client-favorite-service="${escapeHtml(item.id)}" title="Записать клиента на услугу «${escapeHtml(item.name)}»" aria-label="Записать клиента на услугу «${escapeHtml(item.name)}»"><svg class="ui-icon" aria-hidden="true"><use href="ui-icons.svg#icon-plus"></use></svg><span>${escapeHtml(item.name)}</span></button>`).join('');
  section.hidden = !favorites.length;
}

function setClientProfileDetailMode(active) {
  const enabled = active === true;
  if (!enabled) closeClientProfileDialogs();
  $('#clientsLayout')?.classList.toggle('is-detail', enabled);
  document.body.classList.toggle('client-profile-detail-open', enabled);
  if (enabled && matchMedia('(max-width:980px)').matches) requestAnimationFrame(() => window.scrollTo({ top:0, behavior:'auto' }));
}

function closeClientProfileDialogs() {
  $$('.client-profile-dialog[open]').forEach(dialog => dialog.close());
}

function normalizedClientProfileDetails(value = {}, fallbackBirthday = '') {
  const birthday = /^\d{4}-\d{2}-\d{2}$/.test(String(value?.birthday || ''))
    ? String(value.birthday)
    : /^\d{4}-\d{2}-\d{2}$/.test(String(fallbackBirthday || '')) ? String(fallbackBirthday) : '';
  return {
    phone:normalizePhone(value?.client_phone || selectedClientPhone),
    birthday,
    onlineBookingBlocked:Boolean(value?.online_booking_blocked),
    onlineBookingBlockReason:String(value?.online_booking_block_reason || '').trim(),
    supportsBlockReason:Boolean(value?.supports_block_reason),
    canEdit:Boolean(value?.can_edit),
    canManageBlock:Boolean(value?.can_manage_block),
    available:Boolean(value?.available)
  };
}

function clientBirthdayLabel(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ''))) return '';
  return new Date(`${value}T12:00:00`).toLocaleDateString('ru-RU', { day:'numeric', month:'long', year:'numeric' });
}

function renderClientProfileDetails(client, state = clientProfileDetailsState) {
  if (!client || selectedClientPhone !== client.phone) return;
  const digits = normalizePhone(client.phone);
  const displayPhone = newBookingClientPhoneLabel(client.phone, client.displayPhone);
  const phoneCopy = $('#clientCopyPhone');
  if (phoneCopy) phoneCopy.disabled = !digits;
  const contactButton = $('#clientContactButton');
  if (contactButton) contactButton.disabled = !digits;
  const moreButton = $('#clientMoreButton');
  if (moreButton) moreButton.hidden = !state.available || (!state.canEdit && !state.canManageBlock);
  $('#clientContactPhone').textContent = displayPhone;
  $('#clientCallLink').href = digits ? `tel:${digits}` : '#';
  $('#clientWhatsappLink').href = digits ? `https://wa.me/${digits}` : '#';
  $('#clientTelegramLink').href = digits ? `tg://resolve?phone=${digits}` : '#';
  const birthdayText = clientBirthdayLabel(state.birthday);
  $('#clientBirthdayInfo').hidden = !state.available || (!birthdayText && !state.canEdit);
  $('#clientBirthdayDisplay').textContent = birthdayText || 'Не указано';
  $('#clientBirthdayEdit').hidden = !state.canEdit;
  $('#clientBirthdayEdit').textContent = birthdayText ? 'Изменить' : 'Указать';
  $('#clientIdentityAction').hidden = !state.available || !state.canEdit;
  $('#clientBirthdayInput').value = state.birthday;
  $('#clientBirthdayInput').max = businessTodayIso();
  const blocked = state.onlineBookingBlocked;
  $('#clientOnlineBlockBadge').hidden = !blocked;
  const blockAction = $('#clientBlockAction');
  blockAction.hidden = !state.available || !state.canManageBlock;
  blockAction.classList.toggle('is-unblock', blocked);
  blockAction.querySelector('span').textContent = blocked ? 'Разблокировать онлайн-запись' : 'Заблокировать онлайн-запись';
  $('#clientRestrictions').hidden = !state.available || !state.canManageBlock;
  $('#clientBlockStatus').textContent = blocked ? 'Онлайн-запись заблокирована' : 'Онлайн-запись разрешена';
  const reasonSummary = $('#clientBlockReasonSummary');
  reasonSummary.hidden = !blocked || !state.onlineBookingBlockReason;
  reasonSummary.textContent = state.onlineBookingBlockReason ? `Причина: ${state.onlineBookingBlockReason}` : '';
}

async function loadClientProfileDetails(client) {
  const revision = ++clientProfileDetailsLoadRevision;
  const fallback = normalizedClientProfileDetails({ client_phone:client.phone, birthday:client.imported?.birthday || '' }, client.imported?.birthday);
  clientProfileDetailsState = fallback;
  renderClientProfileDetails(client, fallback);
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  const organizationId = activeClientOrganizationId;
  if (!userId || !organizationId || !client.phone) return;
  let { data, error } = await db.rpc('get_minuta_client_profile_v135', { p_organization:organizationId, p_client_phone:client.phone });
  let supportsBlockReason = !error;
  if (error && isMissingRpc(error, 'get_minuta_client_profile_v135')) {
    ({ data, error } = await db.rpc('get_minuta_client_profile_v119', { p_organization:organizationId, p_client_phone:client.phone }));
    supportsBlockReason = false;
  }
  if (revision !== clientProfileDetailsLoadRevision || !sessionIsCurrent(userId, generation) || selectedClientPhone !== client.phone || activeClientOrganizationId !== organizationId) return;
  if (error) {
    if (!isMissingRpc(error, 'get_minuta_client_profile_v119')) console.warn('Client profile details unavailable:', error.message);
    return;
  }
  clientProfileDetailsState = normalizedClientProfileDetails({ ...data, supports_block_reason:supportsBlockReason, available:true }, fallback.birthday);
  renderClientProfileDetails(client, clientProfileDetailsState);
}

async function copySelectedClientPhone() {
  const client = buildClients().find(item => item.phone === selectedClientPhone);
  const value = String(client?.displayPhone || client?.phone || '').trim();
  if (!value) return;
  try {
    await navigator.clipboard.writeText(value);
    notify('Номер скопирован');
  } catch {
    notify('Не удалось скопировать номер');
  }
}

function openClientContactDialog() {
  const client = buildClients().find(item => item.phone === selectedClientPhone);
  if (!client || !normalizePhone(client.phone)) return;
  renderClientProfileDetails(client);
  $('#clientContactDialog').showModal();
}

function openClientMoreDialog() {
  const client = buildClients().find(item => item.phone === selectedClientPhone);
  if (!client) return;
  renderClientProfileDetails(client);
  $('#clientMoreDialog').showModal();
}

function openClientBirthdayDialog() {
  $('#clientMoreDialog')?.close();
  $('#clientBirthdayInput').value = clientProfileDetailsState.birthday;
  $('#clientBirthdayDialog').showModal();
}

function openClientIdentityDialog() {
  const client = buildClients().find(item => item.phone === selectedClientPhone);
  if (!client || !clientProfileDetailsState.available || !clientProfileDetailsState.canEdit) return;
  $('#clientMoreDialog')?.close();
  $('#clientIdentityName').value = client.name || '';
  $('#clientIdentityPhone').value = newBookingClientPhoneLabel(client.phone, client.displayPhone);
  clearFormError('#clientIdentityError');
  updateClientIdentityNote();
  $('#clientIdentityDialog').showModal();
  requestAnimationFrame(() => $('#clientIdentityName')?.focus({ preventScroll:true }));
}

function updateClientIdentityNote() {
  const nextPhone = normalizePhone($('#clientIdentityPhone')?.value);
  const phoneChanged = Boolean(nextPhone && nextPhone !== selectedClientPhone);
  $('#clientIdentityNote').textContent = phoneChanged
    ? 'Карточка и история сохранятся. Вход клиента по номеру не переносится автоматически.'
    : 'Изменения применятся к карточке и записям клиента.';
}

function moveClientMapEntry(map, oldPhone, newPhone) {
  if (!(map instanceof Map) || oldPhone === newPhone || !map.has(oldPhone)) return;
  const value = map.get(oldPhone);
  map.delete(oldPhone);
  map.set(newPhone, value && typeof value === 'object' ? { ...value, client_phone:newPhone } : value);
}

function applyClientIdentityLocally(oldPhone, newPhone, newName) {
  allBookings.forEach(item => {
    if (!isScheduleBlock(item) && String(item.organization_id || '') === String(activeClientOrganizationId || '') && normalizePhone(item.client_phone) === oldPhone) {
      item.client_name = newName;
      item.client_phone = newPhone;
    }
  });
  importedBookingHistory.forEach(item => {
    if (String(item.organization_id || '') === String(activeClientOrganizationId || '') && normalizePhone(item.client_phone) === oldPhone) {
      item.client_name = newName;
      item.client_phone = newPhone;
    }
  });
  importedClients.forEach(item => {
    if (normalizePhone(item.phone || item.display_phone) !== oldPhone) return;
    item.phone = newPhone;
    item.display_phone = newPhone;
    item.name = newName;
    if ('client_name' in item) item.client_name = newName;
  });
  [clientNotes,clientLabels,clientAvatars,pendingClientNotes,pendingClientLabels].forEach(map => moveClientMapEntry(map, oldPhone, newPhone));
  selectedClientPhone = newPhone;
  clientProfileDetailsState = normalizedClientProfileDetails({ ...clientProfileDetailsState, client_phone:newPhone, available:true });
  providerBookingViewRevisions.delete('bookings');
  updateBookingStats();
  renderBookings();
  renderClients();
  renderClientDetail(newPhone, { preserveReturn:true });
}

async function saveClientIdentity(event) {
  event?.preventDefault?.();
  if (!requireWrites() || !clientProfileDetailsState.available || !clientProfileDetailsState.canEdit) return;
  const oldPhone = selectedClientPhone;
  const newPhone = normalizePhone($('#clientIdentityPhone').value);
  const newName = $('#clientIdentityName').value.trim().replace(/\s+/g, ' ');
  clearFormError('#clientIdentityError');
  if (newName.length < 2 || newName.length > 80) {
    showFormError('#clientIdentityError', 'Укажите имя от 2 до 80 символов.');
    $('#clientIdentityName').focus();
    return;
  }
  if (!/^7\d{10}$/.test(newPhone)) {
    showFormError('#clientIdentityError', 'Укажите российский номер телефона полностью.');
    $('#clientIdentityPhone').focus();
    return;
  }
  const button = $('#clientIdentityForm button[type="submit"]');
  button.disabled = true;
  const { data, error } = await db.rpc('save_minuta_client_identity_v134', {
    p_organization:activeClientOrganizationId,
    p_client_phone:oldPhone,
    p_client_name:newName,
    p_new_client_phone:newPhone
  });
  button.disabled = false;
  if (error) {
    const message = String(error.message || '');
    if (message.includes('client_phone_conflict')) showFormError('#clientIdentityError', 'Этот номер уже принадлежит другому клиенту.');
    else if (message.includes('client_metadata_conflict')) showFormError('#clientIdentityError', 'У нового номера уже есть личные данные. Проверьте карточку клиента.');
    else if (isMissingRpc(error, 'save_minuta_client_identity_v134')) showFormError('#clientIdentityError', 'Редактирование пока недоступно. Обновите страницу и повторите.');
    else showFormError('#clientIdentityError', 'Не удалось сохранить изменения. Повторите ещё раз.');
    return;
  }
  const savedPhone = normalizePhone(data?.client_phone || newPhone);
  const savedName = String(data?.client_name || newName).trim();
  $('#clientIdentityDialog').close();
  applyClientIdentityLocally(oldPhone, savedPhone, savedName);
  notify('Данные клиента сохранены');
}

async function saveClientBirthday(event, clear = false) {
  event?.preventDefault?.();
  if (!requireWrites() || !clientProfileDetailsState.available || !clientProfileDetailsState.canEdit) return;
  const organizationId = activeClientOrganizationId;
  const phone = selectedClientPhone;
  const birthday = clear ? null : ($('#clientBirthdayInput').value || null);
  if (birthday && (birthday > businessTodayIso() || birthday < '1900-01-01')) {
    notify('Проверьте дату рождения');
    return;
  }
  const submit = $('#clientBirthdayForm button[type="submit"]');
  submit.disabled = true;
  const { data, error } = await db.rpc('save_minuta_client_birthday_v119', {
    p_organization:organizationId,p_client_phone:phone,p_birthday:birthday
  });
  submit.disabled = false;
  if (error) { notify('Не удалось сохранить дату рождения'); return; }
  clientProfileDetailsState = normalizedClientProfileDetails({ ...clientProfileDetailsState, ...data, available:true });
  const client = buildClients().find(item => item.phone === phone);
  if (client) renderClientProfileDetails(client);
  $('#clientBirthdayDialog').close();
  notify(birthday ? 'Дата рождения сохранена' : 'Дата рождения удалена');
}

function openClientBlockConfirmation() {
  $('#clientMoreDialog')?.close();
  const blocked = clientProfileDetailsState.onlineBookingBlocked;
  $('#clientBlockTitle').textContent = blocked ? 'Разблокировать клиента?' : 'Заблокировать клиента?';
  $('#clientBlockDescription').textContent = blocked
    ? 'Клиент снова сможет самостоятельно записываться в эту организацию.'
    : 'Клиент не сможет самостоятельно записаться в эту организацию. История и данные сохранятся, а сотрудник сможет создать запись вручную.';
  const confirmButton = $('#clientBlockConfirm');
  confirmButton.textContent = blocked ? 'Разблокировать' : 'Заблокировать';
  confirmButton.classList.toggle('is-unblock', blocked);
  const reasonField = $('#clientBlockReasonField');
  const reasonInput = $('#clientBlockReason');
  const existingReason = $('#clientBlockExistingReason');
  reasonField.hidden = blocked || !clientProfileDetailsState.supportsBlockReason;
  reasonInput.value = '';
  existingReason.hidden = !blocked || !clientProfileDetailsState.onlineBookingBlockReason;
  existingReason.textContent = clientProfileDetailsState.onlineBookingBlockReason
    ? `Причина блокировки: ${clientProfileDetailsState.onlineBookingBlockReason}`
    : '';
  $('#clientBlockDialog').showModal();
}

async function confirmClientOnlineBlock() {
  if (!requireWrites() || !clientProfileDetailsState.available || !clientProfileDetailsState.canManageBlock) return;
  const organizationId = activeClientOrganizationId;
  const phone = selectedClientPhone;
  const blocked = !clientProfileDetailsState.onlineBookingBlocked;
  const button = $('#clientBlockConfirm');
  button.disabled = true;
  const reason = blocked ? String($('#clientBlockReason')?.value || '').trim() : '';
  let data;
  let error;
  if (clientProfileDetailsState.supportsBlockReason) {
    ({ data, error } = await db.rpc('set_minuta_client_online_booking_block_v135', {
      p_organization:organizationId,p_client_phone:phone,p_blocked:blocked,p_reason:reason || null
    }));
  } else {
    ({ data, error } = await db.rpc('set_minuta_client_online_booking_block_v119', {
      p_organization:organizationId,p_client_phone:phone,p_blocked:blocked
    }));
  }
  button.disabled = false;
  if (error) { notify('Не удалось изменить блокировку'); return; }
  clientProfileDetailsState = normalizedClientProfileDetails({ ...clientProfileDetailsState, ...data, available:true });
  const client = buildClients().find(item => item.phone === phone);
  if (client) renderClientProfileDetails(client);
  $('#clientBlockDialog').close();
  notify(blocked ? 'Онлайн-запись для клиента заблокирована' : 'Онлайн-запись для клиента разблокирована');
}

function resetClientProfileReturnContext() {
  clientProfileReturnContext = null;
  const back = $('#clientProfileBack');
  back?.classList.remove('is-booking-return');
  const label = back?.querySelector('span');
  if (label) label.textContent = 'Назад к клиентам';
}

function openClientProfileFromBooking(bookingId, requestedPhone = '') {
  const item = bookingSourceItems().find(booking => String(booking.id) === String(bookingId));
  const phone = normalizePhone(requestedPhone || item?.client_phone);
  if (!item || isScheduleBlock(item) || !phone || !buildClients().some(client => client.phone === phone)) {
    notify('Карточка клиента недоступна');
    return;
  }
  closeBookingSheet();
  const showClient = () => {
    clientProfileReturnContext = { bookingId:String(item.id), bookingDate:String(item.booking_date || '') };
    const back = $('#clientProfileBack');
    back?.classList.add('is-booking-return');
    const label = back?.querySelector('span');
    if (label) label.textContent = 'Назад к записи';
    setClientProfileDetailMode(true);
    renderClientDetail(phone, { preserveReturn:true });
  };
  const transition = setProviderView('clients');
  if (transition?.updateCallbackDone?.then) transition.updateCallbackDone.then(showClient).catch(showClient);
  else showClient();
}

function returnFromClientProfile() {
  const context = clientProfileReturnContext;
  resetClientProfileReturnContext();
  if (!context) {
    setClientProfileDetailMode(false);
    $$('.client-list-item[data-client-phone]').find(button => button.dataset.clientPhone === selectedClientPhone)?.focus();
    return;
  }
  setClientProfileDetailMode(false);
  const showBooking = () => {
    if (context.bookingDate) selectScheduleDate(context.bookingDate);
    openBookingSheet(context.bookingId);
  };
  const transition = setProviderView('bookings');
  if (transition?.updateCallbackDone?.then) transition.updateCallbackDone.then(showBooking).catch(showBooking);
  else showBooking();
}

function activateClientProfileJump(name, { scroll = true } = {}) {
  const targetName = ['history','services','notes','files'].includes(name) ? name : 'history';
  const profile = $('#clientProfileContent');
  if (profile) profile.dataset.clientProfileSection = targetName;
  $$('[data-client-profile-jump]').forEach(button => {
    const active = button.dataset.clientProfileJump === targetName;
    button.classList.toggle('is-active', active);
    button.setAttribute('aria-selected', String(active));
    button.tabIndex = active ? 0 : -1;
  });
  let target = $(`[data-client-profile-panel="${targetName}"]`);
  $$('[data-client-profile-panel]').forEach(panel => { panel.hidden = panel !== target; });
  const records = $('#clientRecords');
  if (targetName === 'notes') {
    $('#clientPreferencesDisclosure')?.setAttribute('open', '');
  }
  if (records && ['history','notes','files'].includes(targetName)) {
    if (records.parentElement !== target) target.append(records);
    clientRecordsController?.setView(targetName);
  }
  if (scroll) target?.scrollIntoView({ behavior:'smooth', block:'start' });
}

async function loadClientCommerceHistory(client) {
  const holder = $('#clientCommerceHistory');
  const list = $('#clientCommerceHistoryList');
  const organization = organizationController?.getActiveOrganization?.();
  if (!holder || !list || !client?.clientAccountId || !organization?.id
    || !['owner', 'admin'].includes(organization.current_role)) {
    if (holder) holder.hidden = true;
    return;
  }
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  const phone = client.phone;
  holder.hidden = false;
  list.innerHTML = '<p class="report-empty-inline">Загружаем покупки…</p>';
  const result = await db.rpc('get_minuta_client_commerce_v147', {
    p_organization:organization.id,
    p_client_account:client.clientAccountId
  });
  if (!sessionIsCurrent(userId, generation) || selectedClientPhone !== phone
    || organizationController?.getActiveOrganization?.()?.id !== organization.id) return;
  if (result.error) {
    holder.hidden = true;
    return;
  }
  const sales = result.data?.sales || [];
  $('#clientCommerceHistoryTitle').textContent = `Продажи · ${sales.length}`;
  const salesMarkup = sales.map(item => `<article class="client-commerce-row"><div><small>${new Date(item.occurred_at).toLocaleDateString('ru-RU')} · ${item.status === 'refunded' ? 'возвращено' : item.status === 'partially_refunded' ? 'частичный возврат' : 'оплачено'}</small><strong>${escapeHtml(item.item_name || 'Продажа')}</strong><span>${escapeHtml(String(item.quantity || 1))} шт. · ${money((Number(item.total_minor || 0) - Number(item.refunded_minor || 0)) / 100)}</span></div></article>`).join('');
  list.innerHTML = salesMarkup || '<p class="report-empty-inline">Оплаченных продаж пока нет.</p>';
}

function renderClientDetail(phone, { preserveReturn = false } = {}) {
  const client = buildClients().find(item => item.phone === phone);
  if (!client) return;
  if (!preserveReturn) resetClientProfileReturnContext();
  const clientChanged = selectedClientPhone !== phone;
  selectedClientPhone = phone;
  renderClients();
  $('#clientProfileEmpty').hidden = true;
  $('#clientProfileContent').hidden = false;
  $('#clientAvatar').innerHTML = clientAvatarContent(client.phone, client.name);
  const avatarInput = $('#clientAvatarInput');
  const avatarRemove = $('#clientAvatarRemove');
  const avatarAvailable = clientAvatarsRemoteAvailable;
  avatarInput.dataset.clientPhone = client.phone;
  avatarInput.disabled = !avatarAvailable;
  avatarInput.closest('.client-avatar-picker').hidden = !avatarAvailable;
  avatarRemove.dataset.removeClientAvatar = client.phone;
  avatarRemove.hidden = !avatarAvailable || !clientAvatar(client.phone);
  $('#clientName').textContent = client.name;
  $('#clientPhone').textContent = newBookingClientPhoneLabel(client.phone, client.displayPhone);
  $('#clientPhone').href = `tel:${client.phone}`;
  $('#clientQuickRepeat').dataset.quickRepeatClient = client.phone;
  $('#clientCommerceSale').dataset.commerceClientSale = client.clientAccountId || '';
  $('#clientCommerceSale').hidden = !client.clientAccountId || !['owner', 'admin'].includes(organizationController?.getActiveOrganization?.()?.current_role);
  $('#clientProfileBadges').innerHTML = clientBadgeMarkup(client.phone, { limit:4, showLabels:true });
  const labels = clientLabel(client.phone);
  applyClientHighlightClasses($('#clientProfileContent').closest('.client-profile'), client.phone, 'client-profile-');
  $('#clientLabelFavorite').checked = labels.favorite;
  $('#clientLabelVip').checked = labels.vip;
  $('#clientLabelAttention').checked = labels.attention;
  $('#clientFavoriteNote').value = labels.favorite_note;
  $('#clientVipNote').value = labels.vip_note;
  $('#clientAttentionReason').value = labels.attention_reason;
  $('#clientFavoriteNoteField').hidden = !labels.favorite;
  $('#clientVipNoteField').hidden = !labels.vip;
  $('#clientAttentionReasonField').hidden = !labels.attention;
  $('#clientAutomaticLabel').textContent = clientIsNew(client.phone) ? 'Новый клиент' : '';
  const noteValue = clientNotes.get(phone) || client.imported?.note || '';
  updateClientPreferencesPreview(phone, noteValue);
  if (clientChanged) {
    $('#clientPreferencesDisclosure').open = false;
    activateClientProfileJump('history', { scroll:false });
  }
  clearFormError('#clientLabelsError');
  const completedVisits = clientCompletedVisits(client);
  const facts = clientRelationshipFacts(client, completedVisits);
  const visits = facts.visits;
  renderClientFavoriteServices(completedVisits);
  const upcoming = clientUpcoming(client);
  const profileOrbit = $('#clientProfileOrbit');
  profileOrbit.style.setProperty('--client-level-progress', `${facts.progress.toFixed(4)}turn`);
  profileOrbit.dataset.clientLevel = String(facts.level);
  profileOrbit.classList.toggle('has-photo', Boolean(clientAvatar(client.phone)?.signed_url));
  profileOrbit.classList.toggle('is-max-level', facts.level === 4);
  profileOrbit.setAttribute('aria-label', facts.level ? `${facts.title}, ${facts.level} уровень` : facts.title);
  $('#clientRelationshipTitle').textContent = facts.title;
  $('#clientRelationshipLevel').textContent = facts.level ? `${facts.level} уровень` : '';
  const milestoneCard = $('#clientMilestoneCard');
  $('#clientMilestoneText').textContent = facts.milestone;
  const milestoneProgress = Math.round(facts.progress * 100);
  milestoneCard.classList.toggle('is-max-level', facts.level === 4);
  milestoneCard.style.setProperty('--client-level-width', `${milestoneProgress}%`);
  $('#clientMilestoneProgress').setAttribute('aria-valuenow', String(milestoneProgress));
  const reliabilityCard = $('#clientReliabilityCard');
  reliabilityCard.hidden = !facts.reliability?.needsAttention;
  reliabilityCard.dataset.severity = facts.reliability?.severity || '';
  $('#clientReliabilityTitle').textContent = facts.reliability?.title || 'Обратите внимание';
  $('#clientReliabilityText').textContent = facts.reliability?.needsAttention ? facts.reliability.label : '';
  $('#clientVisits').textContent = String(visits);
  $('#clientNext').textContent = upcoming ? `${new Date(`${upcoming.booking_date}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})} · ${String(upcoming.booking_time).slice(0,5)}` : 'Нет';
  $('#clientNextDetails').textContent = upcoming ? serviceName(upcoming.services?.name || 'Услуга') : 'Будущих записей нет';
  $('#clientSpent').textContent = money(completedVisits.reduce((sum, item) => sum + Math.max(0, Number(bookingOutcome(item).amount_rub || 0)), 0));
  const lastVisit = [...completedVisits].sort((a, b) => `${b.booking_date}${b.booking_time}`.localeCompare(`${a.booking_date}${a.booking_time}`))[0];
  const lastVisitDate = lastVisit?.booking_date || client.imported?.last_visit_on || '';
  $('#clientLastVisit').textContent = lastVisitDate ? new Date(`${lastVisitDate}T12:00:00`).toLocaleDateString('ru-RU', { day:'numeric',month:'short',year:'numeric' }) : '—';
  void loadClientProfileDetails(client);
  void clientBenefitLifecycleController?.setClient(client, organizationController?.getActiveOrganization?.());
  void loadClientCommerceHistory(client);
  batchBookingsController?.setClient(client);
  clientFieldsController?.setClient(client.phone);
  $('#clientNote').value = noteValue;
  const history = [...client.bookings].sort((a,b) => `${b.booking_date}${b.booking_time}`.localeCompare(`${a.booking_date}${a.booking_time}`));
  const clientDebt = client.bookings.filter(item => item.status !== 'cancelled' && bookingOutcome(item).visit_status === 'completed')
    .reduce((sum,item) => sum + Math.max(0,bookingCalculatedValue(item)-Number(bookingOutcome(item).amount_rub || 0)),0);
  $('#clientDebt').textContent = money(clientDebt);
  $('#clientDebtStatus').hidden = clientDebt <= 0;
  clientResultsController.setClient({phone:client.phone,bookings:history});
  clientRecordsController.setClient({phone:client.phone,bookings:history.map(item => {
    const outcome = bookingOutcome(item);
    const received = Number(outcome.amount_rub || 0);
    const debt = item.status !== 'cancelled' && outcome.visit_status === 'completed' ? Math.max(0,bookingCalculatedValue(item)-received) : 0;
    return {id:item.id,at:`${item.booking_date}T${String(item.booking_time).slice(0,8)}+04:00`,
      title:serviceName(item.services?.name || 'Услуга'),status:bookingStatus(item),
      payment:`Получено ${money(received)}${debt ? ` · Долг ${money(debt)}` : ''}${item.is_imported_history ? ' · Из импортированной истории' : ''}`};
  })});
  if (clientChanged) activateClientProfileJump('history', { scroll:false });
}

async function loadClientNotes() {
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  if (!userId) return { ok: false };
  const { data, error } = await db.from('client_notes').select('client_phone,note').eq('performer_id', userId);
  if (!sessionIsCurrent(userId, generation)) return { ok: false, stale: true };
  if (error) return { ok: false };
  clientNotes = new Map((data || []).map(item => [normalizePhone(item.client_phone), item.note]));
  for (const [phone, note] of pendingClientNotes) clientNotes.set(phone, note);
  renderBookings();
  renderClients();
  return { ok: true };
}

async function signedClientAvatarUrl(path) {
  const { data, error } = await db.storage.from(CLIENT_AVATAR_BUCKET).createSignedUrl(path, 3600);
  return { url:error ? '' : data?.signedUrl || '', expiresAt:Date.now() + 55 * 60 * 1000 };
}

async function loadClientAvatars() {
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  if (!userId) return { ok:false, optional:true };
  const { data, error } = await db.from('client_avatars').select('client_phone,storage_path,width,height,updated_at').eq('performer_id', userId);
  if (!sessionIsCurrent(userId, generation)) return { ok:false, optional:true, stale:true };
  if (error) {
    clientAvatarsLoaded = false;
    clientAvatarsRemoteAvailable = false;
    clientAvatars = new Map();
    renderClients();
    if (selectedClientPhone) renderClientDetail(selectedClientPhone);
    return { ok:false, optional:true };
  }
  const entries = await Promise.all((data || []).map(async item => {
    const clientPhone = normalizePhone(item.client_phone);
    const cached = clientAvatars.get(clientPhone);
    if (cached?.storage_path === item.storage_path && cached.signed_url && cached.signed_url_expires_at > Date.now()) {
      return { ...item, client_phone:clientPhone, signed_url:cached.signed_url, signed_url_expires_at:cached.signed_url_expires_at };
    }
    const signed = await signedClientAvatarUrl(item.storage_path);
    return { ...item, client_phone:clientPhone, signed_url:signed.url, signed_url_expires_at:signed.expiresAt };
  }));
  if (!sessionIsCurrent(userId, generation)) return { ok:false, optional:true, stale:true };
  clientAvatars = new Map(entries.filter(item => item.client_phone).map(item => [item.client_phone, item]));
  clientAvatarsLoaded = true;
  clientAvatarsRemoteAvailable = true;
  renderClients();
  if (selectedClientPhone) renderClientDetail(selectedClientPhone);
  return { ok:true, optional:true };
}

async function prepareClientAvatar(file) {
  const image = await decodePortfolioImage(file);
  const sourceWidth = image.width;
  const sourceHeight = image.height;
  const side = Math.min(sourceWidth, sourceHeight);
  const edge = Math.max(1, Math.min(CLIENT_AVATAR_MAX_EDGE, side));
  const sourceX = Math.max(0, (sourceWidth - side) / 2);
  const sourceY = Math.max(0, (sourceHeight - side) / 2);
  const canvas = document.createElement('canvas');
  canvas.width = edge;
  canvas.height = edge;
  const context = canvas.getContext('2d', { alpha:false });
  context.fillStyle = '#fff';
  context.fillRect(0, 0, edge, edge);
  context.drawImage(image, sourceX, sourceY, side, side, 0, 0, edge, edge);
  image.close?.();
  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', .84));
  if (!blob || blob.size > CLIENT_AVATAR_OUTPUT_LIMIT) throw new Error('avatar_too_large');
  return { blob, width:edge, height:edge };
}

async function saveClientAvatar(input) {
  const file = input.files?.[0];
  if (!file) return;
  if (!requireWrites() || !clientAvatarsRemoteAvailable) { input.value = ''; return; }
  const phone = normalizePhone(input.dataset.clientPhone);
  if (!phone) { input.value = ''; notify('Не удалось определить клиента'); return; }
  if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { input.value = ''; notify('Выберите фото JPEG, PNG или WebP'); return; }
  if (file.size > CLIENT_AVATAR_INPUT_LIMIT) { input.value = ''; notify('Фото должно быть не больше 8 МБ'); return; }
  const userId = currentUser.id;
  const generation = sessionGeneration;
  const bookingId = input.dataset.bookingId || '';
  const existing = clientAvatar(phone);
  input.disabled = true;
  let path = '';
  try {
    const prepared = await prepareClientAvatar(file);
    if (!sessionIsCurrent(userId, generation)) return;
    path = `${userId}/${phone}/avatar.webp`;
    const { error: uploadError } = await db.storage.from(CLIENT_AVATAR_BUCKET).upload(path, prepared.blob, { contentType:'image/webp', cacheControl:'3600', upsert:true });
    if (!sessionIsCurrent(userId, generation)) return;
    if (uploadError) throw uploadError;
    const { error: saveError } = await db.from('client_avatars').upsert({ performer_id:userId, client_phone:phone, storage_path:path, width:prepared.width, height:prepared.height, updated_at:new Date().toISOString() }, { onConflict:'performer_id,client_phone' });
    if (!sessionIsCurrent(userId, generation)) return;
    if (saveError) {
      if (!existing) await db.storage.from(CLIENT_AVATAR_BUCKET).remove([path]);
      throw saveError;
    }
    const signed = await signedClientAvatarUrl(path);
    if (!sessionIsCurrent(userId, generation)) return;
    clientAvatars.set(phone, { client_phone:phone, storage_path:path, width:prepared.width, height:prepared.height, signed_url:signed.url, signed_url_expires_at:signed.expiresAt });
    renderBookingData();
    if (bookingId && !$('#bookingSheet').hidden) openBookingSheet(bookingId);
    notify(existing ? 'Фото клиента обновлено' : 'Фото клиента добавлено');
  } catch {
    notify('Не удалось сохранить фото. Попробуйте другое изображение.');
  } finally {
    input.value = '';
    input.disabled = false;
    applyWriteAvailability();
  }
}

async function removeClientAvatar(phone, bookingId = '', options = {}) {
  if (!requireWrites() || !clientAvatarsRemoteAvailable) return;
  const normalizedPhone = normalizePhone(phone);
  const existing = clientAvatar(normalizedPhone);
  if (!existing || (options.confirm !== false && !confirm('Удалить фото клиента?'))) return;
  const userId = currentUser.id;
  const generation = sessionGeneration;
  const { error:storageError } = await db.storage.from(CLIENT_AVATAR_BUCKET).remove([existing.storage_path]);
  if (!sessionIsCurrent(userId, generation)) return;
  if (storageError) { notify('Не удалось удалить файл фото клиента'); return; }
  const { error } = await db.from('client_avatars').delete().eq('performer_id', userId).eq('client_phone', normalizedPhone);
  if (!sessionIsCurrent(userId, generation)) return;
  if (error) { notify('Файл удалён, но карточка фото не очистилась. Повторите удаление.'); return; }
  clientAvatars.delete(normalizedPhone);
  renderBookingData();
  if (bookingId && !$('#bookingSheet').hidden) openBookingSheet(bookingId);
  if (!options.silent) notify('Фото клиента удалено');
}

