function shouldTryCompatibleProviderRead(error) {
  return Boolean(error) && !window.MinutaProviderReadFetch.isConnectionError(error);
}

async function loadBookings(options = {}) {
  const holder = $('#providerBookings');
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  const revision = ++bookingsRequestRevision;
  if (!userId) return { ok: false };
  const cachePromise = readProviderCache('bookings', userId);
  let cached = null;
  let cacheShown = false;
  let networkFinished = false;
  const showCached = async () => {
    const candidate = await cachePromise;
    if (networkFinished || !candidate?.data || !sessionIsCurrent(userId, generation) || revision !== bookingsRequestRevision) return null;
    cached = candidate;
    if (bookingDataSignature(candidate.data) !== bookingDataSignature()) {
      applyCachedBookings(candidate);
      cacheShown = true;
    }
    return candidate;
  };
  if (!options.silent) holder.innerHTML = '<div class="loading-state"><i></i><span>Загружаем записи…</span></div>';
  if (!navigator.onLine) {
    const offlineCache = await showCached();
    return offlineCache ? { ok: false, cached: true, savedAt: offlineCache.savedAt } : { ok: false };
  }
  let { data, error } = await queryAllProviderBookings(userId, 'id,organization_id,location_id,booking_code,request_id,service_id,series_id,series_occurrence,client_name,client_phone,booking_date,booking_time,duration_minutes,original_price_rub,total_price_rub,status,cancellation_reason,created_at,reschedule_count,deposit_amount_rub,payment_status,payment_url,booking_source,created_by_user_id,created_by_role,services(name,price_rub,duration_minutes),booking_series(occurrence_count)');
  if (shouldTryCompatibleProviderRead(error)) ({ data, error } = await queryAllProviderBookings(userId, 'id,organization_id,location_id,booking_code,request_id,service_id,client_name,client_phone,booking_date,booking_time,duration_minutes,original_price_rub,total_price_rub,status,cancellation_reason,created_at,reschedule_count,deposit_amount_rub,payment_status,payment_url,booking_source,created_by_user_id,created_by_role,services(name,price_rub,duration_minutes)'));
  if (shouldTryCompatibleProviderRead(error)) ({ data, error } = await queryAllProviderBookings(userId, 'id,booking_code,request_id,service_id,client_name,client_phone,booking_date,booking_time,duration_minutes,original_price_rub,total_price_rub,status,created_at,reschedule_count,deposit_amount_rub,payment_status,payment_url,services(name,price_rub,duration_minutes)'));
  if (shouldTryCompatibleProviderRead(error)) ({ data, error } = await queryAllProviderBookings(userId, 'id,booking_code,request_id,service_id,client_name,client_phone,booking_date,booking_time,duration_minutes,status,created_at,reschedule_count,deposit_amount_rub,payment_status,payment_url,services(name,price_rub,duration_minutes)'));
  networkFinished = true;
  if (!sessionIsCurrent(userId, generation) || revision !== bookingsRequestRevision) return { ok: false, stale: true };
  if (error) {
    cached ||= await cachePromise;
    if (!sessionIsCurrent(userId, generation) || revision !== bookingsRequestRevision) return { ok:false, stale:true };
    if (cached?.data) {
      if (!cacheShown) applyCachedBookings(cached);
      return { ok: false, cached: true, savedAt:cached.savedAt };
    }
    holder.innerHTML = '<div class="provider-empty"><strong>Не удалось загрузить записи</strong><small>Соединение с сервером не установлено. Попробуйте ещё раз.</small></div>';
    return { ok: false };
  }
  const previousSignature = bookingDataSignature();
  allBookings = data || [];
  await loadAutomaticBookingBreaks(selectedDate, userId, generation);
  if (!sessionIsCurrent(userId, generation) || revision !== bookingsRequestRevision) return { ok: false, stale: true };
  if (!options.deferPresentation) await loadRemoteBookingColors(userId, generation);
  if (!sessionIsCurrent(userId, generation) || revision !== bookingsRequestRevision) return { ok: false, stale: true };
  const savedSnapshot = await saveProviderCache('bookings', allBookings, userId);
  if (!sessionIsCurrent(userId, generation) || revision !== bookingsRequestRevision) return { ok: false, stale: true };
  bookingsSnapshotSavedAt = String(savedSnapshot?.savedAt || new Date().toISOString());
  bookingsSnapshotFromCache = false;
  if (!providerBookingRenderRevision || previousSignature !== bookingDataSignature()) renderBookingData();
  if (!options.skipTimelineMoveRecovery) {
    const recover = () => { void recoverPendingTimelineBookingMove(); };
    if (typeof queueMicrotask === 'function') queueMicrotask(recover);
    else if (typeof setTimeout === 'function') setTimeout(recover, 0);
  }
  return { ok: true };
}

function waitlistPeriodLabel(value) {
  return ({ any: 'Любое время', morning: 'Утро · 10:00–12:00', day: 'День · 12:00–17:00', evening: 'Вечер · 17:00–20:00' })[value] || 'Любое время';
}

function renderWaitlist() {
  const holder = $('#waitlistList');
  if (!holder) return;
  const active = waitlistRequests.filter(item => ['waiting', 'contacted'].includes(item.status));
  const count = $('#waitlistCount');
  count.textContent = String(active.length);
  count.hidden = !active.length;
  const badge = $('#waitlistBadge');
  badge.textContent = String(active.length);
  badge.hidden = !active.length;
  if (!waitlistLoaded) {
    holder.innerHTML = '<div class="provider-empty compact-empty"><strong>Загружаем лист ожидания…</strong><small>Данные появятся здесь через несколько секунд.</small></div>';
    return;
  }
  if (!waitlistRemoteAvailable) {
    holder.innerHTML = '<div class="provider-empty"><strong>Лист ожидания недоступен</strong><small>Обновите страницу после установки серверного обновления.</small></div>';
    return;
  }
  if (!active.length) {
    const clientPageUrl = $('.provider-client-link')?.href || 'https://primetime-booking.github.io/';
    holder.innerHTML = `<div class="provider-empty compact-empty waitlist-empty-state"><strong>Заявок пока нет</strong><small>Когда клиенту не подойдёт свободное время, его заявка появится здесь.</small><div class="provider-empty-actions"><a class="primary compact-button provider-client-link" href="${escapeHtml(clientPageUrl)}" target="_blank" rel="noopener noreferrer">Открыть страницу клиента</a></div></div>`;
    return;
  }
  const statusLabels = { waiting: 'Ожидает', contacted: 'Связались' };
  holder.innerHTML = active.map(item => {
    const date = new Date(`${item.desired_date}T12:00:00`).toLocaleDateString('ru-RU', { weekday: 'short', day: 'numeric', month: 'long' });
    const phone = String(item.client_phone || '');
    const whatsapp = phone.replace(/\D/g, '') ? `https://wa.me/${phone.replace(/\D/g, '')}` : '';
    return `<article class="waitlist-provider-card" data-waitlist-scope="${item.organization_id ? 'organization' : 'personal'}"><div class="waitlist-provider-date"><strong>${escapeHtml(date)}</strong><span>${escapeHtml(waitlistPeriodLabel(item.time_period))}</span></div><div class="waitlist-provider-client"><small>${escapeHtml([item.services?.name || 'Услуга',item.locations?.name,item.performer_profiles?.display_name].filter(Boolean).join(' · '))}</small><strong>${escapeHtml(item.client_name)}</strong><a href="tel:+${escapeHtml(phone)}">+${escapeHtml(phone)}</a></div><span class="waitlist-status status-${escapeHtml(item.status)}">${statusLabels[item.status] || escapeHtml(item.status)}</span><div class="waitlist-provider-actions">${whatsapp ? `<a class="secondary-button" href="${whatsapp}" target="_blank" rel="noopener noreferrer">WhatsApp</a>` : ''}${item.status === 'waiting' ? `<button class="secondary-button" type="button" data-waitlist-status="contacted" data-waitlist-id="${item.id}">Связались</button>` : ''}<button class="primary compact-button" type="button" data-waitlist-status="booked" data-waitlist-id="${item.id}">Записан</button><button class="booking-cancel-action" type="button" data-waitlist-status="closed" data-waitlist-id="${item.id}">Закрыть</button></div></article>`;
  }).join('');
  applyWriteAvailability();
}

async function loadWaitlist() {
  const userId = currentUser?.id;
  const generation = sessionGeneration;
  const organizationId = organizationController.getActiveOrganization()?.id || null;
  if (!userId) return { ok: false, optional: true };
  const { data, error } = await db.from('booking_waitlist_requests')
    .select('id,request_code,client_name,client_phone,desired_date,time_period,status,created_at,services(name)')
    .eq('performer_id', userId)
    .in('status', ['waiting', 'contacted'])
    .order('desired_date', { ascending: true })
    .order('created_at', { ascending: true });
  let scoped = { data:[],error:null };
  if (organizationId && !bookingUsesDemoData()) {
    scoped = await db.from('organization_waitlist_requests')
      .select('id,organization_id,request_code,client_name,client_phone,desired_date,time_period,status,created_at,services(name),locations(name),performer_profiles(display_name)')
      .eq('organization_id',organizationId).in('status',['waiting','contacted'])
      .order('desired_date',{ascending:true}).order('created_at',{ascending:true});
  }
  if (!sessionIsCurrent(userId,generation) || (organizationController.getActiveOrganization()?.id || null) !== organizationId) return { ok:false,optional:true,stale:true };
  waitlistRemoteAvailable = !error && !scoped.error;
  waitlistLoaded = true;
  waitlistRequests = waitlistRemoteAvailable ? [...(data || []),...(scoped.data || [])]
    .sort((a,b)=>a.desired_date.localeCompare(b.desired_date) || a.created_at.localeCompare(b.created_at)) : [];
  renderWaitlist();
  return { ok:waitlistRemoteAvailable,optional:true };
}

document.addEventListener('pointerdown', event => {
  const bookingCard = event.target.closest('.timeline-booking[data-open-booking]');
  if (bookingCard && !bookingUsesDemoData() && !bookingCard.matches('[data-imported-history]')) {
    beginTimelineBookingDrag(event, bookingCard);
    return;
  }
  const swipeSurface = event.target.closest('#providerBookings');
  if (swipeSurface) beginScheduleDaySwipe(event, swipeSurface);
});

document.addEventListener('contextmenu', event => {
  if (event.target.closest('.timeline-booking[data-open-booking]')) event.preventDefault();
});

document.addEventListener('pointermove', event => {
  if (timelineBookingDrag?.pointerId === event.pointerId) {
    const state = timelineBookingDrag;
    const deltaX = event.clientX - state.startX;
    const deltaY = event.clientY - state.startY;
    const distance = Math.hypot(deltaX, deltaY);
    if (!state.active) {
      if (state.pointerType === 'mouse' && distance >= TIMELINE_DRAG_THRESHOLD_PX) activateTimelineBookingDrag(state);
      else if (state.pointerType !== 'mouse' && distance > 12) {
        if (Math.abs(deltaX) > Math.abs(deltaY) && currentFilter === 'day') {
          const surface = state.card.closest('#providerBookings');
          const swipeState = { pointerId:event.pointerId, surface, startX:state.startX, startY:state.startY, active:true };
          finishTimelineBookingDrag();
          if (surface) {
            scheduleDaySwipe = swipeState;
            surface.setPointerCapture?.(event.pointerId);
            surface.classList.add('is-day-swiping');
            surface.style.setProperty('--day-swipe-x', `${Math.max(-72, Math.min(72, deltaX * .28))}px`);
            event.preventDefault();
          }
          return;
        }
        finishTimelineBookingDrag();
        return;
      }
    }
    if (state.active) {
      event.preventDefault();
      updateTimelineBookingDrag(state, event.clientY);
    }
    return;
  }
  if (scheduleDaySwipe?.pointerId !== event.pointerId) return;
  const state = scheduleDaySwipe;
  const deltaX = event.clientX - state.startX;
  const deltaY = event.clientY - state.startY;
  if (!state.active && Math.hypot(deltaX, deltaY) > 10) {
    if (Math.abs(deltaY) >= Math.abs(deltaX)) {
      state.surface.classList.remove('is-day-swiping');
      try { state.surface.releasePointerCapture(state.pointerId); } catch {}
      scheduleDaySwipe = null;
      return;
    }
    state.active = true;
    state.surface.setPointerCapture?.(event.pointerId);
    state.surface.classList.add('is-day-swiping');
  }
  if (!state.active) return;
  event.preventDefault();
  state.surface.style.setProperty('--day-swipe-x', `${Math.max(-72, Math.min(72, deltaX * .28))}px`);
});

document.addEventListener('touchmove', event => {
  const state = timelineBookingDrag;
  if (!state?.active || state.pointerType !== 'touch' || event.touches.length !== 1) return;
  event.preventDefault();
  updateTimelineBookingDrag(state, event.touches[0].clientY);
}, { passive:false });

document.addEventListener('pointerup', event => {
  if (timelineBookingDrag?.pointerId === event.pointerId) {
    const state = timelineBookingDrag;
    if (!state.active) {
      finishTimelineBookingDrag();
      return;
    }
    gestureClickSuppressedUntil = Date.now() + 450;
    finishTimelineBookingDrag({ restore:false });
    void confirmTimelineBookingMove(state);
    return;
  }
  if (scheduleDaySwipe?.pointerId === event.pointerId) finishScheduleDaySwipe(scheduleDaySwipe, event);
});

document.addEventListener('pointercancel', event => {
  if (timelineBookingDrag?.pointerId === event.pointerId) finishTimelineBookingDrag();
  if (scheduleDaySwipe?.pointerId === event.pointerId) finishScheduleDaySwipe(scheduleDaySwipe, { ...event, clientX:scheduleDaySwipe.startX });
});

document.addEventListener('keydown', event => {
  const card = event.target.closest?.('.timeline-booking[data-timeline-movable]');
  if (!card || !event.shiftKey || !['ArrowUp', 'ArrowDown'].includes(event.key) || timelineMovePending || timelineMoveConfirmationPending) return;
  const item = allBookings.find(booking => booking.id === card.dataset.openBooking);
  const stage = card.closest('.timeline-stage');
  if (!item || !stage) return;
  event.preventDefault();
  event.stopPropagation();
  const step = Math.max(1, scheduleStepForDate(selectedDate));
  const raw = minutesFromTime(item.booking_time) + (event.key === 'ArrowUp' ? -step : step);
  const target = timelineMagneticTarget(item, stage, raw, selectedDate);
  const state = {
    item:timelineBookingMoveSnapshot(item),
    bookingId:item.id,
    date:selectedDate,
    targetMinute:target.minute,
    duration:Math.max(1, Number(item.duration_minutes || item.services?.duration_minutes || 60)),
    issue:target.issue
  };
  void confirmTimelineBookingMove(state).finally(() => requestAnimationFrame(() => {
    document.querySelector(`.timeline-booking[data-open-booking="${CSS.escape(String(item.id))}"]`)?.focus();
  }));
});

