function providerAssistantIsoDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ''));
  if (!match) return '';
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const parsed = new Date(Date.UTC(year, month - 1, day));
  return parsed.getUTCFullYear() === year && parsed.getUTCMonth() === month - 1 && parsed.getUTCDate() === day ? match[0] : '';
}

function providerAssistantNumber(value, fallback = 0, minimum = 0, maximum = Number.MAX_SAFE_INTEGER) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(minimum, Math.min(maximum, number)) : fallback;
}

function providerAssistantCurrentMinute() {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone:'Europe/Samara', hour:'2-digit', minute:'2-digit', hour12:false }).formatToParts(new Date());
  const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return (Number(values.hour) * 60) + Number(values.minute);
}

function providerAssistantLexiconKey() {
  const organizationId = organizationController.getActiveOrganization()?.id;
  if (!currentUser?.id || !organizationId) return '';
  return `minuta-assistant-lexicon-v1-${currentUser.id}-${organizationId}`;
}

function providerAssistantLexicon() {
  const key = providerAssistantLexiconKey();
  if (!key) return [];
  try {
    const stored = JSON.parse(localStorage.getItem(key) || '[]');
    return (Array.isArray(stored) ? stored : []).map(rule => ({
      from:String(rule?.from || '').toLocaleLowerCase('ru-RU').replace(/ё/g, 'е').replace(/[^а-яa-z\s-]/gi, '').replace(/\s+/g, ' ').trim().slice(0, 80),
      to:String(rule?.to || '').toLocaleLowerCase('ru-RU').replace(/ё/g, 'е').replace(/[^а-яa-z\s-]/gi, '').replace(/\s+/g, ' ').trim().slice(0, 120)
    })).filter(rule => rule.from && rule.to && rule.from !== rule.to).slice(-40);
  } catch {
    return [];
  }
}

function rememberProviderAssistantCorrections(rules = []) {
  const key = providerAssistantLexiconKey();
  if (!key || !Array.isArray(rules)) return { ok:false };
  const merged = new Map(providerAssistantLexicon().map(rule => [rule.from, rule]));
  rules.slice(0, 3).forEach(rule => {
    const from = String(rule?.from || '').toLocaleLowerCase('ru-RU').replace(/ё/g, 'е').replace(/[^а-яa-z\s-]/gi, '').replace(/\s+/g, ' ').trim().slice(0, 80);
    const to = String(rule?.to || '').toLocaleLowerCase('ru-RU').replace(/ё/g, 'е').replace(/[^а-яa-z\s-]/gi, '').replace(/\s+/g, ' ').trim().slice(0, 120);
    if (from && to && from !== to) merged.set(from, { from, to });
  });
  try {
    localStorage.setItem(key, JSON.stringify([...merged.values()].slice(-40)));
    return { ok:true };
  } catch {
    return { ok:false };
  }
}

function providerAssistantPreferencesKey() {
  const organizationId = organizationController.getActiveOrganization()?.id;
  if (!currentUser?.id || !organizationId) return '';
  return `minuta-assistant-preferences-v1-${currentUser.id}-${organizationId}`;
}

function providerAssistantPreferences() {
  const key = providerAssistantPreferencesKey();
  if (!key) return { observationCount:0, preferredTime:'', preferredTimeWindow:'', preferredServiceId:'', usualDurations:{} };
  try {
    const stored = JSON.parse(localStorage.getItem(key) || '{}');
    const timeCount = providerAssistantNumber(stored?.timeCount, 0, 0, 100);
    const totalMinutes = providerAssistantNumber(stored?.totalMinutes, 0, 0, 1439 * 100);
    const serviceCounts = stored?.serviceCounts && typeof stored.serviceCounts === 'object' && !Array.isArray(stored.serviceCounts) ? stored.serviceCounts : {};
    const durationStats = stored?.durationStats && typeof stored.durationStats === 'object' && !Array.isArray(stored.durationStats) ? stored.durationStats : {};
    const knownServiceIds = new Set(ownServices.filter(item => item.active).map(item => String(item.id)));
    const preferredServiceId = Object.entries(serviceCounts)
      .filter(([id]) => knownServiceIds.has(String(id)))
      .map(([id, count]) => ({ id:String(id), count:providerAssistantNumber(count, 0, 0, 100) }))
      .sort((left, right) => right.count - left.count)[0]?.id || '';
    const average = timeCount ? Math.round((totalMinutes / timeCount) / 30) * 30 : 0;
    const preferredTime = timeCount >= 2 ? `${String(Math.floor(Math.min(1439, average) / 60)).padStart(2, '0')}:${String(Math.min(1439, average) % 60).padStart(2, '0')}` : '';
    const preferredTimeWindow = !preferredTime ? '' : average < 12 * 60 ? 'morning' : average < 17 * 60 ? 'day' : 'evening';
    const usualDurations = {};
    Object.entries(durationStats).forEach(([id, value]) => {
      if (!knownServiceIds.has(String(id)) || !value || typeof value !== 'object') return;
      const count = providerAssistantNumber(value.count, 0, 0, 100);
      const total = providerAssistantNumber(value.total, 0, 0, 480 * 100);
      if (count >= 2) usualDurations[String(id)] = Math.max(1, Math.min(480, Math.round(total / count)));
    });
    return { observationCount:timeCount, preferredTime, preferredTimeWindow, preferredServiceId, usualDurations };
  } catch {
    return { observationCount:0, preferredTime:'', preferredTimeWindow:'', preferredServiceId:'', usualDurations:{} };
  }
}

function rememberProviderAssistantPreference(plan = {}) {
  const key = providerAssistantPreferencesKey();
  if (!key || !plan || typeof plan !== 'object' || Array.isArray(plan)) return { ok:false };
  const time = /^([01]\d|2[0-3]):[0-5]\d$/.test(String(plan.time || '')) ? String(plan.time) : '';
  const serviceId = ownServices.some(item => item.active && String(item.id) === String(plan.serviceId || '')) ? String(plan.serviceId) : '';
  const duration = Math.max(0, Math.min(480, Math.round(Number(plan.durationMinutes) || 0)));
  if (!time && !serviceId) return { ok:false };
  let stored = {};
  try { stored = JSON.parse(localStorage.getItem(key) || '{}'); } catch { stored = {}; }
  let timeCount = providerAssistantNumber(stored?.timeCount, 0, 0, 100);
  let totalMinutes = providerAssistantNumber(stored?.totalMinutes, 0, 0, 1439 * 100);
  const serviceCounts = stored?.serviceCounts && typeof stored.serviceCounts === 'object' && !Array.isArray(stored.serviceCounts) ? { ...stored.serviceCounts } : {};
  const durationStats = stored?.durationStats && typeof stored.durationStats === 'object' && !Array.isArray(stored.durationStats) ? { ...stored.durationStats } : {};
  if (timeCount >= 100) { timeCount = Math.floor(timeCount / 2); totalMinutes = Math.round(totalMinutes / 2); }
  if (time) {
    const [hour, minute] = time.split(':').map(Number);
    timeCount += 1;
    totalMinutes += hour * 60 + minute;
  }
  if (serviceId) serviceCounts[serviceId] = Math.min(100, providerAssistantNumber(serviceCounts[serviceId], 0, 0, 100) + 1);
  if (serviceId && duration) {
    const previous = durationStats[serviceId] && typeof durationStats[serviceId] === 'object' ? durationStats[serviceId] : {};
    let count = providerAssistantNumber(previous.count, 0, 0, 100);
    let total = providerAssistantNumber(previous.total, 0, 0, 480 * 100);
    if (count >= 100) { count = Math.floor(count / 2); total = Math.round(total / 2); }
    durationStats[serviceId] = { count:count + 1, total:total + duration };
  }
  try {
    localStorage.setItem(key, JSON.stringify({ timeCount, totalMinutes, serviceCounts, durationStats }));
    return { ok:true, preferences:providerAssistantPreferences() };
  } catch {
    return { ok:false };
  }
}

function clearProviderAssistantPreferences() {
  const key = providerAssistantPreferencesKey();
  if (!key) return { ok:false };
  try { localStorage.removeItem(key); return { ok:true }; }
  catch { return { ok:false }; }
}

function setInventorySection(nextSection = 'balances', reveal = false) {
  const allowed = new Set(['balances', 'catalog', 'operations', 'history']);
  const section = allowed.has(nextSection) ? nextSection : 'balances';
  $$('[data-inventory-section]').forEach(button => {
    const active = button.dataset.inventorySection === section;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', String(active));
    if (active && reveal && typeof button.scrollIntoView === 'function')
      button.scrollIntoView({ behavior:'smooth', block:'nearest', inline:'nearest' });
  });
  $$('[data-inventory-pane]').forEach(pane => {
    pane.hidden = pane.dataset.inventoryPane !== section;
  });
}

const PROVIDER_ASSISTANT_UNDO_TTL_MS = 10 * 60 * 1000;
let providerAssistantUndoState = null;
let providerAssistantClientLookup = new Map();
let providerAssistantClientKeys = new Map();
let providerAssistantClientKeyGeneration = -1;
let providerAssistantNextClientKey = 1;

function providerAssistantOpenBookingId() {
  const sheet = $('#bookingSheet');
  return sheet && !sheet.hidden ? String(sheet.dataset.bookingId || '') : '';
}

function providerAssistantScreenContext(readable = false, offline = false) {
  const view = String($('#dashboard')?.dataset.activeView || providerViewFromLocation() || 'bookings');
  const viewLabel = ({
    bookings:'Записи', clients:'Клиенты', messages:'Сообщения', notifications:'Уведомления', waitlist:'Лист ожидания', analytics:'Статистика',
    schedule:'Рабочие часы', services:'Услуги', organization:'Организация', portfolio:'Портфолио', settings:'Настройки'
  })[view] || 'Кабинет';
  const bookingId = providerAssistantOpenBookingId();
  const item = readable && bookingId ? allBookings.find(entry => String(entry.id || '') === bookingId && !isScheduleBlock(entry)) : null;
  return {
    view,
    viewLabel,
    selectedDate:String(selectedDate || ''),
    surface:String($('#bookingSheet')?.dataset.assistantContext || ''),
    booking:item ? {
      id:String(item.id || ''),
      clientName:offline ? 'Клиент' : String(item.client_name || 'Клиент'),
      date:String(item.booking_date || ''),
      time:String(item.booking_time || '').slice(0, 5),
      durationMinutes:providerAssistantNumber(item.duration_minutes || item.services?.duration_minutes, 60, 1, 480),
      serviceId:String(item.service_id || ''),
      serviceName:serviceName(item.services?.name || 'Услуга'),
      status:String(item.status || 'confirmed')
    } : null
  };
}

function providerAssistantUndoAvailable() {
  return Boolean(providerAssistantUndoState
    && currentUser?.id === providerAssistantUndoState.userId
    && sessionGeneration === providerAssistantUndoState.sessionGeneration
    && Date.now() <= providerAssistantUndoState.expiresAt);
}

function captureProviderAssistantNavigation() {
  if (!currentUser?.id) return;
  providerAssistantUndoState = {
    userId:currentUser.id,
    sessionGeneration,
    view:String($('#dashboard')?.dataset.activeView || providerViewFromLocation() || 'bookings'),
    selectedDate:String(selectedDate || ''),
    bookingId:providerAssistantOpenBookingId(),
    expiresAt:Date.now() + PROVIDER_ASSISTANT_UNDO_TTL_MS
  };
}

function restoreProviderAssistantNavigation() {
  if (!providerAssistantUndoAvailable()) {
    providerAssistantUndoState = null;
    return { ok:false, reason:'nothing_to_undo' };
  }
  const previous = providerAssistantUndoState;
  providerAssistantUndoState = null;
  closeBookingSheet();
  setProviderView(PROVIDER_VIEW_ORDER.includes(previous.view) ? previous.view : 'bookings');
  if (providerAssistantIsoDate(previous.selectedDate)) selectScheduleDate(previous.selectedDate);
  if (previous.bookingId && allBookings.some(item => String(item.id || '') === previous.bookingId)) openBookingSheet(previous.bookingId);
  return { ok:true };
}

async function providerAssistantSynthesizeSpeech(payload = {}, externalSignal = null) {
  if (!window.MINUTA_CONFIG.assistantCloudSpeechEnabled) return { ok:false, reason:'not_configured' };
  const generation = sessionGeneration;
  const userId = currentUser?.id;
  if (!userId) return { ok:false, reason:'auth_required' };
  if (!navigator.onLine) return { ok:false, reason:'offline' };
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return { ok:false, reason:'invalid_request' };
  const voice = String(payload.voice || '');
  if (!['dmitry', 'svetlana'].includes(voice)) return { ok:false, reason:'invalid_voice' };
  const text = Array.from(String(payload.text || '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim()).slice(0, 1200).join('').trim();
  const body = { text, voice };
  if (!text || new TextEncoder().encode(JSON.stringify(body)).byteLength > 4 * 1024) return { ok:false, reason:'invalid_request' };
  const { data:sessionData, error:sessionError } = await db.auth.getSession();
  const accessToken = sessionData?.session?.access_token || '';
  if (sessionError || !accessToken || !sessionIsCurrent(userId, generation) || sessionData?.session?.user?.id !== userId) return { ok:false, reason:'stale_session' };
  const controller = new AbortController();
  const relayAbort = () => controller.abort(externalSignal?.reason);
  if (externalSignal?.aborted) relayAbort();
  else externalSignal?.addEventListener?.('abort', relayAbort, { once:true });
  const timeoutId = setTimeout(() => controller.abort(new DOMException('Timed out', 'TimeoutError')), 10000);
  let response;
  try {
    response = await fetch(`${window.MINUTA_CONFIG.supabaseUrl}/functions/v1/assistant-speech`, {
      method:'POST',
      headers:{
        apikey:window.MINUTA_CONFIG.supabaseKey,
        authorization:`Bearer ${accessToken}`,
        'content-type':'application/json'
      },
      body:JSON.stringify(body),
      cache:'no-store',
      credentials:'omit',
      referrerPolicy:'no-referrer',
      signal:controller.signal
    });
  } catch {
    return { ok:false, reason:controller.signal.aborted ? (externalSignal?.aborted ? 'cancelled' : 'timeout') : 'request_failed' };
  } finally {
    clearTimeout(timeoutId);
    externalSignal?.removeEventListener?.('abort', relayAbort);
  }
  if (!sessionIsCurrent(userId, generation)) return { ok:false, reason:'stale_session' };
  if (!response.ok) return { ok:false, reason:response.status === 429 ? 'rate_limited' : response.status === 503 ? 'not_configured' : 'request_failed' };
  const contentType = String(response.headers.get('content-type') || '').toLowerCase();
  const audio = await response.blob();
  if (!contentType.startsWith('audio/') || !audio.size || audio.size > 2 * 1024 * 1024) return { ok:false, reason:'invalid_response' };
  return { ok:true, audio };
}

window.MinutaProviderAssistant = Object.freeze({
  remoteUnderstandingEnabled:Boolean(window.MINUTA_CONFIG.assistantRemoteUnderstanding),
  cloudSpeechEnabled:Boolean(window.MINUTA_CONFIG.assistantCloudSpeechEnabled),
  synthesizeSpeech:providerAssistantSynthesizeSpeech,
  getAssistantLexicon:providerAssistantLexicon,
  rememberAssistantCorrections:rememberProviderAssistantCorrections,
  getAssistantPreferences:providerAssistantPreferences,
  rememberAssistantPreference:rememberProviderAssistantPreference,
  clearAssistantPreferences:clearProviderAssistantPreferences,
  getReadOnlySnapshot() {
    const organization = organizationController.getActiveOrganization();
    const inventoryPayload = inventoryController?.payload;
    const snapshotTime = new Date(bookingsSnapshotSavedAt).getTime();
    const snapshotCurrent = Number.isFinite(snapshotTime) && Date.now() - snapshotTime <= PROVIDER_CACHE_MAX_AGE;
    const synchronized = Boolean(currentUser && bookingCreationReady && navigator.onLine && snapshotCurrent && !bookingsSnapshotFromCache);
    const offline = Boolean(currentUser && !navigator.onLine);
    const offlineReadable = Boolean(offline && snapshotCurrent);
    const readable = synchronized || offlineReadable;
    const inventoryReady = Boolean(readable
      && inventoryPayload
      && inventoryController.availability === 'ready'
      && organization?.id
      && String(inventoryPayload.organization_id || '') === String(organization.id));
    if (providerAssistantClientKeyGeneration !== sessionGeneration) {
      providerAssistantClientKeys = new Map();
      providerAssistantClientKeyGeneration = sessionGeneration;
      providerAssistantNextClientKey = 1;
    }
    providerAssistantClientLookup = new Map();
    const clientKey = item => {
      if (offline) return '';
      const phone = normalizePhone(item.client_phone);
      if (!phone) return '';
      if (!providerAssistantClientKeys.has(phone)) providerAssistantClientKeys.set(phone, `client-${providerAssistantNextClientKey++}`);
      const key = providerAssistantClientKeys.get(phone);
      providerAssistantClientLookup.set(key, { phone, userId:currentUser.id, sessionGeneration });
      return key;
    };
    const marks = notificationMarks();
    const now = new Date();
    const nextDay = new Date(now.getTime() + 86400000);
    const notificationTasks = readable ? buildNotificationTasks().map(task => ({ ...task, mark:marks[task.key] || '' })) : [];
    const screen = providerAssistantScreenContext(readable, offline);
    return {
      authenticated:Boolean(currentUser),
      synchronized,
      offline,
      offlineReadable,
      readOnly:true,
      lastUpdatedAt:readable ? bookingsSnapshotSavedAt : '',
      snapshotSource:!readable ? 'unavailable' : bookingsSnapshotFromCache ? 'cache' : 'live',
      sessionGeneration,
      today:businessTodayIso(),
      currentMinute:providerAssistantCurrentMinute(),
      selectedDate,
      organizationName:readable ? String(organization?.name || '') : '',
      currentRole:readable ? String(organization?.current_role || '') : '',
      canManage:Boolean(readable && organization?.can_manage),
      screen,
      undoAvailable:providerAssistantUndoAvailable(),
      assistantPreferences:providerAssistantPreferences(),
      dataQuality:{
        bookings:readable ? (bookingsSnapshotFromCache ? 'anonymized_cache' : 'server') : 'unavailable',
        outcomes:outcomesRemoteAvailable ? 'server' : bookingOutcomes.size ? 'local_fallback' : 'unavailable',
        notifications:notificationOutboxRemoteAvailable ? 'server' : 'local_fallback',
        team:readable && organizationController.availability === 'ready' ? 'server' : 'unavailable',
        inventory:inventoryReady ? 'server' : 'unavailable'
      },
      services:(readable ? ownServices : []).filter(item => item.active).map(item => ({
        id:String(item.id),
        name:serviceName(item.name || 'Услуга'),
        durationMinutes:providerAssistantNumber(item.duration_minutes, 60, 1, 480),
        defaultDurationMinutes:Number(item.duration_minutes) === 1 ? serviceDefaultDuration(item.id) : providerAssistantNumber(item.duration_minutes, 60, 1, 480),
        priceRub:providerAssistantNumber(item.price_rub),
        perMinute:Number(item.duration_minutes) === 1
      })),
      bookings:(readable ? allBookings : []).filter(item => !isScheduleBlock(item)).map(item => ({
        id:String(item.id || ''),
        outcome:bookingOutcome(item).visit_status,
        paymentMethod:bookingOutcome(item).payment_method,
        amountRub:providerAssistantNumber(bookingOutcome(item).amount_rub),
        clientName:offline ? 'Клиент' : String(item.client_name || 'Клиент'),
        clientKey:clientKey(item),
        date:String(item.booking_date || ''),
        time:String(item.booking_time || '').slice(0, 5),
        durationMinutes:providerAssistantNumber(item.duration_minutes || item.services?.duration_minutes, 60, 1, 480),
        serviceId:String(item.service_id || ''),
        serviceName:serviceName(item.services?.name || 'Услуга'),
        status:String(item.status || 'confirmed')
      })),
      team:(readable ? organization?.members || [] : []).filter(item => item.active).map(item => ({
        name:String(item.display_name || 'Сотрудник'),
        role:String(item.role || '')
      })),
      notifications:readable ? {
        available:notificationSettingsRemoteAvailable || notificationOutboxRemoteAvailable,
        failed:notificationOutbox.filter(item => item.status === 'failed').length,
        pending:notificationOutbox.filter(item => item.status === 'pending' || item.status === 'sending').length,
        manualDue:notificationTasks.filter(task => task.dueAt <= now && task.mark !== 'sent').length,
        manualDueWithin24Hours:notificationTasks.filter(task => task.dueAt > now && task.dueAt <= nextDay && task.mark !== 'sent').length
      } : null,
      inventory:inventoryReady ? {
        enabled:Boolean(inventoryPayload.enabled),
        items:(inventoryPayload.items || []).filter(item => item.active).map(item => ({
          id:String(item.id),
          name:String(item.name || 'Материал'),
          unit:String(item.unit || ''),
          quantity:(inventoryPayload.balances || []).filter(row => String(row.inventory_item_id) === String(item.id)).reduce((sum, row) => sum + providerAssistantNumber(row.quantity), 0),
          lowStockThreshold:providerAssistantNumber(item.low_stock_threshold)
        })),
        usage:(inventoryPayload.usage || []).map(item => ({
          serviceId:String(item.service_id || ''),
          itemId:String(item.inventory_item_id || ''),
          quantity:providerAssistantNumber(item.quantity)
        }))
      } : null
      };
  },
  async understandCommand(payload = {}) {
    if (!window.MINUTA_CONFIG.assistantRemoteUnderstanding) return { ok:false, reason:'not_configured' };
    const generation = sessionGeneration;
    const userId = currentUser?.id;
    if (!userId) return { ok:false, reason:'auth_required' };
    if (!navigator.onLine || !bookingCreationReady || bookingsSnapshotFromCache) return { ok:false, reason:'not_synchronized' };
    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return { ok:false, reason:'invalid_request' };
    const command = String(payload.command || '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 500);
    const context = payload.context && typeof payload.context === 'object' && !Array.isArray(payload.context) ? payload.context : {};
    const history = (Array.isArray(payload.history) ? payload.history : []).slice(-6).map(item => ({
      role:item?.role === 'assistant' ? 'assistant' : 'user',
      text:String(item?.text || '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 500)
    })).filter(item => item.text);
    const body = { command, context, history };
    if (!command || new TextEncoder().encode(JSON.stringify(body)).byteLength > 24 * 1024) return { ok:false, reason:'invalid_request' };
    const { data:sessionData, error:sessionError } = await db.auth.getSession();
    if (sessionError || !sessionIsCurrent(userId, generation) || sessionData?.session?.user?.id !== userId) return { ok:false, reason:'stale_session' };
    let timeoutId;
    let result;
    try {
      result = await Promise.race([
        db.functions.invoke('assistant-understand', { body }),
        new Promise((_, reject) => { timeoutId = setTimeout(() => reject(new Error('assistant_timeout')), 10000); })
      ]);
    } catch {
      return { ok:false, reason:'request_failed' };
    } finally {
      clearTimeout(timeoutId);
    }
    if (!sessionIsCurrent(userId, generation)) return { ok:false, reason:'stale_session' };
    if (result?.error || !result?.data?.ok || !result.data.analysis || typeof result.data.analysis !== 'object') return { ok:false, reason:String(result?.data?.reason || 'request_failed') };
    return { ok:true, analysis:result.data.analysis };
  },
  openSection(section = '') {
    const allowed = new Set(['bookings', 'clients', 'messages', 'notifications', 'waitlist', 'schedule', 'services', 'organization', 'analytics', 'portfolio', 'settings']);
    const view = String(section || '');
    if (!currentUser || !allowed.has(view)) return { ok:false, reason:'invalid_request' };
    captureProviderAssistantNavigation();
    setProviderView(view);
    return { ok:true };
  },
  openClient(request = {}) {
    const key = String(request?.clientKey || '');
    const expectedGeneration = Number(request?.sessionGeneration);
    const target = providerAssistantClientLookup.get(key);
    if (!currentUser || !key || !target || target.userId !== currentUser.id || target.sessionGeneration !== sessionGeneration || expectedGeneration !== sessionGeneration) return { ok:false, reason:'stale_session' };
    if (!buildClients().some(item => item.phone === target.phone)) return { ok:false, reason:'not_found' };
    captureProviderAssistantNavigation();
    const transition = setProviderView('clients');
    const showClient = () => {
      setClientProfileDetailMode(true);
      renderClientDetail(target.phone);
    };
    if (transition?.updateCallbackDone?.then) transition.updateCallbackDone.then(showClient).catch(showClient);
    else showClient();
    return { ok:true };
  },
  undoLastAssistantStep() {
    return restoreProviderAssistantNavigation();
  },
  async findGeneralAvailability(plan = {}) {
    const generation = sessionGeneration;
    const userId = currentUser?.id;
    if (!userId) return { ok:false, reason:'auth_required', windows:[] };
    if (!navigator.onLine || !bookingCreationReady || bookingsSnapshotFromCache) return { ok:false, reason:'not_synchronized', windows:[] };
    if (!plan || typeof plan !== 'object' || Array.isArray(plan)) return { ok:false, reason:'invalid_request', windows:[] };
    const date = providerAssistantIsoDate(plan.date);
    const today = businessTodayIso();
    const latest = new Date(`${today}T12:00:00+04:00`);
    latest.setUTCDate(latest.getUTCDate() + 730);
    if (!date || date < today || date > businessTodayIso(latest)) return { ok:false, reason:'invalid_request', windows:[] };
    const { data:sessionData, error:sessionError } = await db.auth.getSession();
    if (sessionError || !sessionIsCurrent(userId, generation) || sessionData?.session?.user?.id !== userId) return { ok:false, reason:'stale_session', windows:[] };
    try {
      const context = await getFreeSlotsServerContext();
      if (!sessionIsCurrent(userId, generation) || context.performerId !== userId) return { ok:false, reason:'stale_session', windows:[] };
      const locations = (Array.isArray(context.locations) ? context.locations : []).filter(item => item?.id);
      if (context.resourceScheduling && locations.length !== 1) return { ok:false, reason:'location_required', windows:[] };
      const locationId = context.resourceScheduling ? String(locations[0].id) : '';
      const result = await getFreeSlotsGeneralAvailability({ context, locationId, from:date, to:date });
      if (!sessionIsCurrent(userId, generation)) return { ok:false, reason:'stale_session', windows:[] };
      const windows = (Array.isArray(result?.data) ? result.data : [])
        .filter(item => String(item?.booking_date || '') === date)
        .map(item => ({
          startTime:String(item.start_time || '').slice(0, 5),
          endTime:String(item.end_time || '').slice(0, 5),
          durationMinutes:providerAssistantNumber(item.duration_minutes, 0, 0, 1440)
        }))
        .filter(item => /^([01]\d|2[0-3]):[0-5]\d$/.test(item.startTime)
          && /^([01]\d|2[0-3]):[0-5]\d$/.test(item.endTime)
          && minutesFromTime(item.endTime) > minutesFromTime(item.startTime)
          && item.durationMinutes > 0)
        .slice(0, 12);
      return { ok:true, windows };
    } catch {
      return { ok:false, reason:'request_failed', windows:[] };
    }
  },
  prepareBookingOperation(plan = {}) {
    const synchronized = Boolean(currentUser && navigator.onLine && bookingCreationReady && !bookingsSnapshotFromCache);
    if (!synchronized) return { ok:false, reason:'not_synchronized' };
    if (!plan || typeof plan !== 'object' || Array.isArray(plan)) return { ok:false, reason:'invalid_request' };
    const item = allBookings.find(booking => String(booking.id) === String(plan.bookingId || ''));
    if (!item || isScheduleBlock(item) || item.status === 'cancelled' || bookingOutcome(item).visit_status === 'completed') return { ok:false, reason:'invalid_request' };
    if (plan.operation === 'cancel') {
      captureProviderAssistantNavigation();
      setProviderView('bookings');
      selectScheduleDate(item.booking_date);
      openBookingSheet(item.id);
      return { ok:true, confirmationRequired:true };
    }
    const date = providerAssistantIsoDate(plan.targetDate);
    const time = /^([01]\d|2[0-3]):[0-5]\d$/.test(String(plan.targetTime || '')) ? String(plan.targetTime) : '';
    if (plan.operation !== 'reschedule' || !date || date < businessTodayIso() || !time) return { ok:false, reason:'invalid_request' };
    captureProviderAssistantNavigation();
    setProviderView('bookings');
    selectScheduleDate(item.booking_date);
    openBookingEditor(item.id, { date, time });
    return { ok:true, confirmationRequired:true };
  },
  async findAvailableSlots(plan = {}) {
    const generation = sessionGeneration;
    const userId = currentUser?.id;
    if (!userId) return { ok:false, reason:'auth_required', slots:[] };
    if (!navigator.onLine || !bookingCreationReady || bookingsSnapshotFromCache) return { ok:false, reason:'not_synchronized', slots:[] };
    if (!plan || typeof plan !== 'object' || Array.isArray(plan)) return { ok:false, reason:'invalid_request', slots:[] };
    const service = ownServices.find(item => item.active && String(item.id) === String(plan.serviceId || ''));
    const date = providerAssistantIsoDate(plan.date);
    const today = businessTodayIso();
    const latest = new Date(`${today}T12:00:00+04:00`);
    latest.setUTCDate(latest.getUTCDate() + 730);
    if (!service || !date || date < today || date > businessTodayIso(latest)) return { ok:false, reason:'invalid_request', slots:[] };
    const fixedDuration = providerAssistantNumber(service.duration_minutes, 60, 1, 480);
    const requestedDuration = Number(service.duration_minutes) === 1 ? Number(plan.durationMinutes || serviceDefaultDuration(service.id)) : fixedDuration;
    if (!Number.isFinite(requestedDuration) || !Number.isInteger(requestedDuration) || requestedDuration < 1 || requestedDuration > 480) return { ok:false, reason:'invalid_request', slots:[] };
    const duration = requestedDuration;
    const { data:sessionData, error:sessionError } = await db.auth.getSession();
    if (sessionError || !sessionIsCurrent(userId, generation) || sessionData?.session?.user?.id !== userId) return { ok:false, reason:'stale_session', slots:[] };
    const { data, error } = await getProviderAvailableSlots({ p_service:service.id, p_start:date, p_end:date });
    if (!sessionIsCurrent(userId, generation)) return { ok:false, reason:'stale_session', slots:[] };
    if (error) return { ok:false, reason:'request_failed', slots:[] };
    const currentMinute = date === today ? providerAssistantCurrentMinute() : -1;
    const slots = (Array.isArray(data) ? data : [])
      .filter(item => String(item?.booking_date || '') === date)
      .map(item => String(item.booking_time || '').slice(0, 5))
      .filter(time => /^([01]\d|2[0-3]):[0-5]\d$/.test(time)
        && minutesFromTime(time) > currentMinute);
    return { ok:true, slots:[...new Set(slots)].sort(), durationMinutes:duration };
  },
  prepareBookingDraft(plan = {}) {
    const snapshotTime = new Date(bookingsSnapshotSavedAt).getTime();
    const offlineDraftAllowed = Boolean(currentUser && !navigator.onLine && Number.isFinite(snapshotTime) && Date.now() - snapshotTime <= PROVIDER_CACHE_MAX_AGE);
    const synchronized = Boolean(currentUser && navigator.onLine && bookingCreationReady && !bookingsSnapshotFromCache);
    if (!synchronized && !offlineDraftAllowed) return { ok:false, reason:'not_synchronized' };
    if (!plan || typeof plan !== 'object' || Array.isArray(plan)) return { ok:false, reason:'invalid_request' };
    const date = providerAssistantIsoDate(plan.date);
    const time = /^([01]\d|2[0-3]):[0-5]\d$/.test(String(plan.time || '')) ? String(plan.time) : '';
    const service = ownServices.find(item => item.active && String(item.id) === String(plan.serviceId || '')) || null;
    if (!date || date < businessTodayIso() || (plan.serviceId && !service)) return { ok:false, reason:'invalid_request' };
    const durationMinutes = service && Number(service.duration_minutes) === 1
      ? providerAssistantNumber(plan.durationMinutes || serviceDefaultDuration(service.id), serviceDefaultDuration(service.id), 1, 480)
      : undefined;
    captureProviderAssistantNavigation();
    setProviderView('bookings');
    selectScheduleDate(date);
    openNewBookingSheet(time, {
      clientName:String(plan.clientName || '').trim().slice(0, 80),
      serviceId:service?.id || '',
      date,
      durationMinutes
    });
    if (offlineDraftAllowed) {
      saveNewBookingDraft();
      const draftStatus = $('#newBookingDraftStatus');
      if (draftStatus) draftStatus.textContent = 'Офлайн-черновик сохранён в этой вкладке · время проверим после подключения';
      applyWriteAvailability();
    }
    return { ok:true, offline:offlineDraftAllowed };
  }
});
